INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(172906, 'frFR', 'Autant que l\’argent sorte de sa poche plutôt que de la mienne. Hah !', '', 29981),
(172905, 'frFR', 'Gazleu a dit qu\’il se chargerait de vous payer. J\’imagine qu\’il détestait ce Grizzek encore plus que moi !', '', 29981),
(172903, 'frFR', 'Bien. Finissons-en.', '', 29981),
(172728, 'frFR', 'Plumes est en train de disjoncter ! Accrochez-vous !', 'Plumes est en train de disjoncter ! Accrochez-vous !', 29981),
(172721, 'frFR', 'Puis-je emprunter votre fil synchrone, Delormi ?', 'Puis-je emprunter votre fil synchrone, Delormi ?', 29981),
(172671, 'frFR', 'Bien sûr ! Croyez-moi, on n\’a pas encore vu les limites du Cœur d\’Azeroth !', '', 29981),
(172670, 'frFR', 'Magni, pensez-vous que le Cœur d\’Azeroth puisse devenir encore plus puissant ?', 'Magni, pensez-vous que le Cœur d\’Azeroth puisse devenir encore plus puissant ?', 29981),
(172622, 'frFR', '', 'Permets-nous de baigner dans ta gloire, afin que nous puissions protéger nos enfants.', 29981),
(172621, 'frFR', '', 'Accorde ta bénédiction à ces instruments…', 29981),
(172620, 'frFR', '', 'Élune, entends ma prière…', 29981),
(172619, 'frFR', 'Accorde-nous ta faveur, afin que nous puissions mieux protéger nos enfants.', '', 29981),
(172618, 'frFR', 'Fais-nous grâce de ta générosité.', '', 29981),
(172617, 'frFR', 'Terre-Mère, accorde-nous ton aide.', '', 29981),
(172614, 'frFR', 'À laquelle de ces statues de mauvais goût souhaitez-vous rendre visite ?', 'À laquelle de ces statues de mauvais goût souhaitez-vous rendre visite ?', 29981),
(172613, 'frFR', 'Dirigez-vous vers les escaliers de la terrasse où se trouve tous les sanctuaires, c\’est là que vous le trouverez.', 'Dirigez-vous vers les escaliers de la terrasse où se trouve tous les sanctuaires, c\’est là que vous le trouverez.', 29981),
(172612, 'frFR', 'Une grenouille ? Ridicule. En tout cas, vous la trouverez près des artisans dans le coin nord-ouest.', 'Une grenouille ? Ridicule. En tout cas, vous la trouverez près des artisans dans le coin nord-ouest.', 29981),
(172611, 'frFR', 'Dirigez-vous vers les escaliers de la terrasse où se trouve tous les sanctuaires, c\’est là que vous le trouverez.', 'Dirigez-vous vers les escaliers de la terrasse où se trouve tous les sanctuaires, c\’est là que vous le trouverez.', 29981),
(172610, 'frFR', 'L\’autel du squelette parlant se trouve à l\’ouest de ce rocher.', 'L\’autel du squelette parlant se trouve à l\’ouest de ce rocher.', 29981),
(172609, 'frFR', 'Je crois qu\’il se trouve près du Grand Sceau.', 'Je crois qu\’il se trouve près du Grand Sceau.', 29981),
(172608, 'frFR', 'Vous trouverez l\’autel du dieu félin à l\’est de la pyramide.', 'Vous trouverez l\’autel du dieu félin à l\’est de la pyramide.', 29981),
(172581, 'frFR', '', 'Je vais observer la façon dont vous manipulez le fil pour voir si vous êtes digne de devenir $guntailleur synchrone:une couturière synchrone;.', 29981),
(172576, 'frFR', '', 'Avant que vous ne partiez… je crois avoir découvert comment obtenir la lentille que le Terrestre utilisait sur les sanctuaires.', 29981),
(172575, 'frFR', '', 'En Kul Tiras, précisément. Vous pourriez peut-être accompagner la brigade de l\’Honneur lors de sa prochaine incursion.', 29981),
(172574, 'frFR', '', 'Je pense avoir déterminé l\’emplacement de certains d\’entre eux, mais hélas, ils se trouvent en territoire hostile.', 29981),
(172573, 'frFR', '', 'J\’ai profité de votre absence pour parcourir le journal et tenter de localiser d\’autres sanctuaires.', 29981),
(172522, 'frFR', 'Le sanctuaire de Pa\’ku se trouve au pied des escaliers qui mènent à la terrasse des Prédicateurs.', 'Le sanctuaire de Pa\’ku se trouve au pied des escaliers qui mènent à la terrasse des Prédicateurs.', 29981),
(172521, 'frFR', 'Le sanctuaire de Krag\’wa se trouve à l\’angle nord-ouest de la pyramide, près de la terrasse de l\’Artisanat.', 'Le sanctuaire de Krag\’wa se trouve à l\’angle nord-ouest de la pyramide, près de la terrasse de l\’Artisanat.', 29981),
(172520, 'frFR', 'Le sanctuaire de Kimbul surplombe la jungle, à l\’est de la pyramide.', 'Le sanctuaire de Kimbul surplombe la jungle, à l\’est de la pyramide.', 29981),
(172519, 'frFR', 'Le sanctuaire de Gonk est au pied des escaliers qui mènent vers la terrasse des Prédicateurs.', 'Le sanctuaire de Gonk est au pied des escaliers qui mènent vers la terrasse des Prédicateurs.', 29981),
(172518, 'frFR', 'Le sanctuaire de Bwonsamdi se trouve sur l\’escalier à l\’extrémité ouest de la pyramide.', 'Le sanctuaire de Bwonsamdi se trouve sur l\’escalier à l\’extrémité ouest de la pyramide.', 29981),
(172517, 'frFR', 'Vous trouverez un sanctuaire d\’Akunda sur les marches à l\’est du Grand Sceau.', 'Vous trouverez un sanctuaire d\’Akunda sur les marches à l\’est du Grand Sceau.', 29981),
(172516, 'frFR', '', 'Pour finir, vous devez accomplir le rituel de lien.', 29981),
(172496, 'frFR', 'C\’est quel sanctuaire qui vous intéresse ?', 'C\’est quel sanctuaire qui vous intéresse ?', 29981),
(172489, 'frFR', 'Sanctuaire de Pa\’ku', 'Sanctuaire de Pa\’ku', 29981),
(172488, 'frFR', 'Sanctuaire de Krag\’wa', 'Sanctuaire de Krag\’wa', 29981),
(172487, 'frFR', 'Sanctuaire de Kimbul', 'Sanctuaire de Kimbul', 29981),
(172486, 'frFR', 'Sanctuaire de Gonk', 'Sanctuaire de Gonk', 29981),
(172485, 'frFR', 'Sanctuaire de Bwonsamdi', 'Sanctuaire de Bwonsamdi', 29981),
(172484, 'frFR', 'Sanctuaire d\’Akunda', 'Sanctuaire d\’Akunda', 29981),
(172483, 'frFR', 'Les sanctuaires des Loas', 'Les sanctuaires des Loas', 29981),
(172475, 'frFR', 'Vos épreuves vous attendent. Plongez-vous dans ces ouvrages pour recueillir le savoir dont vous avez besoin.', '', 29981),
(172437, 'frFR', '%s et $n se sont télescopés, causant une éruption gigantesque !', '%s et $n se sont télescopés, causant une éruption gigantesque !', 29981),
(172436, 'frFR', 'La Résonance instable |2 %s a expiré, causant une éruption gigantesque !', 'La Résonance instable |2 %s a expiré, causant une éruption gigantesque !', 29981),
(172435, 'frFR', '|TInterface\\Icons\\SPELL_SHADOW_DEATHSEMBRACE:20|t|cFFFF0000%s|r commence à lancer |cFFFF0000|Hspell:293653|h[Résonance instable]|h|r !', '', 29981),
(172433, 'frFR', 'Peut-être en trouverez-vous certains qui peuvent encore être sauvés.', '', 29981),
(172432, 'frFR', 'Je vous conseille de partir vers l\’est. La cime Enneigée regorge de yétis particulièrement féroces qui s\’en prennent régulièrement aux cerfs pour les dévorer.', '', 29981),
(172431, 'frFR', 'Pour cette épreuve, vous aurez besoin de trouver une créature blessée et de la soigner. Évidemment, il vous en coûtera de votre propre force vitale.', '', 29981),
(172429, 'frFR', 'Que dois-je faire de l\’écrit de sacrifice ?', 'Que dois-je faire de l\’écrit de sacrifice ?', 29981),
(172428, 'frFR', 'Vos épreuves vous attendent dans les livres autour de moi. Choisissez celui que vous souhaitez.', '', 29981),
(172413, 'frFR', 'Vous allez payer pour vos accusations sans fondement !', '', 29981),
(172412, 'frFR', 'Comment ça, « triché » ? Quelle grossièreté !', '', 29981),
(172411, 'frFR', 'C\’était mes dés préférés, espèce de sauvage !', '', 29981),
(172410, 'frFR', 'Comment ça, vous ne prenez pas en compte mon action ?!', '', 29981),
(172409, 'frFR', 'Bienvenue dans ma boutique, $r. Puis-je vous proposer le tissu le plus raffiné que vous ayez jamais vu ?$b$bOu peut-être souhaitez-vous apprendre comment transformer ce merveilleux tissu en équipement puissant ?', '', 29981),
(172408, 'frFR', 'Hé, $gfrangin:frangine;, vous voulez faire de jolies choses avec du cuir ?$b$bAlors cherchez plus. Le meilleur maître en la matière, c\’est moi.', '', 29981),
(172407, 'frFR', 'Comment ça va, $c ? Vous voulez faire des explosions encore plus grosses qu\’en Silithus ?$b$bAlors ne cherchez pas plus loin. Je suis le Gobelin qui transformera vos rêves explosifs en réalité !$b$bAllez-y, jetez un coup d\’œil !', '', 29981),
(172403, 'frFR', 'Cela vous dérangerait-il de jouer avec mes dés ?', '', 29981),
(172402, 'frFR', 'Allez, jolis dés, ne me décevez pas !', '', 29981),
(172401, 'frFR', 'Allez, mes dés du bonheur ! Papa a vraiment besoin de gagner !', '', 29981),
(172399, 'frFR', 'Vous avez terminé votre formation. Rendez-vous maintenant auprès des griffons, à l\’arrière du vaisseau.', 'Vous avez terminé votre formation. Rendez-vous maintenant auprès des griffons, à l\’arrière du vaisseau.', 29981),
(172397, 'frFR', 'On va vous faire cette enclume en un clin d\’œil !$b$bMais euh… gardez cette information pour vous, tant que ce n\’est pas terminé.', '', 29981),
(172391, 'frFR', 'Vous avez terminé votre formation. Rendez-vous maintenant auprès des wyvernes, à l\’arrière du vaisseau.', 'Vous avez terminé votre formation. Rendez-vous maintenant auprès des wyvernes, à l\’arrière du vaisseau.', 29981),
(172380, 'frFR', 'Je sens beaucoup de colère et de frustration parmi les gens présents aujourd\’hui. Sur ma terre natale, de telles émotions se manifestaient en des menaces bien réelles quand nous nous consacrions trop de temps et d\’énergie à les refouler.\n\nBaine devait agir, ou sa colère aurait été une menace encore plus grande pour la Horde.\n\nNous devrions tous en tirer une leçon.', '', 29981),
(172365, 'frFR', '', 'Je me demande si Zukashi, il attendait pas que j\’utilise ces bulles pour voir ce que ça me ferait. Il est resté un grand enfant.', 29981),
(172364, 'frFR', '', 'Pouah, je crois que j\’ai besoin d\’un bain.', 29981),
(172363, 'frFR', '', 'Eh bien. Ces ingrédients, ça devait pas être les bons. Processus par élimination, tout ça. Pas vrai, $n ?', 29981),
(172362, 'frFR', 'C\’est un grand enfant. Maintenant que j\’y pense, je me demande s\’il attendait que j\’utilise ces bulles pour voir ce qui se passerait.', '', 29981),
(172361, 'frFR', 'C\’est du Quentin tout craché d\’utiliser un ingrédient qui pourrait avoir un tel effet.', '', 29981),
(172360, 'frFR', 'Eh bien, si on ne réussit pas du premier coup, il faut réessayer encore et encore, pas vrai ? Nous éliminerons au moins les mauvais ingrédients de la liste.', '', 29981),
(172354, 'frFR', 'Dites donc, qu\’est-ce qu\’il y a dans votre poche ?$b$bSerait-ce une de mes pierres de transmutation ?! Bon sang. Laquelle avez-vous eue ?$b$b<Vous montrez la pierre à Silas.>$b$bHaha oui, elle est drôle, celle-là. Je crois même avoir tenté d\’en vendre la recette…$b$bEh bien, j\’espère que vous l\’apprécierez ! Et n\’oubliez pas de faire un tour dans ma foire. Elle recèle des merveilles dignes de vos rêves les plus fous !', '', 29981),
(172353, 'frFR', 'En fait… Hati me manque, je dois bien le reconnaître. Cette bête a un cœur en or, ou je ne m\’y connais pas.', '', 29981),
(172352, 'frFR', 'Ha ! Il nous aime bien !', '', 29981),
(172350, 'frFR', 'Nous devrons terminer plus tard, Barbe-de-Bronze. $p est enfin $uarrivé:arrivée; !', '', 29981),
(172342, 'frFR', '', 'Parler avec Derek après tant d\’années…\n\n<Jaina secoue la tête.>\n\nCela donne à réfléchir.', 29981),
(172341, 'frFR', 'Nous avons beaucoup à enseigner aux Orcs de ce monde.', 'Nous avons beaucoup à enseigner aux Orcs de ce monde.', 29981),
(172340, 'frFR', 'Je rêve toujours de Draenor. Est-ce que mon foyer existe toujours ?\n\nRaah. Ça ne sert à rien de ressasser ces choses-là.', 'Je rêve toujours de Draenor. Est-ce que mon foyer existe toujours ?\n\nRaah. Ça ne sert à rien de ressasser ces choses-là.', 29981),
(172339, 'frFR', 'Lok\’tar ogar !', 'Lok\’tar ogar !', 29981),
(172338, 'frFR', 'Le chef de guerre Hurlenfer est très probablement mort. Si c\’est le cas, il est tombé en héros.', 'Le chef de guerre Hurlenfer est très probablement mort. Si c\’est le cas, il est tombé en héros.', 29981),
(172337, 'frFR', 'Ce monde empeste la corruption.', 'Ce monde empeste la corruption.', 29981),
(172336, 'frFR', 'Si ces traîtres d\’empreints de Lumière viennent dans notre monde, je serai prêt !', 'Si ces traîtres d\’empreints de Lumière viennent dans notre monde, je serai prête !', 29981),
(172335, 'frFR', 'Qu\’est-il arrivé à nos frères et sœurs ?', 'Qu\’est-il arrivé à nos frères et sœurs ?', 29981),
(172334, 'frFR', 'Le commandant Geya\’rah était le bras droit du chef de guerre. Il n\’y a pas d\’Orque plus brave ici.', 'Le commandant Geya\’rah était le bras droit du chef de guerre. Il n\’y a pas d\’Orque plus brave ici.', 29981),
(172333, 'frFR', '', 'Il est bon de rentrer chez soi.', 29981),
(172275, 'frFR', 'Vous êtes là depuis longtemps ?', '', 29981),
(172274, 'frFR', '', 'Savez-vous en quelle année nous sommes ?', 29981),
(172242, 'frFR', 'Ça fait un moment que je vous observe, $p.', '', 29981),
(172239, 'frFR', 'Également en lice : sir Phillip Carter Tracey !', '', 29981),
(172216, 'frFR', '', 'Je dispose de peu de temps, malheureusement. Je dois partir. Ce fut un plaisir de vous rencontrer.', 29981),
(172215, 'frFR', '', 'Ah, quelle époque intéressante. Voyons, à en juger par vos vêtements, nous nous situons en…\n\nOui, c\’est cette période. Excellent ! Eh bien, $gcher:chère; collègue $gtailleur:couturière;, si ma compagnie n\’est pas votre seule motivation, peut-être voudrez-vous voir les patrons que j\’ai en stock ?\n\nNe vous inquiétez pas, je ne vous prendrai pas tout votre or. Je suis surtout intéressée par le commerce du tissu.', 29981),
(172198, 'frFR', '%s est le seigneur des Rochenoires !', '', 29981),
(172189, 'frFR', 'Je… Wahou… je ne pensais pas que ça drainerait autant d\’énergie. Je dois me reposer un peu.', '', 29981),
(172176, 'frFR', 'Commencez le rituel.', 'Commencez le rituel.', 29981),
(172168, 'frFR', 'Et par « attirés », il veut dire qu\’ils vous mangeront $gtout cru:toute crue; si vous avez votre lumière allumée !', '', 29981),
(172167, 'frFR', 'Faites attention aux requins-baleines. Ils semblent attirés par la lumière.', '', 29981),
(172166, 'frFR', 'Ce qu\’il veut dire, c\’est que lorsque vous aurez assez de notes de recherche, vous pourrez venir me voir et je vous donnerai des trucs.', '', 29981),
(172165, 'frFR', 'Votre participation à cette expérience sera dédommagée par une prime.', '', 29981),
(172164, 'frFR', 'Cool, pas vrai ? Ah oui, Edgar, c\’est notre sous-marin.', '', 29981),
(172163, 'frFR', 'Vous recevrez les instructions directement depuis le casque se trouvant dans votre sac à dos.', '', 29981),
(172162, 'frFR', 'Apportez-moi ces créatures et Edgar les analysera.', '', 29981),
(172161, 'frFR', 'Tu ne peux pas dire « phosphorescentes » comme tout le monde ?', '', 29981),
(172160, 'frFR', 'Nous avons identifié trois espèces uniques de créatures luminescentes dans les environs.', '', 29981),
(172158, 'frFR', 'Il est mort. Où est mon paiement ?', 'Il est mort. Où est mon paiement ?', 29981),
(172157, 'frFR', 'De lui, il ne reste qu\’une trainée de poussière dans le désert. D\’infimes particules éparpillées dans le sable. Il est bien mort. Retrouver tous les morceaux m\’a valu un terrible coup de soleil, et quand je les ai finalement tous réunis, je les ai désintégrés une fois de plus pour m\’assurer qu\’il était mort. Alors oui, il est mort, et pour de bon.', 'De lui, il ne reste qu\’une trainée de poussière dans le désert. D\’infimes particules éparpillées dans le sable. Il est bien mort. Retrouver tous les morceaux m\’a valu un terrible coup de soleil, et quand je les ai finalement tous réunis, je les ai désintégrés une fois de plus pour m\’assurer qu\’il était mort. Alors oui, il est mort, et pour de bon.', 29981),
(172156, 'frFR', 'Voilà ce que j\’aime entendre ! C\’est toujours un plaisir de faire affaire avec vous, $p.', '', 29981),
(172155, 'frFR', 'Eh ! $N !\nAlors, ce mauvais investissement, Grizzek Moussemolette, c\’est réglé ?\n\nNe m\’épargnez aucun détail ! Je veux TOUT savoir !', '', 29981),
(172154, 'frFR', 'Dites-lui de courir s\’il approche trop !', '', 29981),
(172153, 'frFR', 'Ne jamais s\’impliquer dans l\’ingénierie politique ! Jamais !', '', 29981),
(172152, 'frFR', 'Et, euh, remerciez Gazleu pour moi, vous voulez bien ? Je lui en dois une, alors voilà un petit conseil pour lui :', '', 29981),
(172151, 'frFR', '', 'N\’oubliez pas, vous n\’avez trouvé personne !', 29981),
(172150, 'frFR', 'Bonjour, Saffy !', '', 29981),
(172149, 'frFR', 'Impact prévu dans approximativement vingt secondes.', '', 29981),
(172148, 'frFR', 'Signal rétabli.', '', 29981),
(172147, 'frFR', 'Signal perdu. Erreur 37. Compensation.', '', 29981),
(172146, 'frFR', 'Tentative de compensation.', '', 29981),
(172145, 'frFR', 'Dégradation du signal. Perturbations atmosphériques détectées.', '', 29981),
(172144, 'frFR', 'Hé ! $p ! Par ici !', '', 29981),
(172143, 'frFR', 'Oubliez pas, je paierai le double !', '', 29981),
(172139, 'frFR', 'Mmhmmh hahahaha HAHAHA !', '', 29981),
(172134, 'frFR', 'Allez, les garçons ! Notre investissement a payé ! Mettons-nous à la recherche d\’un nouveau coup.', '', 29981),
(172130, 'frFR', 'C\’est bon, les garçons, on a été payés ! La première tournée est pour moi.', '', 29981),
(172100, 'frFR', 'Jo\’nok entend l\’appel de la reine des Zandalari.\n\nQue voulez-vous, petite créature ?', '', 29981),
(172099, 'frFR', 'Regardez tous ces tomes, ces parchemins, ces livres !\n\nJe savais que les Zandalari étaient un peuple cultivé, mais il y a assez ici pour me tenir occupé des dizaines d\’années !\n\nLe vieux Torga avait raison, comme d\’habitude. Les aventures étranges font toujours les meilleurs récits.\n\nJ\’ai hâte de voir ce que l\’avenir nous réserve !', '', 29981),
(172098, 'frFR', '', '<La gardelame Kaja est en pleine conversation avec le général Rakera.>', 29981),
(172097, 'frFR', '', '<Le général Rakera est en pleine conversation avec la gardelame Kaja.>', 29981),
(172096, 'frFR', 'Le vent du changement se lève. Est-ce que vous le sentez ?', '', 29981),
(172095, 'frFR', '', 'Ah, $n !\n\nPendant que la reine Talanji s\’acharne à restaurer notre empire, le conseil zanchuli a été chargé de s\’assurer que les loyaux de Zandalar lui donnent le temps de s\’acquitter de sa tâche.\n\nLes prêtres émettent encore quelques doutes, mais le moment venu, ils se rendront compte tout comme moi que Talanji est un bon chef.', 29981),
(172094, 'frFR', '', 'La lumière des Loas brille sur vous, $n.', 29981),
(172093, 'frFR', '', 'Comme l\’aurait dit mon père, il est bon d\’être reine.\n\nIl me manque tous les jours. Avant, je me demandais comment je pourrais être à la hauteur de la tâche. Mais je commence à comprendre que même le plus vieux et le plus sage des Trolls ne peut prévoir ce que l\’avenir nous réserve. Pas même un prophète comme Zul.\n\nLa route devant nous est incertaine, mais les Zandalari releveront les défis qui se présenteront à eux.\n\nÇa, je peux le prédire.', 29981),
(172088, 'frFR', 'Ma sœur ne m\’a pas confié cette tâche pour que je passe mes journées à boire de la bière.\n\nTrès bientôt, nous affronterons la Horde face à face. La mer appelle, comme elle l\’a toujours fait.', '', 29981),
(172087, 'frFR', 'Bonjour, $n.\n\nCette ville est sacrément armée. Je comprends mieux comment elle a pu résister si longtemps.\n\nÇa me rappelle chez moi.', '', 29981),
(172086, 'frFR', '', 'J\’espère juste que nous n\’allons pas jouer les pots de fleurs, $n.\n\nJ\’ai quelques harpons qui n\’attendent que nos amis de la Horde.', 29981),
(172084, 'frFR', 'Heureux de vous revoir, $n !\n\nJ\’espérais que vous repasseriez me voir. C\’est calme par ici, depuis que Dorlan est partie.\n\nNe vous méprenez pas, j\’aime aussi la tranquillité. Et je peux aller à Brennadam chaque fois que l\’envie de faire un brin de causette me prend. Ma femme n\’a jamais été du genre à parler pour ne rien dire, de toute façon.\n\nElle m\’a dit qu\’elle viendrait bientôt me voir. J\’ai hâte.\n\n<Sal se remet à jardiner en fredonnant un air enjoué.>', '', 29981),
(172082, 'frFR', 'À une époque, être un eauracle signifiait naviguer aux quatre coins du monde. J\’ai hâte de voir où nous mèneront ces courants mystérieux.', '', 29981),
(172081, 'frFR', '', 'Thomas Zelling a… avait… une famille. Il m\’a fait promettre de les protéger, même après qu\’il eut été rejeté parce qu\’il était devenu un Mort-vivant. Je tiendrai cette promesse.\n\nS\’ils me demandent un jour ce qui s\’est passé, je leur dirai qu\’il est mort en héros.\nNous autres, Réprouvés, conservons notre libre arbitre après avoir été ranimés. C\’est ce qui nous différencie du Fléau. Autrefois, Sylvanas Coursevent s\’enorgueillissait de cette distinction.\n\nMais après tout ce que j\’ai vu au cours de cette guerre, je me demande si c\’est toujours le cas.', 29981),
(172080, 'frFR', 'Il y a des années, Tirion Fordring a tout sacrifié pour me sauver la vie. C\’était une question d\’honneur. Baine a agi de la même façon et nous allons le punir pour cela ?\n\nJ\’ai bien peur que la Horde soit en train de devenir ce que nous haïssions autrefois, $c… et je n\’aime pas ça.', '', 29981),
(172079, 'frFR', '', 'Vous avez vu ce qui est arrivé à Baine ? Et Zelling ? C\’est pour cela que nous devons faire profil bas et suivre les ordres du chef de guerre. Pour l\’instant du moins.\n\nL\’erreur de Baine n\’a pas été de s\’opposer à Sylvanas, c\’est de l\’avoir fait trop tôt.', 29981),
(172078, 'frFR', 'D\’autres doivent apprendre ce qui s\’est passé, $n.\n\nNous nous en assurerons.', '', 29981),
(172077, 'frFR', '', 'C\’est vraiment pour ça que la Horde se bat ? Emprisonner ceux qui agissent par compassion et honneur ?\n\nMon peuple n\’aurait jamais dû quitter Haut-Roc…', 29981),
(172076, 'frFR', '', 'Notre révolte contre Élisande était justifiée, mais elle m\’a valu d\’être attaquée dans le dos. Je prie que Baine ne connaisse pas le même sort.\n\nLes Sacrenuit ne font pas partie de la Horde depuis longtemps. Peut-être devrais-je demander conseil à Lor\’themar. Il sait ce que mon peuple a vécu. Et j\’ai beaucoup appris en discutant avec lui.', 29981),
(172075, 'frFR', '', 'Ce n\’est pas une Orque, mais le chef de guerre fait preuve de force en punissant le Tauren qui l\’a trahie.\n\nCeux qui n\’ont aucune loyauté n\’ont aucun honneur.', 29981),
(172074, 'frFR', '', 'Sans la Horde à nos côtés, mon peuple serait à la merci de l\’Alliance. Nous devons beaucoup au chef de guerre… mais nous ne la suivrons pas aveuglément.\n\nBaine Sabot-de-Sang a fait preuve d\’honneur et de respect envers les Zandalari. Il devrait avoir une chance d\’affronter ses accusateurs et de répondre des crimes dont il est accusé.', 29981),
(172073, 'frFR', 'C\’est pas du bon juju, tout ça. La Horde, il faut qu\’elle reste unie, si on veut gagner la guerre… mais Sylvanas… elle nous facilite pas la tâche.\n\nEt tout ça, ça va faire que rajouter de l\’huile sur le feu.', '', 29981),
(172072, 'frFR', 'Je ne peux blâmer Baine pour ce qu\’il a fait, même s\’il a agi de façon irréfléchie. Son acte a montré que la Horde était profondément divisée. Cette scission n\’a cessé de croître depuis l\’attaque de Teldrassil.\n\nJe crains qu\’en s\’opposant ouvertement à Sylvanas, il ait mis son propre peuple en danger. Tout comme le mien le serait, si je me rangeais à ses côtés.\n\nEn ces temps troublés, nous devons rester vigilants et agir avec prudence.', '', 29981),
(172071, 'frFR', 'Eh bien, si je m\’attendais à ça !\n\nSi j\’avais su que les choses allaient tourner au vinaigre, j\’aurais fait payer le DOUBLE pour le billet d\’entrée !', '', 29981),
(172051, 'frFR', '', 'Prenez bien soin de Plumes, $p !', 29981),
(172050, 'frFR', 'Bon, prêts à partir à ton signal.', '', 29981),
(172049, 'frFR', '', 'Faut qu\’on file. Les sbires de Gallywix pourraient débarquer à tout moment !', 29981),
(172048, 'frFR', 'Eh, merci de ne rien dire à Gallywix.', '', 29981),
(172047, 'frFR', '', 'Je vous recontacterai. Peut-être. Ou pas.', 29981),
(172046, 'frFR', 'Salut.\n\nJani, il va surveiller la nouvelle reine de très près. Les Trolls comme elle, ils vénèrent pas les créatures comme moi. Mais là où l\’or brille, les déchets sont jamais loin.\n\nCeux que Talanji elle laisse derrière elle, ils finiront par venir à moi.\n\nÀ la prochaine, $gcossu:cossue;.', '', 29981),
(172043, 'frFR', 'Erreur 37 ! Erreur 37 ! Redémarrez le système !', 'Erreur 37 ! Erreur 37 ! Redémarrez le système !', 29981),
(172042, 'frFR', 'Surcharge du système ! Videz le cache !', 'Surcharge du système ! Videz le cache !', 29981),
(172041, 'frFR', 'Interaction requise ! Appuyez sur n\’importe quelle touche !', 'Interaction requise ! Appuyez sur n\’importe quelle touche !', 29981),
(172020, 'frFR', 'Ramenez-moi chez moi.', 'Ramenez-moi chez moi.', 29981),
