(162494, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aLe fourré Flétri a été perdu !', '|A:Warfronts-FieldMapIcons-Horde-LumberMill-Minimap:25:23:0:0|aLe fourré Flétri a été perdu !', 29981),
(162493, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aLa mine de Lornesta est attaquée !', '|A:Warfronts-FieldMapIcons-Horde-Mine-Minimap:25:23:0:0|aLa mine de Lornesta est attaquée !', 29981),
(162492, 'frFR', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aL\’accostage de Lor\’danel est attaqué !', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aL\’accostage de Lor\’danel est attaqué !', 29981),
