UPDATE `broadcast_text_locale` SET `Text_lang`='Houlà, du calme ! Comment aurais-je pu savoir qu\’il y avait des survivants ?', `VerifiedBuild`=29981 WHERE (`ID`=161939 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Espèce de lâche ! Tu nous as abandonnés à notre sort !', `VerifiedBuild`=29981 WHERE (`ID`=161938 AND `locale`='frFR');
