UPDATE `broadcast_text_locale` SET `Text_lang`='Je hais ces moutards !', `Text1_lang`='Débarrassez-nous de ces saletés !', `VerifiedBuild`=29981 WHERE (`ID`=161930 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ce sont ces sales petits morveux qui ont ramené ces choses au village !', `Text1_lang`='Encore une riche idée de ces gamins qui a mal tourné !', `VerifiedBuild`=29981 WHERE (`ID`=161929 AND `locale`='frFR');
