UPDATE `broadcast_text_locale` SET `Text_lang`='|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t Dame Malvoie commence à lancer |cFFFF0404|Hspell:268306|h[Cadence discordante]|h|r !', `Text1_lang`='|TInterface\\ICONS\\INV_MISC_VOLATILESHADOW:20|t Dame Malvoie commence à lancer |cFFFF0404|Hspell:268306|h[Cadence discordante]|h|r !', `VerifiedBuild`=29981 WHERE (`ID`=161927 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous avez réussi ! Azeroth a gagné en force… et vous aussi !', `VerifiedBuild`=29981 WHERE (`ID`=161926 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Un serviteur des Dieux très anciens ! Le Cœur d\’Azeroth est assez fort pour l\’expulser ! Utilisez le Cœur, $n !', `VerifiedBuild`=29981 WHERE (`ID`=161925 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Nous avons réussi ! Allons annoncer la bonne nouvelle au roi à Hurlevent.', `VerifiedBuild`=29981 WHERE (`ID`=161921 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Chevauchez les courants ! Bravez la tempête !', `VerifiedBuild`=29981 WHERE (`ID`=161918 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je peux pas dire que j\’aime beaucoup les bateaux en général, mais j\’admire ce que vous avez en réserve ici.\n\nSi vous trouvez d\’autres vieilles reliques dignes d\’intérêt, je serai ravi d\’y jeter un coup d\’œil.\n\nEt des portes. Des portes mystérieuses. Les portes mystérieuses des Titans, c\’est mon dada !', `VerifiedBuild`=29981 WHERE (`ID`=161916 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Halford garde des notes assez intéressantes, ici. Des rapports de guerre, des mouvements de troupes…\n\n<Kelsey jette un coup d\’œil à l\’encadrement de la porte et s\’approche pour murmurer à votre oreille.>\n\nEt je crois même que je sais où il cache son journal intime !\n\n<Kelsey vous fait un clin d\’œil entendu.>', `VerifiedBuild`=29981 WHERE (`ID`=161915 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous ne songez tout de même pas à partir sans vos camarades ?', `VerifiedBuild`=29981 WHERE (`ID`=161914 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t Rixxa Fluxifuge lance |cFFFF0000|Hspell:259940|h[Déflagration de propulseur]|h|r !', `Text1_lang`='|TINTERFACE\\ICONS\\SPELL_FROST_ARCTICWINDS.BLP:20|t Rixxa Fluxifuge lance |cFFFF0000|Hspell:259940|h[Déflagration de propulseur]|h|r !', `VerifiedBuild`=29981 WHERE (`ID`=161912 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Y a pas meilleur jour pour être Sombrefer !', `VerifiedBuild`=29981 WHERE (`ID`=161909 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Être à nouveau sur le front est un vrai plaisir, $n. Mais je dois bien avouer que jouer les infirmières commence à m\’ennuyer. Mes talents pourraient être bien mieux employés.\n\nNombre de techniques que nous autres Sancteforge avons employées contre la Légion seraient aussi efficaces contre la Horde.\n\nVeuillez informer le haut-commandant que je serais ravie de veiller à ce que tout prisonnier que nous capturons soit… « purifié » en bonne et due forme.', `VerifiedBuild`=29981 WHERE (`ID`=161907 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le gardien du cœur se positionne pour vous attaquer !', `Text1_lang`='Le gardien du cœur se positionne pour vous attaquer !', `VerifiedBuild`=29981 WHERE (`ID`=161905 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|tMerekpha s\’apprête à vous jeter du |cFFFF0000|Hspell:263914|h[Sable aveuglant]|h|r, détournez le regard !', `Text1_lang`='|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:20|tMerekpha s\’apprête à vous jeter du |cFFFF0000|Hspell:263914|h[Sable aveuglant]|h|r, détournez le regard !', `VerifiedBuild`=29981 WHERE (`ID`=161904 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Que savons-nous au sujet des Orcs mag\’har ?', `Text1_lang`='Que savons-nous au sujet des Orcs mag\’har ?', `VerifiedBuild`=29981 WHERE (`ID`=161888 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Que pouvez-vous me dire sur les Nains sombrefer ?', `Text1_lang`='Que pouvez-vous me dire sur les Nains sombrefer ?', `VerifiedBuild`=29981 WHERE (`ID`=161887 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quand je serai grand, je voudrais être comme Nisha ! C\’est la meilleure !\n\nOu alors comme Kiro ! Il est super intelligent…\n\nOu comme Meera, peut-être ! Elle est tellement gentille…\n\nOu bien Jena ! Elle a plein de choses…\n\nOu encore…\n\n<Rudo continue à lister les noms des autres Vulpérins.>', `VerifiedBuild`=29981 WHERE (`ID`=161886 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Laissez-vous tenter par une bière bien fraîche !', `VerifiedBuild`=29981 WHERE (`ID`=161884 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est votre jour de chance ! J\’ai de quoi assurer la victoire en toutes circonstances !', `VerifiedBuild`=29981 WHERE (`ID`=161883 AND `locale`='frFR');
