UPDATE `broadcast_text_locale` SET `Text1_lang`='Apparemment, mes talents ont attiré l\’attention des autorités en place. Et elles ont aussitôt… « requis » mes services.\n\nVous avez compris le sous-entendu ? Désolée. Malgré ma profession, la subtilité n\’est pas mon fort.\n\nEnfin, quoi qu\’il en soit, je sais reconnaître une opportunité quand j\’en vois une.', `VerifiedBuild`=29981 WHERE (`ID`=161564 AND `locale`='frFR');
