UPDATE `broadcast_text_locale` SET `Text_lang`='Gonk, il nous accorde sa bénédiction ! Puisse la meute être toujours avec vous !', `Text1_lang`='Gonk, il nous accorde sa bénédiction ! Puisse la meute être toujours avec vous !', `VerifiedBuild`=29981 WHERE (`ID`=160925 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Peuple de Zandalar ! Le Loa de la métamorphose, il attend les louanges de ses fidèles. Élevons nos voix vers le seigneur de la meute, le plus généreux des Loas ! Loué soit Gonk !', `Text1_lang`='Peuple de Zandalar ! Le Loa de la métamorphose, il attend les louanges de ses fidèles. Élevons nos voix vers le seigneur de la meute, le plus généreux des Loas ! Loué soit Gonk !', `VerifiedBuild`=29981 WHERE (`ID`=160923 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Frères et sœurs zandalari ! Le puissant Krag\’wa est revenu ! Venez rendre hommage au grand gardien sur les marches de Dazar\’alor !', `Text1_lang`='Frères et sœurs zandalari ! Le puissant Krag\’wa est revenu ! Venez rendre hommage au grand gardien sur les marches de Dazar\’alor !', `VerifiedBuild`=29981 WHERE (`ID`=160922 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le grand gardien, il nous offre sa protection ! Loué soit Krag\’wa !', `Text1_lang`='Le grand gardien, il nous offre sa protection ! Loué soit Krag\’wa !', `VerifiedBuild`=29981 WHERE (`ID`=160920 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Bwonsamdi, il observe chacun d\’entre nous. Montrez-vous dignes de sa bénédiction !', `Text1_lang`='Bwonsamdi, il observe chacun d\’entre nous. Montrez-vous dignes de sa bénédiction !', `VerifiedBuild`=29981 WHERE (`ID`=160919 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous connaissez tous Bwonsamdi. « Pour sûr ! C\’est le Loa de la mort ! », pensez-vous.', `Text1_lang`='Vous connaissez tous Bwonsamdi. « Pour sûr ! C\’est le Loa de la mort ! », pensez-vous.', `VerifiedBuild`=29981 WHERE (`ID`=160918 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Que les esprits, ils soient avec nous ! Approchez des marches de Dazar\’alor et venez louer celui qui veille sur nos morts. Rendez grâce à Bwonsamdi !', `Text1_lang`='Que les esprits, ils soient avec nous ! Approchez des marches de Dazar\’alor et venez louer celui qui veille sur nos morts. Rendez grâce à Bwonsamdi !', `VerifiedBuild`=29981 WHERE (`ID`=160917 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Frères et sœurs zandalari ! Approchez des marches de Dazar\’alor pour recevoir les enseignements de celui qu\’on nomme le roi des félins, la malédiction des proies et le seigneur des bêtes. Loué soit Kimbul !', `Text1_lang`='Frères et sœurs zandalari ! Approchez des marches de Dazar\’alor pour recevoir les enseignements de celui qu\’on nomme le roi des félins, la malédiction des proies et le seigneur des bêtes. Loué soit Kimbul !', `VerifiedBuild`=29981 WHERE (`ID`=160913 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Que la malédiction des proies bénisse vos chasses !', `Text1_lang`='Que la malédiction des proies bénisse vos chasses !', `VerifiedBuild`=29981 WHERE (`ID`=160911 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Recevez la bénédiction d\’Akunda !', `Text1_lang`='Recevez la bénédiction d\’Akunda !', `VerifiedBuild`=29981 WHERE (`ID`=160910 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Une tempête approche ! Mes frères, mes sœurs, laissez la pluie laver vos soucis. Venez louer Akunda sur les marches de Dazar\’alor !', `Text1_lang`='Une tempête approche ! Mes frères, mes sœurs, laissez la pluie laver vos soucis. Venez louer Akunda sur les marches de Dazar\’alor !', `VerifiedBuild`=29981 WHERE (`ID`=160908 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='$UUn admirateur:Une admiratrice; ! Quelle allégresse ! Cette rencontre doit vous mettre en état de choc. Ne vous laissez pas bouleverser ainsi, je ne suis qu\’un aventurier sans prétention, tout comme vous. Excepté que je suis un auteur à succès immensément riche et que mes admirateurs traversent les océans dans l\’espoir d\’avoir la chance de m\’apercevoir.\n\nVoici votre livre. Je suis certain que vous en prendrez grand soin.', `VerifiedBuild`=29981 WHERE (`ID`=160906 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le houblon, ça a du bon ! Avez-vous déjà goûté nos succulentes bières ?', `VerifiedBuild`=29981 WHERE (`ID`=160905 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous êtes chevalier de la mort ? J\’ai toujours rêvé de rencontrer quelqu\’un comme vous !\n\nC\’est comment la non-mort ? Et c\’est une vocation, pour vous ? Je peux en être moi aussi ? Où est-ce qu\’on doit s\’inscrire ?', `VerifiedBuild`=29981 WHERE (`ID`=160904 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous voulez bien dédicacer mon livre ?', `Text1_lang`='Vous voulez bien dédicacer mon livre ?', `VerifiedBuild`=29981 WHERE (`ID`=160903 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mon dernier ouvrage est un véritable chef-d\’œuvre. Un pur bijou littéraire, tiré du fond des océans pour éblouir et séduire le lecteur. Êtes-vous ici pour chanter mes louanges ?', `VerifiedBuild`=29981 WHERE (`ID`=160902 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous m\’avez sauvé ! Merci infiniment ! J\’ai une récompense pour vous, quelque part dans ce sac.', `VerifiedBuild`=29981 WHERE (`ID`=160899 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Où qu\’elles sont, les défenses ? La trahison de Zul a-t-elle affaibli Zuldazar au point qu\’elle ne peut plus se défendre elle-même ?\n\nMeera, elle a fait l\’impossible pour qu\’on arrive à temps, histoire de prévenir la garde royale, mais on peut pas dire qu\’il reste grand monde. Alors, c\’est à nous qu\’incombe de défendre ce qu\’il reste.', `VerifiedBuild`=29981 WHERE (`ID`=160896 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous n\’imaginez pas le chemin que nous avons dû emprunter pour arriver ici avant les Sephraks. Sans mon aide, vos amis n\’auraient jamais réussi à franchir ces montagnes à temps.\n\nOh, et nous avons amené avec nous Akunda et Kimbul. Le premier couvre nos arrières et j\’ignore où est passé le second. Il a juste parlé de « faire rendre gorge à l\’ennemi » ou quelque chose du genre.\n\nTout ce que je peux vous dire, c\’est que nous avons croisé des TAS de Sephraks en chemin.', `VerifiedBuild`=29981 WHERE (`ID`=160895 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pouvez-vous nous renseigner sur les agissements de la Horde dans cette région ?', `Text1_lang`='Pouvez-vous nous renseigner sur les agissements de la Horde dans cette région ?', `VerifiedBuild`=29981 WHERE (`ID`=160894 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Cette fois, j\’ai bien cru que c\’en était fini de moi. Merci infiniment, $R. C\’est toujours ainsi que l\’on appelle ceux de votre espèce, n\’est-ce pas ?', `Text1_lang`='Cette fois, j\’ai bien cru que c\’en était fini de moi. Merci infiniment, $R. C\’est toujours ainsi que l\’on appelle ceux de votre espèce, n\’est-ce pas ?', `VerifiedBuild`=29981 WHERE (`ID`=160893 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous semblez avoir soif d\’aventure ! Que diriez-vous d\’une bonne bière exotique ?', `VerifiedBuild`=29981 WHERE (`ID`=160892 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Une petite bière, ça vous tente ? Il y en a pour tous les goûts !', `VerifiedBuild`=29981 WHERE (`ID`=160890 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous les avez écrabouillés, ma parole ! Si vous voulez, je peux fournir de nouvelles armures à vos soldats. À titre gracieux, bien sûr !', `VerifiedBuild`=29981 WHERE (`ID`=160889 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Coupe plus vite, Colton ! On a des clients à nourrir !', `VerifiedBuild`=29981 WHERE (`ID`=160886 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Alors, allons-y, ma fille !', `VerifiedBuild`=29981 WHERE (`ID`=160884 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tu es prête ?', `VerifiedBuild`=29981 WHERE (`ID`=160883 AND `locale`='frFR');
