UPDATE `broadcast_text_locale` SET `Text1_lang`='J\’ai une surprise pour vous !', `VerifiedBuild`=29981 WHERE (`ID`=160880 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous avez vu ça ? Fascinant !', `VerifiedBuild`=29981 WHERE (`ID`=160879 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Eh bien, je ne sais pas trop, peut-être me trouver une gentille compagne et m\’installer dans une jolie petite ferme des environs…\n\nNon mais franchement, qu\’est-ce que vous croyez que je vais faire ?\n\nJe vais aller récupérer mon argent auprès de Cirrus, payer une tournée générale au Nid douillet, et me mettre en quête de la prochaine aventure.\n\nC\’est comme ça que je vois la vie, moi.', `VerifiedBuild`=29981 WHERE (`ID`=160878 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Que comptez-vous faire, à présent ?', `Text1_lang`='Que comptez-vous faire, à présent ?', `VerifiedBuild`=29981 WHERE (`ID`=160877 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Invasions, révolutions, réveil des Dieux très anciens… Tout cela n\’est rien ! Je ne quitterai pas ce Zocalo avant que le vieux Fabul m\’ait remboursé.', `VerifiedBuild`=29981 WHERE (`ID`=160876 AND `locale`='frFR');
