UPDATE `broadcast_text_locale` SET `Text_lang`='Hé, $r ! C\’est vous qui avez pris nos bonbons !', `Text1_lang`='Hé, $r ! C\’est vous qui avez pris nos bonbons !', `VerifiedBuild`=29981 WHERE (`ID`=160393 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’ai hâte d\’exhumer les secrets de Xibala. Cet endroit soulève tant de questions !\n\nQui est Xibala ? De quoi s\’agit-il ? Pourquoi les Zandalari ont-ils déserté ces lieux ? À quoi sert l\’Œil de Xibala ?\n\nSous la supervision de l\’examinatrice Tae\’shara, je suis sûr que nous le découvrirons !', `Text1_lang`='J\’ai hâte d\’exhumer les secrets de Xibala. Cet endroit soulève tant de questions !\n\nQui est Xibala ? De quoi s\’agit-il ? Pourquoi les Zandalari ont-ils déserté ces lieux ? À quoi sert l\’Œil de Xibala ?\n\nSous la supervision de l\’examinatrice Tae\’shara, je suis sûre que nous le découvrirons !', `VerifiedBuild`=29981 WHERE (`ID`=160390 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous croyez qu\’Astrandis accepterait de me présenter au télémancien en chef Oculeth… ?\n\nJ\’ai lu tant de choses à son sujet. À votre avis, il signerait mon tabard ?', `Text1_lang`='Vous croyez qu\’Astrandis accepterait de me présenter au télémancien en chef Oculeth… ?\n\nJ\’ai lu tant de choses à son sujet. À votre avis, il signerait mon tabard ?', `VerifiedBuild`=29981 WHERE (`ID`=160389 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Force m\’est de reconnaître qu\’après avoir passé des lustres cloîtrés dans un petit paradis où le vin coule à flots, ces Sacrenuit s\’adaptent remarquablement bien aux rigueurs du monde extérieur.\n\nJ\’ai même réussi à inculquer à l\’un d\’entre eux l\’art de manier une pelle !', `Text1_lang`='Force m\’est de reconnaître qu\’après avoir passé des lustres cloîtrés dans un petit paradis où le vin coule à flots, ces Sacrenuit s\’adaptent remarquablement bien aux rigueurs du monde extérieur.\n\nJ\’ai même réussi à inculquer à l\’un d\’entre eux l\’art de manier une pelle !', `VerifiedBuild`=29981 WHERE (`ID`=160388 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’ai donné une pioche à un Sacrenuit et il m\’a regardé d\’un air ahuri.\n\n« À quoi ça sert ? » m\’a-t-il demandé, comme s\’il n\’en avait pas la moindre idée.\n\nLeurs prouesses magiques en disent long sur les talents de leur race, mais ils ont encore beaucoup à apprendre du monde extérieur. Par chance, nous autres Sin\’dorei, nous avons tout le nécessaire pour les instruire.', `Text1_lang`='J\’ai donné une pioche à un Sacrenuit et il m\’a regardée d\’un air ahuri.\n\n« À quoi ça sert ? » m\’a-t-il demandé, comme s\’il n\’en avait pas la moindre idée.\n\nLeurs prouesses magiques en disent long sur les talents de leur race, mais ils ont encore beaucoup à apprendre du monde extérieur. Par chance, nous autres Sin\’dorei, nous avons tout le nécessaire pour les instruire.', `VerifiedBuild`=29981 WHERE (`ID`=160385 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous croyez que nos alliés du Reliquaire me laisseront utiliser un de ces minuscules pinceaux ?', `Text1_lang`='Vous croyez que nos alliés du Reliquaire me laisseront utiliser un de ces minuscules pinceaux ?', `VerifiedBuild`=29981 WHERE (`ID`=160380 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous croyez que les Trolls nous laisseront ramener une de ces étranges créatures au long cou à Suramar… ? Su\’esh aurait bien besoin d\’un compagnon !\n\nAllez leur demander, pour voir !', `Text1_lang`='Vous croyez que les Trolls nous laisseront ramener une de ces étranges créatures au long cou à Suramar… ?\n\nAllez leur demander, pour voir !', `VerifiedBuild`=29981 WHERE (`ID`=160378 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='<Il écrase un moustique à la volée.>\n\nQu\’est-ce qu\’il ne faut pas faire pour prouver notre valeur à la Horde ! Vous parlez de conditions de travail !', `Text1_lang`='<Elle écrase un moustique à la volée.>\n\nQu\’est-ce qu\’il ne faut pas faire pour prouver notre valeur à la Horde ! Vous parlez de conditions de travail !', `VerifiedBuild`=29981 WHERE (`ID`=160377 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’ai lu des tas d\’articles sur la jungle dans notre bibliothèque, mais aucun ne faisait mention de cette chaleur écrasante !\n\nMes vêtements me collent à la peau, et en plus, c\’est bourré d\’insectes ! Vous imaginez un peu ?\n\nQui peut vouloir vivre dans un endroit pareil ?', `Text1_lang`='J\’ai lu des tas d\’articles sur la jungle dans notre bibliothèque, mais aucun ne faisait mention de cette chaleur écrasante !\n\nMes vêtements me collent à la peau, et en plus, c\’est bourré d\’insectes ! Vous imaginez un peu ?\n\nQui peut vouloir vivre dans un endroit pareil ?', `VerifiedBuild`=29981 WHERE (`ID`=160375 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Elle est belle, ma morue ! Vidée et prête à déguster !', `VerifiedBuild`=29981 WHERE (`ID`=160372 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La prise du jour ! Du requin tout frais harponné ce matin !', `VerifiedBuild`=29981 WHERE (`ID`=160371 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ô, courants et marées, livrez ces humbles mots :', `VerifiedBuild`=29981 WHERE (`ID`=160358 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Avec le meilleur jambon des royaumes de l\’Est ! Arrivage direct de Havrebrune !', `VerifiedBuild`=29981 WHERE (`ID`=160357 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Saucisses pour tous ! Dernier arrivage de Drustvar et de Hurlevent !', `VerifiedBuild`=29981 WHERE (`ID`=160356 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Rien de tel qu\’une petite bière exotique en faisant son marché ! Et si vous n\’aimez pas la bière, j\’ai aussi de nombreuses variétés de thé !', `VerifiedBuild`=29981 WHERE (`ID`=160355 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Elle est bonne, ma bière, elle est bonne ! Importée directement de Pandarie !', `VerifiedBuild`=29981 WHERE (`ID`=160354 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Hé ! Vous, là-bas ! Oui, vous ! J\’ai ici quelque chose qui pourrait vous intéresser.', `VerifiedBuild`=29981 WHERE (`ID`=160353 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Aujourd\’hui plus que jamais, le chef de guerre a besoin de pouvoir compter sur une armée bien huilée. Votre guilde, quel sacrifice est-elle prête à consentir pour servir la cause de la Horde ?', `VerifiedBuild`=29981 WHERE (`ID`=160352 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Choux frais du pays !', `VerifiedBuild`=29981 WHERE (`ID`=160351 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Légumes frais en provenance des fermes de Chantorage ! Venez goûter le meilleur maïs au monde !', `VerifiedBuild`=29981 WHERE (`ID`=160350 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Si jamais vous avez un problème de chaussures, revenez me voir. D\’ici là, profitez bien de votre nouveau cirage !', `VerifiedBuild`=29981 WHERE (`ID`=160346 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Et un cirage de pompes, un !', `VerifiedBuild`=29981 WHERE (`ID`=160345 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous êtes du métier ? Bien, on a toujours besoin de spécialistes. Si vous cherchez du matériel spécialisé, il faut vous adresser au Tauren Hanul Vive-Rafale. Vous le trouverez dans le hall des Voies antiques, du côté est du Grand Sceau.', `Text1_lang`='Vous êtes du métier ? Bien, on a toujours besoin de spécialistes. Si vous cherchez du matériel spécialisé, il faut vous adresser au Tauren Hanul Vive-Rafale. Vous le trouverez dans le hall des Voies antiques, du côté est du Grand Sceau.', `VerifiedBuild`=29981 WHERE (`ID`=160344 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des fournitures générales ? La Horde, elle a tout prévu. Allez voir l\’Orque Araka, dans le hall des Voies antiques. C\’est du côté est du Grand Sceau. Vous verrez, elle a tout le matériel qu\’il vous faut.', `Text1_lang`='Des fournitures générales ? La Horde, elle a tout prévu. Allez voir l\’Orque Araka, dans le hall des Voies antiques. C\’est du côté est du Grand Sceau. Vous verrez, elle a tout le matériel qu\’il vous faut.', `VerifiedBuild`=29981 WHERE (`ID`=160342 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous voulez fonder une nouvelle guilde ? Il faut voir ça avec le gardien des quais Finnson et Perry Charlton. Ils forment un drôle de couple, ces deux-là, mais ils vous montreront les ficelles du métier.\n\nVous les trouverez dans le bâtiment qui se dresse juste à côté de l\’entrée du port, côté ville.', `Text1_lang`='Vous voulez fonder une nouvelle guilde ? Il faut voir ça avec le gardien des quais Finnson et Perry Charlton. Ils forment un drôle de couple, ces deux-là, mais ils vous montreront les ficelles du métier.\n\nVous les trouverez dans le bâtiment qui se dresse juste à côté de l\’entrée du port, côté ville.', `VerifiedBuild`=29981 WHERE (`ID`=160340 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='N\’avez-vous jamais rêvé d\’avoir une seconde chance ? Peut-être pour obtenir une pièce d\’armure spéciale, une arme ou encore un bijou surpuissant ?\n\nJe peux vous proposer un sceau qui vous permettra d\’infléchir le destin en vous offrant une deuxième chance d\’obtenir un objet.\n\nUne fois en votre possession, il s\’activera après une victoire sur de puissants ennemis dans de périlleux donjons et lors de dangereux raids.\n\nBientôt, je serai en mesure de vous fournir des sceaux du destin érodé contre de l\’or, des ressources de guerre ou des marques d\’honneur.\n\nMais je n\’en possède aucun pour l\’instant.', `VerifiedBuild`=29981 WHERE (`ID`=160332 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je vous propose d\’acquérir un sceau du destin érodé de diverses manières.\n\nÀ quoi préférez-vous renoncer pour avoir la chance d\’infléchir le sort ?', `VerifiedBuild`=29981 WHERE (`ID`=160331 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous détenez déjà le nombre maximum de sceaux !\n\nUtilisez-les avant de m\’en réclamer d\’autres.', `VerifiedBuild`=29981 WHERE (`ID`=160330 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des marchands ? Je vois. Quel genre de marchandises, au juste ?', `Text1_lang`='Des marchands ? Je vois. Quel genre de marchandises, au juste ?', `VerifiedBuild`=29981 WHERE (`ID`=160325 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Un nouveau style ? Effectivement, ce serait pas du luxe. Aussi étrange que ça puisse paraître, c\’est au tisse-dimensions Ezil qu\’il faut vous adresser. Je sais, on ne dirait pas, à voir la façon dont il est fagoté. Et pourtant, vous pouvez me croire, il fait des miracles. Le plus dur, c\’est d\’avoir un rendez-vous.\n\nSa boutique est à côté de l\’auberge du Nid douillet.', `Text1_lang`='Un nouveau style ? Effectivement, ce serait pas du luxe. Aussi étrange que ça puisse paraître, c\’est au tisse-dimensions Ezil qu\’il faut vous adresser. Je sais, on ne dirait pas, à voir la façon dont il est fagoté. Et pourtant, vous pouvez me croire, il fait des miracles. Le plus dur, c\’est d\’avoir un rendez-vous.\n\nSa boutique est à côté de l\’auberge du Nid douillet.', `VerifiedBuild`=29981 WHERE (`ID`=160324 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous faites dans la chasse au gros gibier ? Alors tenez-vous bien. Ces bestiaux, là-bas… ils ont la peau la plus dure que vous ayez jamais vue. Ouais, on plaisante pas avec ça, en Kul Tiras.\n\nSi vous voulez apprendre, il faut vous adresser aux meilleurs. Allez voir Camilla Sombre-Ciel, au niveau supérieur du marché des Alizés, côté nord.', `Text1_lang`='Vous faites dans la chasse au gros gibier ? Alors tenez-vous bien. Ces bestiaux, là-bas… ils ont la peau la plus dure que vous ayez jamais vue. Ouais, on plaisante pas avec ça, en Kul Tiras.\n\nSi vous voulez apprendre, il faut vous adresser aux meilleurs. Allez voir Camilla Sombre-Ciel, au niveau supérieur du marché des Alizés, côté nord.', `VerifiedBuild`=29981 WHERE (`ID`=160322 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='En sécurité ? Vous avez vu les monstres qui rôdent dans les parages ?\n\nMerci bien, mais j\’aime autant garder mon arme… Histoire de ne pas la passer à gauche, justement.', `VerifiedBuild`=29981 WHERE (`ID`=160321 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je le vois dans vos yeux : votre esprit est rongé par la folie. Le répit se trouve pourtant à votre portée.$b$bJadis, des sages ont combattu les ténèbres en ce lieu. Ils ont érigé des chapelles, ces remparts de foi et de détermination, mais également une taverne, pour noyer les murmures dans un océan d\’hydromel. Il ne reste plus que des gravats…$b$bDirigez-vous vers le nord-ouest et vous tomberez sur une relique de leur présence, une grande idole abyssale. Trouvez l\’effigie et vous parviendrez peut-être à chasser les horreurs qui envahissent ces lieux. Mais attention, vous devrez boire tout votre soûl et la mer le fait payer très cher.', `VerifiedBuild`=29981 WHERE (`ID`=160317 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je n\’ai pas les idées claires. Pouvez-vous m\’aider ?', `Text1_lang`='Je n\’ai pas les idées claires. Pouvez-vous m\’aider ?', `VerifiedBuild`=29981 WHERE (`ID`=160316 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous le sentez ? Les barrières… Elles sont en train de s\’effondrer. Ils arrivent, murmure terrifiant par murmure terrifiant.', `VerifiedBuild`=29981 WHERE (`ID`=160315 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous cherchez à vous remplir les poches d\’or, de platine ou de foudrargent ? Si vous voulez apprendre les dernières techniques en matière de minage, il faut vous adresser à Myra Cabot. Elle a un sixième sens pour flairer les bons filons.\n\nVous la trouverez au niveau supérieur du marché des Alizés, côté nord. Pensez à moi si vous faites fortune…', `Text1_lang`='Vous cherchez à vous remplir les poches d\’or, de platine ou de foudrargent ? Si vous voulez apprendre les dernières techniques en matière de minage, il faut vous adresser à Myra Cabot. Elle a un sixième sens pour flairer les bons filons.\n\nVous la trouverez au niveau supérieur du marché des Alizés, côté nord. Pensez à moi si vous faites fortune…', `VerifiedBuild`=29981 WHERE (`ID`=160311 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Samuel D. Colton III est l\’homme de la situation. Il n\’est pas peu fier de lui, et je m\’étonne qu\’il ne se soit pas affublé de titres ronflants. Cela dit, il faut reconnaître que ses ouvrages sont exquis. Si vous voulez vous former, c\’est le meilleur des professeurs.\n\nVous le trouverez en train de trôner fièrement derrière sa vitrine, au centre du niveau supérieur du marché des Alizés, côté nord.', `Text1_lang`='Samuel D. Colton III est l\’homme de la situation. Il n\’est pas peu fier de lui, et je m\’étonne qu\’il ne se soit pas affublé de titres ronflants. Cela dit, il faut reconnaître que ses ouvrages sont exquis. Si vous voulez vous former, c\’est le meilleur des professeurs.\n\nVous le trouverez en train de trôner fièrement derrière sa vitrine, au centre du niveau supérieur du marché des Alizés, côté nord.', `VerifiedBuild`=29981 WHERE (`ID`=160307 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous aimez les fleurs ? Moi aussi. Elles sentent si bon. Enfin, la plupart d\’entre elles, du moins.\n\nSi vous voulez apprendre les secrets de l\’horticulture telle qu\’on la pratique dans cette partie du monde, il faut vous adresser à Declan Senal. Vous le trouverez dans son jardin, au niveau supérieur du marché des Alizés, côté nord.', `Text1_lang`='Vous aimez les fleurs ? Moi aussi. Elles sentent si bon. Enfin, la plupart d\’entre elles, du moins.\n\nSi vous voulez apprendre les secrets de l\’horticulture telle qu\’on la pratique dans cette partie du monde, il faut vous adresser à Declan Senal. Vous le trouverez dans son jardin, au niveau supérieur du marché des Alizés, côté nord.', `VerifiedBuild`=29981 WHERE (`ID`=160304 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quelqu\’un protège la Complainte de la Banshee avec une magie qui sent les eaugures !', `VerifiedBuild`=29981 WHERE (`ID`=160303 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Prenez mes marteaux, $p, et lancez-les de toutes vos forces !', `VerifiedBuild`=29981 WHERE (`ID`=160301 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Marteaux-Hardis, concentrez-vous sur la Complainte de la Banshee ! Empêchez-les d\’intervenir !', `VerifiedBuild`=29981 WHERE (`ID`=160300 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous faites dans l\’artillerie ou dans les inventions farfelues ? Les deux à la fois, peut-être ?\n\nBref, quoi qu\’il en soit, il faut voir ça avec Layla Tirando. Vous la trouverez en train de trafiquer ses engins au niveau supérieur du marché des Alizés, côté nord.', `Text1_lang`='Vous faites dans l\’artillerie ou dans les inventions farfelues ? Les deux à la fois, peut-être ?\n\nBref, quoi qu\’il en soit, il faut voir ça avec Layla Tirando. Vous la trouverez en train de trafiquer ses engins au niveau supérieur du marché des Alizés, côté nord.', `VerifiedBuild`=29981 WHERE (`ID`=160299 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Votre heure est venue !', `VerifiedBuild`=29981 WHERE (`ID`=160297 AND `locale`='frFR');
