UPDATE `broadcast_text_locale` SET `Text_lang`='La fillette égarée est entre mes mains. Oh, elle ne cesse de pleurer. Ses souffrances seront éternelles !', `VerifiedBuild`=29981 WHERE (`ID`=160283 AND `locale`='frFR');
