UPDATE `broadcast_text_locale` SET `Text_lang`='On cherche à se faire bien voir de l\’amirauté ? Pas bête.\n\nOuais, je sais où elle est. C\’est l\’approvisionneuse Fray que vous cherchez. Vous la trouverez à la capitainerie, avec tous les gros bonnets.', `Text1_lang`='On cherche à se faire bien voir de l\’amirauté ? Pas bête.\n\nOuais, je sais où elle est. C\’est l\’approvisionneuse Fray que vous cherchez. Vous la trouverez à la capitainerie, avec tous les gros bonnets.', `VerifiedBuild`=29981 WHERE (`ID`=160198 AND `locale`='frFR');
