UPDATE `broadcast_text_locale` SET `Text_lang`='Ce coffre, il est sous la surveillance de Blaise le Balèze. Personne mettra la main sur son contenu !', `VerifiedBuild`=29981 WHERE (`ID`=159904 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Place à ma partie préférée !', `VerifiedBuild`=29981 WHERE (`ID`=159902 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='On m\’a chargé de garder le coffre et je prends mon travail très au sérieux, $p.\n\nTenez-vous à carreau, et tout ira bien.\n\nMais au moindre geste déplacé, je vous emballe dans la plus petite caisse que je trouverai et je vous expédie en Vol\’dun. Ensuite, les Sephraks, ils auront plus qu\’à vous jeter en pâture à leurs vautours.\n\nC\’est clair ?', `VerifiedBuild`=29981 WHERE (`ID`=159890 AND `locale`='frFR');
