UPDATE `broadcast_text_locale` SET `Text_lang`='On est bien loin de chez nous, vous et moi. Et si on allait plutôt boire un pot au Grand bazar ?', `VerifiedBuild`=29981 WHERE (`ID`=159887 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Oh, bien sûr. Si vous avez besoin des services d\’un professionnel, vous devriez trouver votre bonheur sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.\n\nQuel genre d\’instructeur recherchez-vous ?', `Text1_lang`='Oh, bien sûr. Si vous avez besoin des services d\’un professionnel, vous devriez trouver votre bonheur sur la terrasse de l\’Artisanat, dans la partie basse de Dazar\’alor, côté ouest.\n\nQuel genre d\’instructeur recherchez-vous ?', `VerifiedBuild`=29981 WHERE (`ID`=159885 AND `locale`='frFR');
