UPDATE `broadcast_text_locale` SET `Text_lang`='À vos ordres ! Hannibal, ici présent, portera votre message au donjon Portvaillant sans délai !', `VerifiedBuild`=29981 WHERE (`ID`=159799 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Cet affreux Sacrenuit d\’Oculeth nous a ouvert des portails vers Orgrimmar, Lune-d\’Argent et les Pitons-du-Tonnerre. Vous les trouverez dans le hall des Voies antiques, à l\’intérieur du Grand Sceau, côté est.\n\nMalheureusement, nous n\’avons aucun portail pour Fossoyeuse. Bientôt, on se vengera de ces fumiers de l\’Alliance ! Genn, Jaina et le roi Anduin paieront pour leurs crimes !\n\nVictoire au chef de guerre Sylvanas ! Puisse son règne durer mille ans !', `Text1_lang`='Cet affreux Sacrenuit d\’Oculeth nous a ouvert des portails vers Orgrimmar, Lune-d\’Argent et les Pitons-du-Tonnerre. Vous les trouverez dans le hall des Voies antiques, à l\’intérieur du Grand Sceau, côté est.\n\nMalheureusement, nous n\’avons aucun portail pour Fossoyeuse. Bientôt, on se vengera de ces fumiers de l\’Alliance ! Genn, Jaina et le roi Anduin paieront pour leurs crimes !\n\nVictoire au chef de guerre Sylvanas ! Puisse son règne durer mille ans !', `VerifiedBuild`=29981 WHERE (`ID`=159796 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Le chariot s\’est retourné d\’un seul coup. C\’était terrifiant !\n\nJ\’étais censée retourner en ville chercher de l\’aide, mais j\’ai eu peur.', `VerifiedBuild`=29981 WHERE (`ID`=159793 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah, qu\’il est bon de rencontrer une âme qui suit le même chemin.\n\nQue venez vous chercher auprès des Parlépines ?', `VerifiedBuild`=29981 WHERE (`ID`=159792 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous voilà de retour ?\n\nIl me semble pourtant que notre dette a été payée. Venez-vous demander de nouvelles faveurs aux Parlépines ?', `VerifiedBuild`=29981 WHERE (`ID`=159791 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Cela fait bien longtemps qu\’aucun natif du continent n\’avait mis les pieds ici.\n\nDésirez-vous puiser à la source du savoir des Parlépines ? Ou venez-vous revendiquer ces terres que votre espèce aspire tant à contrôler ?', `VerifiedBuild`=29981 WHERE (`ID`=159790 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous n\’êtes pas en position de juger la valeur de quiconque. Vos agissements souillent notre honneur, Tul !', `VerifiedBuild`=29981 WHERE (`ID`=159785 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous partageriez nos dons avec ces larves, Ulfar ? Vous méritez de finir sur le même bûcher !', `VerifiedBuild`=29981 WHERE (`ID`=159784 AND `locale`='frFR');
