UPDATE `broadcast_text_locale` SET `Text1_lang`='Nous allons voler plus bas pour les semer ! En avant, Trombecœur !', `VerifiedBuild`=29981 WHERE (`ID`=159737 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='M\’accrocher ! Comme si j\’avais le choix !', `VerifiedBuild`=29981 WHERE (`ID`=159736 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Accrochez-vous ! Ils nous tirent dessus !', `VerifiedBuild`=29981 WHERE (`ID`=159735 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les îles de l\’Écho ? Pourquoi vous voulez aller là-bas ? C\’est le fief des Sombrelances. C\’est tout petit, en plus. Vous feriez mieux de rester en Zandalar, c\’est plus grand.\n\nNon ? Bon, vous avez de la chance, on leur a prêté un de nos petits navires de guerre. Il est amarré au bout du quai sud, dans le port de Zandalar.', `Text1_lang`='Les îles de l\’Écho ? Pourquoi vous voulez aller là-bas ? C\’est le fief des Sombrelances. C\’est tout petit, en plus. Vous feriez mieux de rester en Zandalar, c\’est plus grand.\n\nNon ? Bon, vous avez de la chance, on leur a prêté un de nos petits navires de guerre. Il est amarré au bout du quai sud, dans le port de Zandalar.', `VerifiedBuild`=29981 WHERE (`ID`=159733 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ha ! C\’est c\’que je préfère dans tout ça !', `VerifiedBuild`=29981 WHERE (`ID`=159729 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pour sûr que vous avez de l\’or à dépenser. On est en Zandalar ! Même les Gobelins, ils sont pas aussi riches que nous.\n\nAlors, vous cherchez quoi, au juste ?', `Text1_lang`='Pour sûr que vous avez de l\’or à dépenser. On est en Zandalar ! Même les Gobelins, ils sont pas aussi riches que nous.\n\nAlors, vous cherchez quoi, au juste ?', `VerifiedBuild`=29981 WHERE (`ID`=159726 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Je vais aller reconnaître la Risée écarlate pendant que vous espionnez la Complainte de la Banshee. Tor ilisar\’thera\’nal !', `VerifiedBuild`=29981 WHERE (`ID`=159724 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Votre Sacrenuit, il trafique avec son vaudou dans le hall des Voies antiques. C\’est du côté est, à l\’intérieur du Grand Sceau.\n\nIl vous a bricolé un moyen de retourner dans vos petites villes. Comment elles s\’appellent, déjà ? Orgrimmar, Lune-d\’Argent et les Pitons-du-Tonnerre, c\’est ça ?', `Text1_lang`='Votre Sacrenuit, il trafique avec son vaudou dans le hall des Voies antiques. C\’est du côté est, à l\’intérieur du Grand Sceau.\n\nIl vous a bricolé un moyen de retourner dans vos petites villes. Comment elles s\’appellent, déjà ? Orgrimmar, Lune-d\’Argent et les Pitons-du-Tonnerre, c\’est ça ?', `VerifiedBuild`=29981 WHERE (`ID`=159722 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Comment avez-vous atterri ici ?', `Text1_lang`='Comment avez-vous atterri ici ?', `VerifiedBuild`=29981 WHERE (`ID`=159720 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous y voilà ! Je parie que les informations qu\’il nous faut pour trouver Jaina sont là-dedans.\n\n<Flynn désigne le coffre.>\n\nC\’est vous qui avez les clés, alors à vous l\’honneur.', `VerifiedBuild`=29981 WHERE (`ID`=159719 AND `locale`='frFR');
