UPDATE `broadcast_text_locale` SET `Text_lang`='Alors comme ça, vous voulez vous entraîner ? Ça tombe bien, c\’est ici à Dazar\’alor qu\’on trouve les meilleurs mannequins. Allez voir à l\’Armurerie royale.\n\nC\’est du côté nord de la pyramide de Dazar\’alor.', `Text1_lang`='Alors comme ça, vous voulez vous entraîner ? Ça tombe bien, c\’est ici à Dazar\’alor qu\’on trouve les meilleurs mannequins. Allez voir à l\’Armurerie royale.\n\nC\’est du côté nord de la pyramide de Dazar\’alor.', `VerifiedBuild`=29981 WHERE (`ID`=159716 AND `locale`='frFR');
