UPDATE `broadcast_text_locale` SET `Text_lang`='Pouvez-vous me montrer à quoi ressemblaient les hautes-terres Arathies avant que le conflit n\’éclate ?', `Text1_lang`='Pouvez-vous me montrer à quoi ressemblaient les hautes-terres Arathies avant que le conflit n\’éclate ?', `VerifiedBuild`=29981 WHERE (`ID`=159708 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Effectivement, vous êtes bien sur la liste ! Montez, c\’est la dernière porte au bout du couloir. Monsieur Camden va vous recevoir immédiatement.', `VerifiedBuild`=29981 WHERE (`ID`=159707 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='La guerre fait rage sur ces terres, reproduisant les schémas d\’un lointain passé. Les cycles du temps sont inexorables.\n\nVeuillez m\’excuser. J\’oublie parfois que la vision de votre peuple est… linéaire.\n\nEn quoi puis-je vous aider ?', `VerifiedBuild`=29981 WHERE (`ID`=159706 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Je regrette, mais nous recevons uniquement sur rendez-vous. Gardes !', `VerifiedBuild`=29981 WHERE (`ID`=159705 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous ne me reconnaissez pas ? C\’est moi, $n, champion de l\’Alliance ! Je dois consulter vos dossiers séance tenante !', `Text1_lang`='Vous ne me reconnaissez pas ? C\’est moi, $n, championne de l\’Alliance ! Je dois consulter vos dossiers séance tenante !', `VerifiedBuild`=29981 WHERE (`ID`=159703 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’ai rendez-vous avec votre patron. Je dois lui parler immédiatement, c\’est très important !', `Text1_lang`='J\’ai rendez-vous avec votre patron. Je dois lui parler immédiatement, c\’est très important !', `VerifiedBuild`=29981 WHERE (`ID`=159702 AND `locale`='frFR');
