UPDATE `broadcast_text_locale` SET `Text1_lang`='Ces terres sont chargées d\’histoire. Je me dois de vous montrer à quoi elles ressemblaient à l\’apogée de l\’empire arathorien.\n\nToutefois, le moment est mal choisi.\n\nEn avez-vous terminé avec le passé ?', `VerifiedBuild`=29981 WHERE (`ID`=159697 AND `locale`='frFR');
