UPDATE `broadcast_text_locale` SET `Text1_lang`='Du nerf ! On est en territoire hostile, pas à Hurlevent ! Déchargeons tout ce bazar et évacuons les blessés en vitesse !', `VerifiedBuild`=29981 WHERE (`ID`=159688 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ce n\’est pas la question qu\’on finit tous par se poser ?\n\n<Zenbaro tousse.>\n\nLes sables, ils n\’ont pas été tendres avec moi, $n. Ma fin approche.\n\nJ\’ai la gorge tout enflée par la chaleur du désert.\n\nAllez me chercher de l\’eau fraîche à la source tout près d\’ici, et je vous raconterai mon histoire.', `VerifiedBuild`=29981 WHERE (`ID`=159687 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous parlez de l\’autre Gobelin avec son engin bizarre, sur la terrasse de l\’Artisanat ? Il paraît que son Ferraill-o-matic, il vous démonte n\’importe quel équipement pour tout recycler.\n\nIl est dans la partie basse de Dazar\’alor, côté ouest.', `Text1_lang`='Vous parlez de l\’autre Gobelin avec son engin bizarre, sur la terrasse de l\’Artisanat ? Il paraît que son Ferraill-o-matic, il vous démonte n\’importe quel équipement pour tout recycler.\n\nIl est dans la partie basse de Dazar\’alor, côté ouest.', `VerifiedBuild`=29981 WHERE (`ID`=159686 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Qu\’est-ce que vous lui voulez, au Trône doré ? Une audience ?\n\nPour monter, il faut prendre les ascenseurs, dans le Grand Sceau.', `Text1_lang`='Qu\’est-ce que vous lui voulez, au Trône doré ? Une audience ?\n\nPour monter, il faut prendre les ascenseurs, dans le Grand Sceau.', `VerifiedBuild`=29981 WHERE (`ID`=159682 AND `locale`='frFR');
