UPDATE `broadcast_text_locale` SET `Text1_lang`='Merci ! En fait, j\’appartiens aux Pandashan. C\’est juste que je prends un jour de repos, voilà tout. Tenez, un peu d\’azérite, et pas un mot de toute cette histoire, d\’accord ?', `VerifiedBuild`=29981 WHERE (`ID`=159666 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Par les vagues, si je m\’attendais… Vais-je périr ici ?', `VerifiedBuild`=29981 WHERE (`ID`=159665 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Allons bon, voilà un cartographe coincé dans l\’exercice de ses fonctions !', `VerifiedBuild`=29981 WHERE (`ID`=159663 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ha ha ! Que serait la cartographie sans une pointe de frisson et de danger ? Je vois bien dans votre regard hagard que vous êtes tout à fait d\’accord avec moi. Tenez, c\’est pour vous. Quant à moi, je retourne à mes cartes !', `VerifiedBuild`=29981 WHERE (`ID`=159662 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il est très gênant pour un dragon de faire ce genre de requête, mais… vous pourriez m\’apporter un peu d\’aide ?', `VerifiedBuild`=29981 WHERE (`ID`=159661 AND `locale`='frFR');
