UPDATE `broadcast_text_locale` SET `Text1_lang`='Oh, Péppi, encore un pépin ! Va falloir trouver un moyen de te sortir de là…', `VerifiedBuild`=29981 WHERE (`ID`=159657 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous êtes super ! Je vais pouvoir reprendre mes explorations ! Bon sang, je ne serais plus Péppi Finrouage si je devais renoncer à l\’aventure !', `VerifiedBuild`=29981 WHERE (`ID`=159656 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Hé, vous faites quoi ici ? Vous voulez bien m\’aider ? Il m\’arrive une tuile.', `VerifiedBuild`=29981 WHERE (`ID`=159653 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous ! Ça vous dirait d\’aider un pauvre hère ? Je vous promets que je ne suis plus avec la Légion ! C\’est fini, cette époque. Je suis un électron libre, maintenant. Sylvester, le diablotin honnête.', `VerifiedBuild`=29981 WHERE (`ID`=159651 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Hé ! Bonjour ? Ah, oui, bonjour. Vous pouvez m\’aider ? Je ne sais pas trop quoi faire là, je suis un peu perdue.', `VerifiedBuild`=29981 WHERE (`ID`=159649 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Merci ! Du fond du cœur, vraiment. Vous savez où nous sommes ? Je n\’ai aucune idée de ce que je fais ici. Où est mon embarcation ? J\’avais une embarcation ?', `VerifiedBuild`=29981 WHERE (`ID`=159648 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’aurais besoin d\’un coup de main ? Il y a quelqu\’un ?', `VerifiedBuild`=29981 WHERE (`ID`=159647 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah, je vous remercie du coup de main. Et comment avez-vous atterri ici, vous ? Peu importe, je vois bien qu\’il vous tarde de reprendre la route.', `VerifiedBuild`=29981 WHERE (`ID`=159646 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La grande cité de Dazar\’alor, c\’est la plus puissante du monde entier. Ses quartiers vous réservent bien des merveilles, et ses habitants brillent par leur force et leur sagesse.\n\nPar contre, le vaudou, il faut s\’en méfier !', `Text1_lang`='La grande cité de Dazar\’alor, c\’est la plus puissante du monde entier. Ses quartiers vous réservent bien des merveilles, et ses habitants brillent par leur force et leur sagesse.\n\nPar contre, le vaudou, il faut s\’en méfier !', `VerifiedBuild`=29981 WHERE (`ID`=159645 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah, merci infiniment. Si vous saviez le nombre de fois que cela m\’est arrivé… Je finirai bien par retenir la leçon un jour ! Mais pas aujourd\’hui en tout cas, ah ! Tenez, c\’est tout ce que j\’ai, mais je suis heureux de le partager avec vous.', `VerifiedBuild`=29981 WHERE (`ID`=159643 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Gregg besoin aide ! Devoir aider Gregg !', `VerifiedBuild`=29981 WHERE (`ID`=159642 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous aider Gregg ! Gregg tellement heureux ! Gregg donner cailloux ! Gregg adorer cailloux.', `VerifiedBuild`=29981 WHERE (`ID`=159641 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Hé, vous là ! Vous pourriez peut-être aider le bon vieux Frankie ? Et peut-être qu\’il vous donnera quelque chose d\’intéressant en retour ? Alors, z\’en dites quoi ?', `VerifiedBuild`=29981 WHERE (`ID`=159640 AND `locale`='frFR');
