UPDATE `broadcast_text_locale` SET `Text1_lang`='Oh, waouh, merci ! Vous êtes super. Et j\’essaierai de ne pas recommencer.', `VerifiedBuild`=29981 WHERE (`ID`=159633 AND `locale`='frFR');
