UPDATE `broadcast_text_locale` SET `Text_lang`='Les meilleurs maîtres de métier, ils sont ici, à Zuldazar. Vous les trouverez sur la terrasse de l\’Artisanat, dans la partie inférieure de Dazar\’alor, côté ouest.\n\nVous cherchez quelqu\’un en particulier ?', `Text1_lang`='Les meilleurs maîtres de métier, ils sont ici, à Zuldazar. Vous les trouverez sur la terrasse de l\’Artisanat, dans la partie inférieure de Dazar\’alor, côté ouest.\n\nVous cherchez quelqu\’un en particulier ?', `VerifiedBuild`=29981 WHERE (`ID`=159397 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des familiers ? Les seuls compagnons qui vaillent le coup, c\’est les enfants d\’un Loa.\n\nAllez plutôt voir l\’éleveur de bêtes Kalatak, tout en bas de Dazar\’alor, au nord-ouest.', `Text1_lang`='Des familiers ? Les seuls compagnons qui vaillent le coup, c\’est les enfants d\’un Loa.\n\nAllez plutôt voir l\’éleveur de bêtes Kalatak, tout en bas de Dazar\’alor, au nord-ouest.', `VerifiedBuild`=29981 WHERE (`ID`=159394 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Tirisfal a vu de grandes puissances s\’ériger puis s\’effondrer. Pensez-vous que… ceux de votre espèce tireront un jour les leçons de leur histoire ?\n\nMais je m\’égare.\n\nEn avez-vous terminé avec le passé ?', `VerifiedBuild`=29981 WHERE (`ID`=159390 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Teldrassil… Une splendeur, n\’est-ce pas ? Mais la beauté est éphémère.\n\nEn particulier lorsque des mortels décident d\’y mettre le feu.\n\nEn avez-vous fini de votre mission dans le passé ?', `VerifiedBuild`=29981 WHERE (`ID`=159389 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t Vectis commence à lancer |cFFFF0000|Hspell:267242|h[Contagion]|h|r !', `Text1_lang`='|TINTERFACE\\ICONS\\ABILITY_CREATURE_CURSED_04.BLP:20|t Vectis commence à lancer |cFFFF0000|Hspell:267242|h[Contagion]|h|r !', `VerifiedBuild`=29981 WHERE (`ID`=159386 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Depuis ces rivages, vous pouvez admirer Teldrassil. Autrefois berceau de la vie, ce n\’est plus aujourd\’hui qu\’une désolation de flammes et de cendres.\n\nMême les Arbres-Mondes n\’échappent pas au cycle de la vie. Tout ce qui naît meurt un jour.\n\nNul n\’en a plus conscience que le Vol draconique de bronze.\n\nVoulez-vous voir l\’arbre dans toute sa splendeur ?', `VerifiedBuild`=29981 WHERE (`ID`=159384 AND `locale`='frFR');
