UPDATE `broadcast_text_locale` SET `Text1_lang`='Tirisfal… une contrée de splendeur et de ténèbres. Aujourd\’hui accablée par le désespoir… et les esprits défunts.\n\nCeux de votre espèce ont, me semble-t-il, tenté de s\’en emparer à maintes reprises.\n\nSouhaitez-vous voir cette région telle qu\’elle était avant la dernière guerre ?', `VerifiedBuild`=29981 WHERE (`ID`=159379 AND `locale`='frFR');
