UPDATE `broadcast_text_locale` SET `Text_lang`='Et voilà qu\’un ÉNORME dragon vient de surgir de nulle part, parce que ça manquait à ma journée, hein, pas vrai ? Dure semaine, j\’vous jure. Bref, y a un dragon.', `VerifiedBuild`=29981 WHERE (`ID`=155622 AND `locale`='frFR');
