UPDATE `broadcast_text_locale` SET `Text_lang`='Dragons à l\’horizon, et ils ont l\’air très intéressés par notre navire. Je crois qu\’ils m\’ont vu. Euh… un petit coup de main ?', `VerifiedBuild`=29981 WHERE (`ID`=155620 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Un vol entier de dragons vient d\’atterrir, et je pense savoir après quoi ils en ont. Bonne chance !', `VerifiedBuild`=29981 WHERE (`ID`=155619 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Qu\’est-ce qui se passe encore ? Pourquoi est-ce que le ciel s\’est assombri ? Et POURQUOI l\’île est envahie de cadavres ? Oh, misère…', `VerifiedBuild`=29981 WHERE (`ID`=155618 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Beurk, c\’est la PIRE puanteur que j\’ai jamais sentie. Qui n\’a pas pu se retenir ? Oh, ce sont des Morts-vivants. Hé, tout le monde, les Morts-vivants sont là et ils en ont après l\’azérite !', `VerifiedBuild`=29981 WHERE (`ID`=155617 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des Morts-vivants ? Ici ? Je n\’ai pas la moindre idée de ce qui se passe, mais quelque chose me dit que ce n\’est rien de bon.', `VerifiedBuild`=29981 WHERE (`ID`=155615 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Réveillez-vous, des bâtiments tol\’vir apparaissent à l\’horizon et ils n\’ont pas l\’air de vouloir nous acheter de la verroterie. Donc dépêchez-vous, d\’accord ?', `VerifiedBuild`=29981 WHERE (`ID`=155614 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tiens, des Tol\’vir ! Ça faisait un sacré bail que je n\’avais pas vu la poupe de leurs navires. Ils sont bel et bien là, et ils ont une dent contre nous.', `VerifiedBuild`=29981 WHERE (`ID`=155613 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des vaisseaux tol\’vir viennent de toucher terre. Mais comment font tous les gêneurs pour trouver l\’azérite ? Ça m\’énerve ! Vous pouvez vous occuper d\’eux ?', `VerifiedBuild`=29981 WHERE (`ID`=155612 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est quoi, ça ? Des centaures ? Des hommes-taures ? Je crois qu\’il y a des… Tol\’vir, qui viennent de se pointer.', `VerifiedBuild`=29981 WHERE (`ID`=155611 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Un équipage de pirates a posé pied sur l\’île. Parce que quand il y a un trésor sur une île, doit forcément y avoir aussi des pirates, pas vrai ?', `VerifiedBuild`=29981 WHERE (`ID`=155609 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Et voilà un TROISIÈME navire, parce que sinon, ce ne serait pas drôle ! Ce sont des pirates, au fait, si vous voulez tout savoir.', `VerifiedBuild`=29981 WHERE (`ID`=155608 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ouah ! On a failli se prendre un tir de canon. Et une armée de pirates s\’apprête à débarquer.', `VerifiedBuild`=29981 WHERE (`ID`=155607 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des sauroks viennent de montrer le bout de leur nez… Ils doivent avoir flairé l\’azérite. Ils ont vraiment un nez ? C\’est pas moi qui leur poserai la question.', `VerifiedBuild`=29981 WHERE (`ID`=155606 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est quoi, ces trucs dans les vagues ? Oh, un banc entier de sauroks vient d\’émerger des profondeurs. Eh bien, je vous laisse gérer tout ça.', `VerifiedBuild`=29981 WHERE (`ID`=155604 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des lézards à l\’air patibulaire semblent très intéressés par notre navire et son azérite. Ce serait peut-être bien de les faire déguerpir, non ?', `VerifiedBuild`=29981 WHERE (`ID`=155603 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah ! D\’où ils sortent, ceux-là ? Ils ont surgi de nulle part ! Hé, les héros ? On a de la compagnie.', `VerifiedBuild`=29981 WHERE (`ID`=155600 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mais qui sont ces intrus ? Je n\’arrive pas à les reconnaître. Et ils seraient avec nous ? Hum, ouais. Moi non plus, j\’y crois pas.', `VerifiedBuild`=29981 WHERE (`ID`=155599 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='On dirait qu\’on a attiré l\’attention d\’un Dieu très ancien et de ses serviteurs, rien que ça. Vous pourriez, euh… régler ce problème ?', `VerifiedBuild`=29981 WHERE (`ID`=155598 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quelqu\’un d\’autre entend des murmures ? Soit je deviens fou, soit il y a des Sans-Visage sur l\’île. Oh, et ils en ont après l\’azérite.', `VerifiedBuild`=29981 WHERE (`ID`=155596 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah, les Nagas sont de la fête. Manquait plus que ça, tiens. N\’y laissez pas votre peau, d\’accord ?', `VerifiedBuild`=29981 WHERE (`ID`=155590 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’ai repéré des Nagas au loin, qui seront bientôt sur nous. Donnez-leur un accueil digne de ce nom, vous voulez bien ?', `VerifiedBuild`=29981 WHERE (`ID`=155589 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des Nagas viennent de débarquer sur l\’île. Ils sont à la recherche d\’azérite, sans doute sur les ordres de notre amie Azshara. C\’est quoi, son problème, à la fin ?', `VerifiedBuild`=29981 WHERE (`ID`=155588 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est du brouillard qui arrive ? Non, attendez, je vois du bois vermoulu… Ce sont des Kvaldirs. Merveilleux.', `VerifiedBuild`=29981 WHERE (`ID`=155586 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Euh, je voulais vous dire, on a repéré des navires kvaldirs qui seront là d\’un instant à l\’autre. Ils doivent vouloir l\’azérite. Mais pourquoi j\’ai accepté ce boulot ?', `VerifiedBuild`=29981 WHERE (`ID`=155585 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ça devient sacrément brumeux, par ici. Les Kvaldirs doivent être derrière tout ça, alors ouvrez l\’œil ! Euh, réflexion faite, ouvrez les deux.', `VerifiedBuild`=29981 WHERE (`ID`=155584 AND `locale`='frFR');
