UPDATE `broadcast_text_locale` SET `Text_lang`='Toc-toc, petit Barbe-de-Bronze. Y a quelqu\’un ?', `VerifiedBuild`=29981 WHERE (`ID`=143840 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La Lumière est toujours avec moi. Je ne tomberai pas si facilement !', `VerifiedBuild`=29981 WHERE (`ID`=143839 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Amiral Rogers ! Nous avons pris votre forteresse d\’assaut. Où est donc ce châtiment que vous nous aviez promis, paladin ?', `VerifiedBuild`=29981 WHERE (`ID`=143838 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ils croient qu\’ils peuvent nous arrêter avec leurs petits chevaux ? Ha ! Montrez-leur de quel bois on se chauffe dans la Horde !', `VerifiedBuild`=29981 WHERE (`ID`=143837 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le bastion a besoin de renforts. Allez détruire ces chars avant qu\’ils soient trop près !', `VerifiedBuild`=29981 WHERE (`ID`=143836 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nos défenses sont toujours insuffisantes. Troupes de la Horde, retournez à la base et défendez notre position !', `VerifiedBuild`=29981 WHERE (`ID`=143835 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Très bien. Si c\’est la guerre que vous voulez, vous l\’aurez. Envoyez un bataillon de cavalerie les éliminer !', `VerifiedBuild`=29981 WHERE (`ID`=143834 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='On a pris Grangeneuve. À nous les chevaucheurs de loups !', `VerifiedBuild`=29981 WHERE (`ID`=143832 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='L\’atelier est fini. Nos démolisseurs vont réduire en poussière les murs de l\’Alliance en moins de deux !', `VerifiedBuild`=29981 WHERE (`ID`=143830 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Démolissez les engins de siège !', `VerifiedBuild`=29981 WHERE (`ID`=143829 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous avez été prévenus. Préparez-vous à mourir, chiens de la Horde !', `VerifiedBuild`=29981 WHERE (`ID`=143828 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Bah ! Étouffe-toi avec ta vindicte, Turalyon !', `VerifiedBuild`=29981 WHERE (`ID`=143821 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ces terres appartiennent à l\’Alliance ! Ces envahisseurs de la Horde recevront bientôt le châtiment qu\’ils méritent !', `VerifiedBuild`=29981 WHERE (`ID`=143820 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Aujourd\’hui, c\’est à la Horde qu\’elles appartiennent !', `VerifiedBuild`=29981 WHERE (`ID`=143819 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Muradin ! Montrez-vous, sale lâche !', `VerifiedBuild`=29981 WHERE (`ID`=143816 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nos défenses sont toujours insuffisantes. Arrêtez ces chars avant qu\’ils atteignent notre base !', `VerifiedBuild`=29981 WHERE (`ID`=143815 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Moins sale que la tienne, Barbe-de-Bronze !', `VerifiedBuild`=29981 WHERE (`ID`=143814 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Le combat est fini… et nous sommes tous en vie. Ateena va payer pour cette folie !', `VerifiedBuild`=29981 WHERE (`ID`=143811 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Tremblez devant le destructeur de Zuldazar ! Essayez de nous arrêter pour voir… Vous allez souffrir comme jamais !', `VerifiedBuild`=29981 WHERE (`ID`=143810 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous êtes si près du but, mais vous allez succomber à la fureur du maître !', `VerifiedBuild`=29981 WHERE (`ID`=143809 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Travailler pour le Reliquaire, c\’est un vrai sacerdoce…', `VerifiedBuild`=29981 WHERE (`ID`=143808 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ha, c\’était trop facile ! Montrez-moi de quoi vous êtes capable. On n\’a jamais assez de bois.', `VerifiedBuild`=29981 WHERE (`ID`=143807 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Votre peau, elle fera une enveloppe parfaite pour mon maître !', `VerifiedBuild`=29981 WHERE (`ID`=143803 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Après, c\’est la Horde qui tombera. Vous allez payer pour la mort d\’Hir\’eek ! Vous pouvez pas m\’échapper.', `VerifiedBuild`=29981 WHERE (`ID`=143802 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Zuldazar va tomber… et mon maître, il sera bientôt libre ! Vos petits Loas ne l\’arrêteront pas !', `VerifiedBuild`=29981 WHERE (`ID`=143801 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Intéressant… Baeloth, viens jeter un coup d\’œil et dis-moi ce que tu vois.', `VerifiedBuild`=29981 WHERE (`ID`=143798 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Où étais-tu passé, Baeloth ? J\’ai encore des tas de précieuses informations à te dicter.', `VerifiedBuild`=29981 WHERE (`ID`=143797 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Baeloth, ne touche pas aux reliques !', `VerifiedBuild`=29981 WHERE (`ID`=143794 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='C\’est prodigieux… Baeloth, viens admirer cette petite merveille !', `VerifiedBuild`=29981 WHERE (`ID`=143793 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Le bouclier d\’Hezrel est activé. Abritez-vous dedans !', `VerifiedBuild`=29981 WHERE (`ID`=143792 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Baeloth, tu rêvasses encore ? Rends-toi un peu utile, à la fin !', `VerifiedBuild`=29981 WHERE (`ID`=143791 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Barges ont besoin de matériel pour rester au top ! Mon boulot à moi, c\’est de gérer le ravitaillement et de réparer nos engins !$b$b…$b$bVous n\’imaginez pas le nombre d\’appareils qu\’ils me bousillent chaque jour.$b$bÇa, on ne peut pas dire qu\’ils soient très délicats.', `VerifiedBuild`=29981 WHERE (`ID`=143789 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='$n, puis-je m\’entretenir avec vous ? J\’aurais besoin de votre aide.', `VerifiedBuild`=29981 WHERE (`ID`=143788 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Trois larrons et un tas d\’os. Trois larrons et tas d\’os. T\’larrons\’ et tas d\’os. T\’laar et tos. T\’laartos. T\’laartos !', `VerifiedBuild`=29981 WHERE (`ID`=143786 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah, ils sont tous tombés dans le panneau ! C\’est incroyable qu\’ils aient pu croire que je sois assez simple d\’esprit pour… Attendez, vous m\’écoutiez ? Je, euh… T\’laartos !', `VerifiedBuild`=29981 WHERE (`ID`=143785 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Voilà la liste des choses que T\’laartos n\’aime pas : les serpents, les vilains enfants, les grottes sombres, les serpents… et les petits êtres chétifs qui embêtent T\’laartos.', `VerifiedBuild`=29981 WHERE (`ID`=143784 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le petit être chétif n\’essaierait jamais d\’abuser la gentillesse de T\’laartos, hein ?', `VerifiedBuild`=29981 WHERE (`ID`=143782 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='T\’laartos est fier d\’être un Sancteforge !', `VerifiedBuild`=29981 WHERE (`ID`=143780 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='T\’laartos est prêt !', `VerifiedBuild`=29981 WHERE (`ID`=143773 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Un danger ? T\’laartos se moque du danger !', `VerifiedBuild`=29981 WHERE (`ID`=143771 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le petit être chétif a besoin de l\’aide de T\’laartos ?', `VerifiedBuild`=29981 WHERE (`ID`=143770 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='T\’laartos ?', `VerifiedBuild`=29981 WHERE (`ID`=143768 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='T\’laartos !', `VerifiedBuild`=29981 WHERE (`ID`=143767 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s commence à lancer |cFFFF0000|Hspell:259610|h[Apocalypse sanglante]|h|r ! À couvert !', `Text1_lang`='|TInterface\\Icons\\ABILITY_DEATHWING_BLOODCORRUPTION_DEATH.BLP|t%s commence à lancer |cFFFF0000|Hspell:259610|h[Apocalypse sanglante]|h|r ! À couvert !', `VerifiedBuild`=29981 WHERE (`ID`=143766 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Résistez ! Débattez-vous ! Votre souffrance, elle nourrit mon maître !', `VerifiedBuild`=29981 WHERE (`ID`=143765 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Jaina ? Vous voulez dire Jain-arde. Et Modera ? Euh… Bon, cette fois aucun de ces excellents jeux de mots ne me vient.', `VerifiedBuild`=29981 WHERE (`ID`=143764 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Khadgar ? Vous voulez dire Rat\’dgar ?', `VerifiedBuild`=29981 WHERE (`ID`=143763 AND `locale`='frFR');
