UPDATE `broadcast_text_locale` SET `Text_lang`='Pour Quel\’thalas !', `VerifiedBuild`=29981 WHERE (`ID`=143759 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Que voulez-vous ?', `VerifiedBuild`=29981 WHERE (`ID`=143752 AND `locale`='frFR');
