UPDATE `broadcast_text_locale` SET `Text1_lang`='Comploter ? Moi ? Qu\’est-ce que l\’innocente demoiselle que je suis pourrait bien comploter ?', `VerifiedBuild`=29981 WHERE (`ID`=143745 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous croyez que je n\’ai pas remarqué la façon dont vous lorgnez mes forestiers-sombres ? Je vous conseille d\’arrêter ça tout de suite.', `VerifiedBuild`=29981 WHERE (`ID`=143744 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Je suis votre préférée des sœurs Coursevent, n\’est-ce pas ? N\’est-ce pas ?', `VerifiedBuild`=29981 WHERE (`ID`=143742 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Et moi qui commençais à douter de l\’existence d\’une telle créature !', `VerifiedBuild`=29981 WHERE (`ID`=143740 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Magnifique !', `VerifiedBuild`=29981 WHERE (`ID`=143734 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est ici que je les préparais, mes cocktails. La famille royale recevait des nobles du monde entier, et moi, je les ai tous régalés de mes créations.\n\nMais aujourd\’hui, c\’est devenu le repaire de ces sales étrangers avec leurs affreux amis. Quelle tristesse !', `VerifiedBuild`=29981 WHERE (`ID`=143717 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je respecte certains des cartels gobelins. Neutres, puissants, prêts à faire ce qu\’il faut. Comme les Zandalari… en moins bien, forcément.\n\nMais vous, les Baille-Fonds, vous n\’avez aucune fierté. Comment pouvez-vous pactiser avec les Elfes et la Horde ? Sales traîtres.', `VerifiedBuild`=29981 WHERE (`ID`=143716 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Goûtez à ma puissance !', `VerifiedBuild`=29981 WHERE (`ID`=143715 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’admire l\’organisation de votre Horde, $p. Des chefs puissants. Un but commun. Un ravitaillement régulier.\n\nVous recrutez ?', `VerifiedBuild`=29981 WHERE (`ID`=143714 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je n\’ai jamais réussi à me faire à l\’idée que les Sombrelances ont rejoint la Horde. Il faut croire que vous avez toujours été trop faibles pour vous débrouiller seuls.\n\nComment il va, Vol\’jin ?', `VerifiedBuild`=29981 WHERE (`ID`=143711 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous avez l\’air d\’avoir soif. Ça vous dirait de discuter autour d\’un verre ?\n\nZuldazar est là depuis la nuit des temps et elle ne va pas disparaître en une nuit.', `VerifiedBuild`=29981 WHERE (`ID`=143709 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mon peuple, il a fondé la civilisation à l\’aube des temps et il porte les autres sur son dos depuis cette époque.\n\nRappelez-moi ce que vos congénères, ils ont accompli qui soit digne de rester dans les mémoires, $PR ?\n\nJ\’ai beau réfléchir, il n\’y a rien qui me vient.', `VerifiedBuild`=29981 WHERE (`ID`=143706 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Échec de la réparation de la structure de confinement de G\’huun. Objectif : empêcher les êtres identifiés comme Trolls de sang de détruire Zuldazar pour éviter la libération de G\’huun.\n\nStructure encerclée par des Trolls de sang. Le gardien des Titans Hezrel assurera la sécurité |2 $n et de la princesse Talanji.\n\nPrière de sauter sur les épaules et garder la tête baissée.', `VerifiedBuild`=29981 WHERE (`ID`=143704 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous avez des nouvelles de ce qui se passe hors de la ville ?', `VerifiedBuild`=29981 WHERE (`ID`=143702 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous autres, les Orcs, il faut bien reconnaître que vous savez picoler.\n\nMais dites à vos amis les Elfes de ne jamais mettre les pieds ici, d\’accord ?', `VerifiedBuild`=29981 WHERE (`ID`=143698 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Alleria et Turalyon ? Aucune chance que ça dure. Non pas que je leur souhaite malheur, mais… Bref. Et si on changeait de sujet ?', `VerifiedBuild`=29981 WHERE (`ID`=143697 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Du violet, encore du violet… Je commence à en avoir plein le dos, littéralement !', `VerifiedBuild`=29981 WHERE (`ID`=143695 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Moi, un Haut-Elfe ? Mais qui aurait donc envie d\’être un Haut-Elfe, alors qu\’on peut avoir l\’air sombre et tourmenté ?', `VerifiedBuild`=29981 WHERE (`ID`=143694 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mon cache-œil n\’a jamais changé de côté ! Franchement… comme si ce genre d\’erreur pouvait se produire !', `VerifiedBuild`=29981 WHERE (`ID`=143679 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Champion de la reine ou non, Nathanos ne m\’arrive pas à la cheville !', `VerifiedBuild`=29981 WHERE (`ID`=143677 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Si je prends autant soin de mes cheveux, c\’est parce que je le vaux bien !', `VerifiedBuild`=29981 WHERE (`ID`=143676 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Oh, je crois que j\’en ai attrapé un gros !', `VerifiedBuild`=29981 WHERE (`ID`=143651 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Reculez, $r ! Sa voix m\’appartient !', `VerifiedBuild`=29981 WHERE (`ID`=143649 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Il y a une telle… puissance… ici.', `VerifiedBuild`=29981 WHERE (`ID`=143648 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='En effet ! Tout comme vous, nous sommes convaincus que le Vide peut être utilisé pour défendre la vie au lieu de la dévorer. Nous avons fait d\’immenses progrès, dame Coursevent, mais de nombreux mystères persistent.', `VerifiedBuild`=29981 WHERE (`ID`=143645 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Alleria Coursevent ? C\’est… C\’est un honneur inespéré !', `VerifiedBuild`=29981 WHERE (`ID`=143642 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Magistère Umbric ! Je suis Alleria Coursevent.', `VerifiedBuild`=29981 WHERE (`ID`=143641 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='D\’après ses notes, ce lieu se trouvait au cœur d\’une faille déchirant la trame de la réalité. Il ne l\’a jamais trouvé… mais moi j\’ai réussi ! La voie s\’ouvrira bientôt à nous !', `VerifiedBuild`=29981 WHERE (`ID`=143636 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le grand magistère Rommath doit comprendre que ce pouvoir est primordial pour la défense de Lune-d\’Argent. Plus jamais les Sin\’dorei ne tomberont aux griffes de l\’ennemi !', `VerifiedBuild`=29981 WHERE (`ID`=143625 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Voyons si ces poissons sont prêts à mordre !', `VerifiedBuild`=29981 WHERE (`ID`=143618 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='$p ! La Dame noire exige que nous nous entretenions à Orgrimmar.', `VerifiedBuild`=29981 WHERE (`ID`=143601 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Trêve de civilités. Vous devez à présent faire vos preuves. Où que vos aventures vous mènent, n\’oubliez pas que vous combattez… pour la Horde !', `VerifiedBuild`=29981 WHERE (`ID`=143595 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous vous chasserons de ces terres !', `VerifiedBuild`=29981 WHERE (`ID`=143588 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’ai besoin de soins !', `VerifiedBuild`=29981 WHERE (`ID`=143582 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est notre scierie ! Allez vous faire voir ailleurs !', `VerifiedBuild`=29981 WHERE (`ID`=143581 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pardonnez-moi, $p.\n\nJe serais ravi de discuter avec vous, mais je crois que je vais vomir.\n\nUn conseil : ne goûtez pas à leur vin.', `VerifiedBuild`=29981 WHERE (`ID`=143579 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Avez-vous déjà goûté le vin du cru ?\n\nNe passez pas à côté ! Il est incroyablement mauvais.\n\nJe vous parie que des bardes composeront un jour des chansons sur son âpreté légendaire.\n\nC\’est véritablement un exploit en termes de médiocrité et de gâchis d\’alcool. Avec ça, on est sûr de gâcher n\’importe quelle fête.', `VerifiedBuild`=29981 WHERE (`ID`=143577 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ils osent appeler cette piquette du vin ? Pas étonnant que les Trolls abandonnent cette ville.', `VerifiedBuild`=29981 WHERE (`ID`=143573 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous sommes enfin libres ! Vite, sortons d\’ici !', `Text1_lang`='Nous sommes enfin libres ! Vite, sortons d\’ici !', `VerifiedBuild`=29981 WHERE (`ID`=143572 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ces abominations de bois sortent tout droit d\’un cauchemar !', `VerifiedBuild`=29981 WHERE (`ID`=143571 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Du nerf, bande de moules !', `Text1_lang`='Mettez-y un peu de cœur, bande de moules !', `VerifiedBuild`=29981 WHERE (`ID`=143567 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Entendu. En route pour Corlain !', `VerifiedBuild`=29981 WHERE (`ID`=143565 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Votre fin approche. G\’huun sera bientôt libre et alors, à nous Azeroth !', `VerifiedBuild`=29981 WHERE (`ID`=143561 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Drustvar vit des heures bien sombres, mais nous reprendrons le contrôle de nos terres !', `VerifiedBuild`=29981 WHERE (`ID`=143559 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pour Zandalar !', `VerifiedBuild`=29981 WHERE (`ID`=143558 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Rezan, c\’est l\’heure de partir en chasse !', `VerifiedBuild`=29981 WHERE (`ID`=143557 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Pendant ce temps, nous préparerons notre départ pour Corlain. Maréchal, j\’ai cru comprendre que vous aviez un plan d\’attaque ?', `VerifiedBuild`=29981 WHERE (`ID`=143552 AND `locale`='frFR');
