UPDATE `broadcast_text_locale` SET `Text1_lang`='Rappelez-vous, si on vous pose une question et que vous ne connaissez pas la réponse, inventez-en une ! Les Gnomes sont des petits malins, mettez ça à profit !', `VerifiedBuild`=29981 WHERE (`ID`=141433 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Faites-moi un joli sourire, recrues ! Montrez-leur à quel point on peut être adorables, nous les Gnomes !', `VerifiedBuild`=29981 WHERE (`ID`=141432 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Comment ? Ce n\’est pas juste ! CE N\’EST PAS JUSTE !', `VerifiedBuild`=29981 WHERE (`ID`=141431 AND `locale`='frFR');
