UPDATE `broadcast_text_locale` SET `Text_lang`='C\’en est fini des Portvaillant ! Et quand dame Corsandre montera sur le trône, je commanderai sa flotte !', `VerifiedBuild`=29981 WHERE (`ID`=141428 AND `locale`='frFR');
