UPDATE `broadcast_text_locale` SET `Text_lang`='Voilà qui est mieux ! Qui a dit que je devais respecter les règles ? Hé hé hé !', `VerifiedBuild`=29981 WHERE (`ID`=141421 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quoi ? Non, non, non. Ça ne va pas du tout.', `VerifiedBuild`=29981 WHERE (`ID`=141420 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Non ! Soit ! On relance !', `VerifiedBuild`=29981 WHERE (`ID`=141419 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah, une nouvelle tête ! J\’espère que vous êtes un peu moins insipide que les gens du coin.', `VerifiedBuild`=29981 WHERE (`ID`=141418 AND `locale`='frFR');
