UPDATE `broadcast_text_locale` SET `Text_lang`='Hum, alors… Qu\’allons-nous faire de nos deux mutins… Pourquoi ne pas laisser les dés décider de leur sort ?', `VerifiedBuild`=29981 WHERE (`ID`=141416 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ho ho ! Notre nouvelle « recrue » est arrivée ! On va bien s\’amuser !', `VerifiedBuild`=29981 WHERE (`ID`=141415 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les choses ont changé, Flynn. C\’est moi le capitaine, maintenant. Et dès que les Portvaillant seront hors course, nous pourrons piller tout Kul Tiras !', `VerifiedBuild`=29981 WHERE (`ID`=141413 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est ça ! Faites-lui passer un mauvais quart d\’heure.', `VerifiedBuild`=29981 WHERE (`ID`=141411 AND `locale`='frFR');
