UPDATE `broadcast_text_locale` SET `Text_lang`='Vous mettez ma parole en doute, mais que suis-je censé penser de vous ? N\’entendez-vous pas les murmures des seigneurs du Vide ? N\’avez-vous pas cédé aux ténèbres sur Argus ?', `VerifiedBuild`=29981 WHERE (`ID`=141388 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Votre langue est acérée, Lor\’themar. Le respectueux forestier que j\’ai connu serait-il devenu le porte-parole de son chef de guerre ?', `VerifiedBuild`=29981 WHERE (`ID`=141387 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ne dites pas de bêtises ! Quelle que soit la raison de votre venue, nos invités peuvent aussi l\’entendre.', `VerifiedBuild`=29981 WHERE (`ID`=141382 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je vous en prie, appelez-moi Lor\’themar. Mais où sont mes manières ? Laissez-moi vous présenter Alleria Coursevent, une ancienne héroïne de Lune-d\’Argent.', `VerifiedBuild`=29981 WHERE (`ID`=141379 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Gobelins, ils m\’ont juré que ce plan fonctionnerait… C\’est pour ça que j\’ai besoin que vous alliez vérifier.$B$BÇa vous dirait de descendre la rivière ?', `VerifiedBuild`=29981 WHERE (`ID`=141352 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il garde la pêche en toutes circonstances… Il est le prédateur de Port-Liberté… le champion des compétiteurs… Trothak le cogneur aux requins !', `VerifiedBuild`=29981 WHERE (`ID`=141351 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Incroyable ! Ces marins d\’eau douce ont réussi à vaincre Gryff et Stevin ! Il ne leur reste plus qu\’un adversaire à affronter, qu\’on ne présente plus.', `VerifiedBuild`=29981 WHERE (`ID`=141350 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les fantastiques frères funestes… La formidable fusion de la finesse et de la force… J\’ai nommé les fabuleux, les effroyables Stevin et Gryff !', `VerifiedBuild`=29981 WHERE (`ID`=141349 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous allez connaître votre douleur !', `VerifiedBuild`=29981 WHERE (`ID`=141347 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il n\’y a aucune échappatoire !', `VerifiedBuild`=29981 WHERE (`ID`=141345 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ludwig est au tapis ! Quel combat ! Ces boucaniers ont du ressort, et ça vaut mieux pour eux… car leur prochain adversaire est la quintessence de la violence.', `VerifiedBuild`=29981 WHERE (`ID`=141344 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Sauvez… vous…', `VerifiedBuild`=29981 WHERE (`ID`=141343 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Sale gosse ! Bwonsamdi, il m\’a promis la vie éternelle en échange de ton âme ! Tu vas tout gâcher, tout !', `VerifiedBuild`=29981 WHERE (`ID`=141342 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il débarque directement des égouts de Port-Liberté… Celui qu\’on surnomme le « puissant protecteur », le « sergent sauvage » ou encore la « carapace coriace » va vous tor… tuer ! Voici Ludwig !', `VerifiedBuild`=29981 WHERE (`ID`=141341 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Eh bien, incroyable. Ils ont attrapé un cochon. On pourrait peut-être passer à un défi un peu plus… difficile !', `VerifiedBuild`=29981 WHERE (`ID`=141340 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Z\’avez jamais entendu parler du clan Crocs-d\’ombre ? Pas étonnant, ils se sont tous fait zigouiller par le Marteau du crépuscule.\n\nReste plus que moi. Les Zandalari, ils me laissent ambassadrice en souvenir du bon vieux temps. Je suis rien qu\’une bête curieuse et pis c\’est tout.\n\nC\’est pas si terrible, r\’marquez. J\’arrête pas de me faire payer des verres.', `VerifiedBuild`=29981 WHERE (`ID`=141334 AND `locale`='frFR');
