UPDATE `broadcast_text_locale` SET `Text_lang`='J\’ai commis une erreur, c\’est vrai… mais regardez autour de vous ! Cet endroit ne vous rappelle-t-il pas de bons souvenirs ? Restez, et permettez-nous de rebâtir ce temple en votre honneur !', `VerifiedBuild`=29981 WHERE (`ID`=133581 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Tortollans ont d\’étranges coutumes, mon seigneur. Comment aurais-je pu savoir que refuser une demande en mariage passerait pour une déclaration de guerre ?', `VerifiedBuild`=29981 WHERE (`ID`=133580 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ta tâche était pourtant simple. Faire la paix avec les Tortaka et veiller sur mon temple en mon absence. Regarde un peu le résultat !', `VerifiedBuild`=29981 WHERE (`ID`=133579 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je me présente, Al\’Abas le Magnifique. Pardonnez mon humeur massacrante, mais je supporte mal ce clapier à Murlocs. Dites-moi, auriez-vous l\’amabilité de prêter l\’oreille à mon histoire ?', `VerifiedBuild`=29981 WHERE (`ID`=133577 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Nous avons un vieux proverbe ici, en Kul Tiras.$B$BQuand les choses tournent mal, les marins se contentent de faire contre mauvaise fortune bon cœur, car selon eux, « on ne peut pas aller contre les vents ».$B$BJe déteste ce dicton.', `VerifiedBuild`=29981 WHERE (`ID`=133576 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='La défaite de Daelin Portvaillant a tout changé ici.$B$BJaina devait avoir ses raisons… n\’est-ce pas ?', `VerifiedBuild`=29981 WHERE (`ID`=133574 AND `locale`='frFR');
