UPDATE `broadcast_text_locale` SET `Text1_lang`='Bienvenue au kraal des Bêtes de guerre, $n.\n\nJ\’ai entendu parler de votre Horde et je sais que vous êtes là pour parlementer avec le vieux Rastakhan.\n\nOn va voir si vous savez vous rendre utile. Si c\’est le cas, on plaidera peut-être en votre faveur dans les hautes sphères de Dazar, hein ?', `VerifiedBuild`=29981 WHERE (`ID`=130906 AND `locale`='frFR');
