UPDATE `broadcast_text_locale` SET `Text_lang`='Peu de gens ont compris que je puisse utiliser les Nagas pour obtenir l\’Œil de Sargeras, mais c\’était un mal nécessaire pour assurer l\’avenir d\’Azeroth. Ne laissez rien vous empêcher d\’accomplir ce qui doit l\’être !', `VerifiedBuild`=29981 WHERE (`ID`=129268 AND `locale`='frFR');
