UPDATE `broadcast_text_locale` SET `Text_lang`='NIVEAU 1', `VerifiedBuild`=29981 WHERE (`ID`=124673 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Un Ettin est lâché dans les catacombes ! Il faut l\’arrêter avant qu\’il détruise tout !', `VerifiedBuild`=29981 WHERE (`ID`=124557 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous m\’offrez vos âmes ? Quelle générosité… Cela épargnera à mes Val\’kyrs la peine d\’aller en chercher à la surface.', `VerifiedBuild`=29981 WHERE (`ID`=123585 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tu vois, Farah ? $n est parmi nous. Tant que l\’esprit d\’Ursoc nous accompagne, nous n\’avons rien à craindre des Harpies.', `VerifiedBuild`=29981 WHERE (`ID`=123332 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Mais quel désastre. Je veux que vous me descendiez le canon gnome !', `VerifiedBuild`=29981 WHERE (`ID`=123261 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Utilisez Écharper pour frapper plusieurs ennemis d\’un coup !', `VerifiedBuild`=29981 WHERE (`ID`=123210 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Utilisez Écharper pour frapper plusieurs ennemis d\’un coup !', `VerifiedBuild`=29981 WHERE (`ID`=123186 AND `locale`='frFR');
