UPDATE `broadcast_text_locale` SET `Text_lang`='Tu es bien sûr de l\’avoir eue, hein ? On n\’a pas intérêt à rater notre coup !', `VerifiedBuild`=29981 WHERE (`ID`=121285 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Très mauvaise idée. Les démons, c\’est une chose, mais les Satyres ? Ce sont des Elfes de la nuit qui ont succombé à la corruption.', `VerifiedBuild`=29981 WHERE (`ID`=121275 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Écoutez. Marius voit régulièrement des choses qui vous terrifieraient au point que vous finiriez par me ressembler.$b$bMais même lui n\’est pas à l\’aise dans cette grotte. Il y rôderait de mauvais rêves et des Elfes corrompus.$b$bBah ! Nous avons suivi un puissant Satyre jusqu\’ici et il n\’est pas question de repartir sans avoir au moins tenté de l\’asservir.', `VerifiedBuild`=29981 WHERE (`ID`=121247 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Gurg urggle blerg\’urk urgle blark.\n\nBlerglearg urk $ct urgle blurg ? Glerk ! Gurg urggle ble\’blerg, erks ker-blerk, gurgler.\n\n<Le Murloc ratatiné rit doucement avant de retrouver tout son sérieux.>\n\nGlergurg blergbergle, $n. Gulg ble\’blergle : gurg urggle kek, glup gurg urggle blarkleblag ? Blerg ?', `VerifiedBuild`=29981 WHERE (`ID`=121197 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Enfants de Golganneth : les grands Skrogs de l\’Histoire (10 joueurs recommandés)', `Text1_lang`='Les Enfants de Golganneth : les grands Skrogs de l\’Histoire (10 joueurs recommandés)', `VerifiedBuild`=29981 WHERE (`ID`=120786 AND `locale`='frFR');
