UPDATE `broadcast_text_locale` SET `Text_lang`='Ah, oui, les Skrogs. Des brutes fascinantes, n\’est-ce pas ?$b$bQuel livre vous intéresse en particulier ?', `VerifiedBuild`=29981 WHERE (`ID`=120776 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ahh… les Kobolds. Excellent choix ! Un de mes sujets de prédilection.$b$bQuel livre vous intéresse en particulier ?', `VerifiedBuild`=29981 WHERE (`ID`=120775 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Murlocs de la crique de l\’Épave se seraient mis à vénérer un géant des mers du nom de Débris. Tuez cette créature !', `VerifiedBuild`=29981 WHERE (`ID`=120694 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous êtes incroyable ! Merci.', `Text1_lang`='Vous êtes incroyable ! Merci.', `VerifiedBuild`=29981 WHERE (`ID`=120056 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Avez-vous autre chose à me révéler au sujet de Xe\’ra et des Naaru avant que nous partions ? [JE METS MA CHEMISE ROUGE ET MON CHAPEAU DE SORCIER.]', `Text1_lang`='Avez-vous autre chose à me révéler au sujet de Xe\’ra et des Naaru avant que nous partions ? [BEAUCOUP D\’INTERPRÉTATION.]', `VerifiedBuild`=29981 WHERE (`ID`=119607 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Grells restent normalement dans leur coin, mais récemment ils se sont enhardis. Ils attaquent les Furbolgs de Grisbois ! Je crains qu\’ils n\’aient bientôt envahi tout le village.', `VerifiedBuild`=29981 WHERE (`ID`=119377 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Harpies veulent maudire les gracieuses chouettes de la forêt. Faites vite ! J\’espère qu\’il n\’est pas trop tard…', `VerifiedBuild`=29981 WHERE (`ID`=119351 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Harpies vers-de-serre ont envahi Ombrefange. Heureusement, les survivants ont réussi à fuir ! Auriez-vous la bonté de rapporter ce qu\’ils ont été contraints d\’abandonner en partant ?', `VerifiedBuild`=29981 WHERE (`ID`=119349 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Harpies sang-de-pierre utilisent leur magie noire pour pétrifier les acolytes d\’Elothir ! Sauvez nos nobles alliés de cette calamité.', `VerifiedBuild`=29981 WHERE (`ID`=119339 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='La cage est peut-être robuste, mais l\’esprit d\’un Murloc est faible et facile à dominer !', `VerifiedBuild`=29981 WHERE (`ID`=118932 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Utilisez maintenant Élémentaire de feu pour invoquer votre élémentaire !', `VerifiedBuild`=29981 WHERE (`ID`=118121 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Grglll… Attendez, oh ! Hé. Attention, ces Nagas ne sont pas commodes. Ils ont réduit en esclavage la tribu des Murlocs aileron-des-brisants des environs. Ce refuge est tout ce qui leur reste pour se protéger de l\’invasion. Votre aide serait vraiment la bienvenue !\n\nUne dernière chose… Si jamais vous mettez la main sur les artéfacts érodés que portent les Nagas, cela vous ennuierait-il de me les rapporter ? J\’en ai besoin pour mes recherches. Je vous garantis que le jeu en vaudra la chandelle !', `VerifiedBuild`=29981 WHERE (`ID`=117142 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Naaru peuvent-ils vous aider ?', `VerifiedBuild`=29981 WHERE (`ID`=117049 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ne vous en faites pas pour nous, débarrassez-nous juste des Nagas !', `VerifiedBuild`=29981 WHERE (`ID`=116438 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Hozen.', `Text1_lang`='Les Hozen.', `VerifiedBuild`=29981 WHERE (`ID`=116051 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ce royaume est à la Légion. Les Troggs doivent servir pour survivre. Nous l\’avons compris.', `VerifiedBuild`=29981 WHERE (`ID`=116012 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Troggs s\’agitent de plus en plus. Peut-être est-ce lié à votre marteau perdu ? Vous voulez bien vous occuper d\’eux ?', `VerifiedBuild`=29981 WHERE (`ID`=115793 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mande-étoiles flétri débloqué !', `Text1_lang`='Mande-étoiles flétrie débloquée !', `VerifiedBuild`=29981 WHERE (`ID`=115658 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Après avoir vaincu les Dieux très anciens, les gardiens ont été priés de mettre de l\’ordre dans le monde. Les Titans leur ont donné cinq puissantes reliques… les piliers de la Création !', `VerifiedBuild`=29981 WHERE (`ID`=115562 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Un Titan ? Ça explique un certain nombre de choses.', `VerifiedBuild`=29981 WHERE (`ID`=115547 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Comme le fait que mon frère ait été transformé en diamant et qu\’il se soit mis à parler aux Titans ?', `VerifiedBuild`=29981 WHERE (`ID`=115546 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le rituel a changé mon corps, mais aussi mes oreilles pour que j\’entende la voix d\’Azeroth elle-même. C\’est pas qu\’un gros caillou. C\’est un Titan !', `VerifiedBuild`=29981 WHERE (`ID`=115545 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Par la force des Sombrefer ! Pour Forgefer !', `VerifiedBuild`=29981 WHERE (`ID`=115133 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous pensiez quand même pas que les Sombrefer allaient louper la fête, hein ?', `VerifiedBuild`=29981 WHERE (`ID`=115062 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Elfes pathétiques ! Rien plus fort que Ettin !', `VerifiedBuild`=29981 WHERE (`ID`=114588 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Plusieurs siècles durant, notre ordre a caché et défendu un lieu secret, le tombeau de Tyr.\n\nTyr, un gardien des Titans qui avait accompli de vaillants exploits pour le salut d\’Azeroth, fut vaincu par la traîtrise et la puissance des Dieux très anciens. Loken le félon envoya de puissants C\’Thraxxi l\’assassiner. Il parvint à les repousser, tuant l\’un d\’eux et forçant le second à s\’enfuir, mais cette victoire fut au prix de sa vie.\n\nCertains des Vrykuls qui l\’accompagnaient furent si émus par son sacrifice qu\’ils restèrent là pour veiller sur son tombeau. Ils furent par la suite remplacés par des Humains… nous. Pendant longtemps, nous avons réussi à cacher cet endroit. Jusqu\’à récemment.', `VerifiedBuild`=29981 WHERE (`ID`=114512 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La réapparition soudaine de la Croisade écarlate, relancée dans son désir d\’éradiquer tous les Morts-vivants ? J\’ai déjà entendu ça. Vous êtes un seigneur de l\’effroi, pas vrai ?', `Text1_lang`='La réapparition soudaine de la Croisade écarlate, relancée dans son désir d\’éradiquer tous les Morts-vivants ? J\’ai déjà entendu ça. Vous êtes un seigneur de l\’effroi, pas vrai ?', `VerifiedBuild`=29981 WHERE (`ID`=114477 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il semblerait qu\’un groupe de démons soit en train d\’installer son camp dans la base située au sud ! Les Ogres vont avoir une sacrée surprise !', `Text1_lang`='Il semblerait qu\’un groupe de démons soit en train d\’installer son camp dans la base située au sud ! Les Ogres vont avoir une sacrée surprise !', `VerifiedBuild`=29981 WHERE (`ID`=114343 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='J\’ai de bons souvenirs des Sombrefer. Sa haine rendait Modgud facile à influencer. Imaginez sa fureur quand je l\’ai abandonnée aux Marteaux-Hardis au pire moment ! Je suis si facile à perdre… Ne l\’oubliez pas.', `VerifiedBuild`=29981 WHERE (`ID`=114007 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Naaru évoquent-ils l\’éternel conflit ? Vous ont-ils dit que l\’histoire de votre monde n\’est qu\’un instant dans celle de la création ? Vous ont-ils parlé de ceux qui étaient là avant les Draeneï ? Non ?', `VerifiedBuild`=29981 WHERE (`ID`=113988 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous sommes la Lame d\’ébène, des Non-morts qui protègent le monde.', `VerifiedBuild`=29981 WHERE (`ID`=113955 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Trouvez-moi un livre sur les Skrogs. Peu importe lequel.', `VerifiedBuild`=29981 WHERE (`ID`=111684 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Bien sûr, dans l\’immédiat, notre académie est plus préoccupée par les intrusions permanentes des Skrogs.', `VerifiedBuild`=29981 WHERE (`ID`=111682 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='C\’est exact ! Un type austère qui s\’intéresse à l\’histoire de Tyr, le gardien des Titans.$b$bJe lui ai parlé de son combat contre Galakrond. Kalecgos prétendait avoir vu la main tranchée de Tyr au Repos de Galakrond. Lorsque je le lui ai dit, Galford s\’est mis dans tous ses états et est reparti aussitôt. Il va bien, au moins ?', `VerifiedBuild`=29981 WHERE (`ID`=111588 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Bienvenue, $c. Vous vous intéressez aux enchantements, ou vous êtes là pour nous aider à combattre les Nagas ?', `VerifiedBuild`=29981 WHERE (`ID`=111305 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Sous le commandement énergique de dame Sylvanas, les Réprouvés ont retrouvé une position de force au sein des factions rivales d\’Azeroth. Renforcée par la puissante magie noire de ses Val\’kyrs, Sylvanas a regarni ses rangs et refait de sa capitale Fossoyeuse un havre de paix pour son peuple. Cependant, les ombres du passé hantent toujours la reine morte-vivante. De traîtresses machinations fomentées par ses subalternes, telle que la trahison au portail du Courroux, continuent à faire planer le doute sur l\’allégeance des Réprouvés à la Horde. En tant que membre dévoué de l\’armée morte-vivante de Sylvanas, votre responsabilité sera de contribuer à faire la preuve de la loyauté des Réprouvés, et d\’éliminer quiconque oserait menacer la suprématie de la Dame noire.', `VerifiedBuild`=29981 WHERE (`ID`=111161 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Earlnoc est un nuisible difforme et surdimensionné ! Cet Ettin n\’a braconné que trop longtemps. Mettez un terme à ses rapines ! ', `VerifiedBuild`=29981 WHERE (`ID`=111070 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le guide est étroitement lié aux Naaru. Leur soutien pourrait nous aider à prendre l\’avantage ! Êtes-vous $gsûr:sûre; de votre choix ?', `VerifiedBuild`=29981 WHERE (`ID`=111000 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='On dit que cette lame remonte à l\’antiquité, avant même l\’apparition des Titans ! Vous avez fait un excellent choix. À moins que vous ne préfériez y réfléchir à deux fois ?', `VerifiedBuild`=29981 WHERE (`ID`=110997 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Voilà un Murloc des plus… inhabituels. Il me dit quelque chose mais je n\’arrive pas à le remettre. Pourriez-vous aller y regarder de plus près ?', `VerifiedBuild`=29981 WHERE (`ID`=110246 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ce serait le moment parfait pour lancer Élémentaire de terre !', `VerifiedBuild`=29981 WHERE (`ID`=110012 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Utilisez maintenant Élémentaire de feu pour invoquer votre élémentaire !', `VerifiedBuild`=29981 WHERE (`ID`=109989 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='D\’odieux Murlocs ont envahi le village de Morheim. Leur présence dans un lieu autrefois sacré m\’est insupportable. Exterminez cette vermine !', `VerifiedBuild`=29981 WHERE (`ID`=109910 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Bien joué ! Par chance, nous avons pu intervenir assez tôt, avant que l\’influence des Nagas puisse s\’enraciner complètement.', `VerifiedBuild`=29981 WHERE (`ID`=109792 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Nos soldats sont épuisés par les incessants assauts des Nagas. Ralliez les veilleurs de la nuit, et renvoyez ces misérables dans les profondeurs d\’où ils sont venus !', `VerifiedBuild`=29981 WHERE (`ID`=109266 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pas de quartier pour les Nagas !', `Text1_lang`='Pas de quartier pour les Nagas !', `VerifiedBuild`=29981 WHERE (`ID`=109263 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Garuhod tenait sans doute une piste, mais je crains qu\’il n\’ait commis quelque erreur dans les ingrédients. Nous devrions essayer une combinaison différente. Peut-être des œufs d\’hydre et des yeux de Murloc ?', `VerifiedBuild`=29981 WHERE (`ID`=109166 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Nagas sèment la pagaille. Ils réduisent les Murlocs des environs en esclavage pour envahir le rivage. Éliminez-les quoi qu\’il en coûte ! Oh, et si jamais vous trouvez des artéfacts érodés, j\’en aurais vraiment besoin pour mes recherches.', `VerifiedBuild`=29981 WHERE (`ID`=108821 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Beau travail ! Nous avons repoussé les Nagas et suffisamment éclairci les rangs de leurs esclaves murlocs ! Si vous avez des artéfacts érodés sur vous, je peux vous en débarrasser !', `VerifiedBuild`=29981 WHERE (`ID`=108807 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Si les géants des mers comptent s\’allier aux Nagas, alors ils sont passés dans le camp adverse. Montrez-leur qu\’on ne se joue pas impunément des Bien-nés !', `VerifiedBuild`=29981 WHERE (`ID`=108743 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='D\’abord les Nagas et les démons envahissent nos terres… et maintenant, ces makruras infestent nos rivages ! Il nous faut découvrir quelle force impie leur fait perdre l\’esprit. Pouvez-vous nous aider ?', `VerifiedBuild`=29981 WHERE (`ID`=108739 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Après ça, les Nagas y réfléchiront à deux fois avant de remettre les pieds sur Azsuna ! Les citoyens de Nar\’thalas vous sont infiniment redevables, $c, de même que les veilleurs de la nuit.', `VerifiedBuild`=29981 WHERE (`ID`=108738 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='D\’abord, les Nagas assiègent notre ville et maintenant, ils essaient de filer en emportant nos reliques ! C\’en est trop ; montrez-leur ce qu\’il en coûte de braver la fureur des veilleurs de la nuit.', `VerifiedBuild`=29981 WHERE (`ID`=108737 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Ces démons sont encore plus tenaces que les maudits Nagas ! Nous devons les repousser et mes veilleurs de la nuit vont vous y aider.', `VerifiedBuild`=29981 WHERE (`ID`=108733 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Oh, toutes sortes de reliques datant d\’la guerre des Anciens. À l\’époque, les combats ont fait rage dans l\’coin, ça oui. Tout ce gangreschiste est pas arrivé là par hasard, pardi ! Mais à part ça, rien qui soit lié aux Titans. Du moins, pas encore…', `VerifiedBuild`=29981 WHERE (`ID`=107612 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous, occupez-vous de ce Satyre puant. Moi, je vais retrouver mon mari !', `VerifiedBuild`=29981 WHERE (`ID`=107557 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Nagas harcèlent un géant des mers. Que faire ?', `VerifiedBuild`=29981 WHERE (`ID`=107347 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Faites vite, mes sœurs. Nous devons terminer le maléfice afin que personne, étrangers et Taurens confondus, ne puisse échapper à son emprise !', `VerifiedBuild`=29981 WHERE (`ID`=107314 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Harpies des terres des Sorcières déchaînent leur magie perverse sur la faune sauvage de la combe des Hurlements. Nous ne savons pas comment contrer leur malédiction. S\’il vous plaît, mettez un terme à cette folie !', `VerifiedBuild`=29981 WHERE (`ID`=107275 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ces satanés Murlocs ne manquent pas d\’imagination quand il s\’agit de couler des bateaux ! Vous pourriez sans doute vous rendre utile en récupérant la cargaison de ces épaves.', `VerifiedBuild`=29981 WHERE (`ID`=107070 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Harpies envahissent les nids de nos alliés aigles. Elles cherchent la bagarre ? Ha ! Elle vont l\’avoir !', `VerifiedBuild`=29981 WHERE (`ID`=106944 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Maudits soient ces Nagas !', `VerifiedBuild`=29981 WHERE (`ID`=106887 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='De répugnants Nagas s\’aventurent hors de leurs sombres creux sous les mers. Je ne peux accepter la présence de ces bêtes corrompues ! Montrons-leur ce qu\’est un combat honorable.', `VerifiedBuild`=29981 WHERE (`ID`=106824 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='On a réussi ! Et visez-moi un peu ça, une console des Titans ! Je m\’en charge, $gmon gars:jeune fille;. Assurez-vous que personne me dérange pendant que je bosse.', `VerifiedBuild`=29981 WHERE (`ID`=106804 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Même les peaux sont inutilisables. Les Harpies vont le payer cher !', `VerifiedBuild`=29981 WHERE (`ID`=106734 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Regardez, là-bas. Des Nagas. Nous sommes en concurrence avec la reine Azshara en personne !', `VerifiedBuild`=29981 WHERE (`ID`=106574 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='40e jour : Un Ettin a saccagé mon atelier au manoir de Koralune. Je l\’ai fait fuir avec des sorts, mais je pense qu\’il ne tardera pas à revenir…', `VerifiedBuild`=29981 WHERE (`ID`=106480 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vise les yeux, Murloc !', `Text1_lang`='Vise les yeux, Murloc !', `VerifiedBuild`=29981 WHERE (`ID`=106353 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='L\’entraînement du Murloc commence à porter ses fruits !', `VerifiedBuild`=29981 WHERE (`ID`=106351 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='L\’entraînement du Murloc commence à porter ses fruits !', `Text1_lang`='L\’entraînement du Murloc commence à porter ses fruits !', `VerifiedBuild`=29981 WHERE (`ID`=106345 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Le Loa aigle ! Loués soient les esprits !', `VerifiedBuild`=29981 WHERE (`ID`=106253 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Cet endroit est marqué par l\’architecture des Titans. Pas plus loin que cette colline au nord, il y a une énorme salle construite par eux !', `VerifiedBuild`=29981 WHERE (`ID`=106219 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Regardez ! Les Val\’kyrs !', `VerifiedBuild`=29981 WHERE (`ID`=106211 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Puissent les Val\’kyrs t\’emporter, Haardgrim !', `VerifiedBuild`=29981 WHERE (`ID`=106210 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Du nerf, mes Nagas ! Nous allons détruire Jandvik !', `VerifiedBuild`=29981 WHERE (`ID`=106170 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Ettins peuvent faire une croix sur leurs agapes, ce soir. Les Crins-de-Rive vous remercient !', `VerifiedBuild`=29981 WHERE (`ID`=106163 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Ces Ettins préparent un énorme bûcher afin de faire rôtir les membres de ma tribu ! Il faut les arrêter !', `VerifiedBuild`=29981 WHERE (`ID`=106162 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Ces Ettins préparent un énorme bûcher afin de faire rôtir les membres de ma tribu ! Vous devez les arrêter avant qu\’ils ne les dévorent !', `VerifiedBuild`=29981 WHERE (`ID`=106161 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le prince des Ettins est mort ! Tirons-nous d\’ici !', `Text1_lang`='Le prince des Ettins est mort ! Tirons-nous d\’ici !', `VerifiedBuild`=29981 WHERE (`ID`=106149 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les chevaliers de la mort ne sont pas les seuls à pouvoir contrôler les Morts-vivants !', `VerifiedBuild`=29981 WHERE (`ID`=106126 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous ne voyez pas ? L\’eau commence déjà à s\’éclaircir. Les fiers Murlocs de Roc-Lointain vous remercient !', `VerifiedBuild`=29981 WHERE (`ID`=106042 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Murlocs de Roc-Lointain sont aux abois ! Leurs eaux, habituellement si pures, sont infestées par la vase. Il faut à tout prix renvoyer les Nagas eaux-troubles dans les profondeurs !', `VerifiedBuild`=29981 WHERE (`ID`=106041 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Saleté de Naga !', `VerifiedBuild`=29981 WHERE (`ID`=106007 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Mes Nagas s\’abattront sur Jandvik tel un raz-de-marée dévastateur !', `VerifiedBuild`=29981 WHERE (`ID`=105968 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mes guides me rapportent qu\’un nid de Kobolds s\’est installé dans les salles de l\’Écho. Une chasse aux rats, ça vous tente ?', `VerifiedBuild`=29981 WHERE (`ID`=105950 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tuez les Nagas !', `VerifiedBuild`=29981 WHERE (`ID`=105872 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quel courage ! Quelle ingéniosité ! Ah, quel soulagement de savoir qu\’$gun aventurier:une aventurière; de votre trempe se soucie du sort des Murlocs ! Merci !', `VerifiedBuild`=29981 WHERE (`ID`=105731 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quel culot ! Vous devez empêcher les Ondenoires d\’assombrir les cœurs de ces pauvres Murlocs de Roc-Lointain !', `VerifiedBuild`=29981 WHERE (`ID`=105730 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ce n\’est pas la première fois que je pique une tête dans l\’océan… Si seulement la SdPA s\’intéressait un peu plus aux Murlocs des mers chaudes !', `VerifiedBuild`=29981 WHERE (`ID`=105510 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='N\’est-ce pas évident ? Les Murlocs ont été chassés de chez eux ! On ne peut pas les abandonner à une mort certaine !', `VerifiedBuild`=29981 WHERE (`ID`=105508 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mrglrrlrlg ! Euh, je veux dire, bonjour ! Veuillez excuser mes manières, je fréquente ces Murlocs depuis plus longtemps que prévu.', `VerifiedBuild`=29981 WHERE (`ID`=105506 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Jandvik ne tombera jamais entre les griffes de vos Nagas ! Jamais !', `VerifiedBuild`=29981 WHERE (`ID`=105469 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Avez-vous fini de nous interrompre, Naga ?', `VerifiedBuild`=29981 WHERE (`ID`=105466 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Lâchez les Murlocs !', `Text1_lang`='Lâchez les Murlocs !', `VerifiedBuild`=29981 WHERE (`ID`=105220 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous souhaitez libérer une autre vague de Murlocs, $n ? Vous n\’avez qu\’un mot à dire.$b$bIl reste tant d\’œufs… Pris individuellement, les Murlocs sont relativement inoffensifs, mais en grand nombre, ils sont pour ainsi dire indestructibles.', `VerifiedBuild`=29981 WHERE (`ID`=105219 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Venez, $n ! Battons-nous côte à côte et décimons les rangs de ces infâmes Nagas !', `VerifiedBuild`=29981 WHERE (`ID`=105173 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous n\’êtes pas $gun:une; Naga ! Où est Brandolf ?', `VerifiedBuild`=29981 WHERE (`ID`=105170 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Je vois bien que vous n\’êtes pas de mèche avec ces Nagas, $R ! Faites-moi sortir de cette cage !', `VerifiedBuild`=29981 WHERE (`ID`=105168 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Val\’kyrs m\’emportent !', `VerifiedBuild`=29981 WHERE (`ID`=104837 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Val\’kyrs m\’emportent !', `VerifiedBuild`=29981 WHERE (`ID`=104831 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Finalement, nous avons trouvé un moyen de les remercier. Nous sommes tombés sur un Naaru subjugé par le Vide, une vision terrible. Il devait y avoir un moyen de le sauver !', `VerifiedBuild`=29981 WHERE (`ID`=104675 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Mon plan se déroulait à merveille, satanée limace ! Mes Nagas auraient dû vous tuer, vous et les crétins sous les ordres de Brandolf. Mais non ! Il a fallu que vous surviviez !', `VerifiedBuild`=29981 WHERE (`ID`=104636 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='En tant que dernière prétendante à la succession de Throndyr, il m\’incombe de guider notre peuple face aux envahisseurs, les Nagas sashj\’tar !', `VerifiedBuild`=29981 WHERE (`ID`=104570 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pourquoi faire appel à moi, Toryl ? Votre clan n\’est-il pas capable de se défendre seul face à ces Nagas ?', `Text1_lang`='Pourquoi faire appel à moi, Toryl ? Votre clan n\’est-il pas capable de se défendre seul face à ces Nagas ?', `VerifiedBuild`=29981 WHERE (`ID`=104565 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Harpies aiment les qui-brille.\n\nOn échange trésors contre cire.\n\nEnsuite, on fait la plus grosse bougie du monde !', `VerifiedBuild`=29981 WHERE (`ID`=103989 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je peux façonner le monde comme les Titans avant moi !', `VerifiedBuild`=29981 WHERE (`ID`=103060 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Qu\’ils viennent ! Voyez ce qui arrive à ceux qui osent défier le digne successeur du pouvoir des Titans !', `VerifiedBuild`=29981 WHERE (`ID`=103058 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Dagmyr a intérêt à me laisser quelques Nagas !', `VerifiedBuild`=29981 WHERE (`ID`=103021 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Par son courage et sa valeur exemplaires, Hyrja s\’est rendue digne de ce rite sacré. Elle s\’élèvera pour devenir l\’une de mes Val\’kyrs et l\’écho de son nom résonnera dans ces salles dorées pour l\’éternité.', `VerifiedBuild`=29981 WHERE (`ID`=102965 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Ces Nagas doivent payer le prix du sang ! Libérez mes frères et sœurs, qu\’ils puissent me rejoindre dans ce glorieux combat !', `VerifiedBuild`=29981 WHERE (`ID`=102862 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des gardeffroi… Attention à leurs formations ! Tenez bon ! Pour la Horde !', `VerifiedBuild`=29981 WHERE (`ID`=102597 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='D\’abord, les Troggs et maintenant, ça ? Quoi qu\’il arrive, les montagnards se battront jusqu\’au bout !', `VerifiedBuild`=29981 WHERE (`ID`=101669 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je ne suis pas un Naga, Stokalfr ! C\’est Brandolf qui m\’envoie !', `Text1_lang`='Je ne suis pas une Naga, Stokalfr ! C\’est Brandolf qui m\’envoie !', `VerifiedBuild`=29981 WHERE (`ID`=101383 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Par mes cornes, je vais exterminer ces Nagas de mes mains !', `VerifiedBuild`=29981 WHERE (`ID`=101379 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Qui t\’a appris à tirer ? Un Murloc ?', `VerifiedBuild`=29981 WHERE (`ID`=101334 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nom d\’un Naaru, j\’ai encore loupé mon coup !', `VerifiedBuild`=29981 WHERE (`ID`=101267 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Essayez d\’viser les défenseurs des Titans. Ces orbes, là, ce sont eux qui maintiennent les portails ouverts.', `VerifiedBuild`=29981 WHERE (`ID`=101151 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ce qu\’a fait cet estropié à la peau verte de cette jungle, c\’est terrible. Même les Ogres, ils ont pas autant la rage de détruire ce monde !', `VerifiedBuild`=29981 WHERE (`ID`=100967 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Oui, je suis resté ici quand Nesingwary est parti. Et si vous alliez voir notre ami des Murlocs ?', `VerifiedBuild`=29981 WHERE (`ID`=100391 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Cornes-Célestes ! Décollez, et montrez à ces Harpies et à leurs rocs la véritable signification du mot combat !', `VerifiedBuild`=29981 WHERE (`ID`=100323 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='<Le Satyre blessé se renfrogne en vous voyant approcher. Il ne lui reste plus longtemps à vivre.>$b$bAlors, vous venez terminer ce que votre archidruide a commencé, $R ? Vous croyez avoir remporté la victoire, stupides mortels… mais Malfurion est à la merci du maître, à présent.$b$bCe crétin s\’est jeté tête baissée dans notre piège… Ha ha haaaaa…', `VerifiedBuild`=29981 WHERE (`ID`=100274 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Bourbie s\’en sort à merveille ! Ses compagnons et lui ne ménagent pas leur peine. Quand ils auront atteint l\’âge adulte, je crois bien que la tribu Rochemare constituera un groupe de Murlocs soudés, promis à un brillant avenir. Et alors, qui sait quelles prouesses ils pourront accomplir ? Je vais rester ici en tant qu\’observateur. Merci infiniment pour votre aide, $p.', `VerifiedBuild`=29981 WHERE (`ID`=100171 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Murlocs rochemares prennent un malin plaisir à provoquer des naufrages avec leur phare de fortune. C\’est une espèce fascinante, mais ceux-ci sont particulièrement féroces.\n\nIl nous faut sauver ce littoral ! Je vous présente Bourbie, un petit Murloc que j\’élève depuis son plus jeune âge. Nous devons l\’aider à grandir pour qu\’il guide ses congénères têtards sur le droit chemin.', `VerifiedBuild`=29981 WHERE (`ID`=99905 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='C\’est une catastrophe… mais tout espoir n\’est pas perdu ! Pas tant que les chars roulent et que nos coucous sillonnent l\’espace aérien ! Le monde ne disparaîtra pas sans que les Gnomes aient leur mot à dire !', `VerifiedBuild`=29981 WHERE (`ID`=99644 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mais… vous pas vrai Kobold !', `VerifiedBuild`=29981 WHERE (`ID`=98867 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Eh bien, on dirait que vous êtes $gdevenu:devenue; la coqueluche de la Ligue des explorateurs !$b$bApparemment, le vieux Corne-d\’Ébène a entendu parler d\’moi et il m\’a demandé d\’vous aider dans votre périple.$b$bJ\’ai sorti mon bon vieux Talas de sa retraite pour l\’occasion, j\’espère que ça vous dérange pas. Paraît que des Ettins seraient impliqués, alors j\’me suis dit que l\’artillerie lourde s\’rait pas d\’trop.', `VerifiedBuild`=29981 WHERE (`ID`=98739 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je vous déclare officiellement Valarjar ! À charge pour vous de redorer le blason de ces salles avec le concours de mes Val\’kyrs !', `VerifiedBuild`=29981 WHERE (`ID`=98244 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je peux vous fournir les plans de navire dont vous avez besoin, mais vous devez d\’abord prouver votre valeur aux Chasseurs de têtes de Vol\’jin, ici, dans la jungle de Tanaan.', `VerifiedBuild`=29981 WHERE (`ID`=97844 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mon peuple a connu bien trop de souffrances. C\’est l\’avènement du Fléau qui nous a forcés à fuir Gilnéas, il y a tant d\’années.$B$BEt aujourd\’hui, nous voilà menacés par des Morts-vivants sortis de la forteresse au nord !$B$BJe défendrai ce village jusqu\’à mon dernier souffle.', `VerifiedBuild`=29981 WHERE (`ID`=97342 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Quel soulagement de voir mes frères sains et saufs ! Les Satyres ont été vaincus, mais je crains fort que notre combat ne fasse que commencer.$B$BSi ce qu\’ils ont dit est vrai, nous devons poursuivre notre veille au sein du Rêve d\’émeraude, aujourd\’hui plus que jamais.', `VerifiedBuild`=29981 WHERE (`ID`=97153 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous allons y remédier… corriger les erreurs du passé et tuer les Satyres jusqu\’au dernier ! Ils paieront cette malédiction de leur sang !', `VerifiedBuild`=29981 WHERE (`ID`=97146 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Après la guerre des Anciens, les Satyres qui avaient survécu furent regroupés. J\’étais d\’avis de les exécuter jusqu\’au dernier pour leur faire payer leurs crimes, mais notre nature charitable finit par l\’emporter et ceux qui souhaitaient les épargner eurent le dernier mot.$b$bC\’est ainsi que les Satyres furent placés dans un sommeil éternel, profondément enfouis sous les racines de Shaladrassil. Pourtant, aujourd\’hui, sans que l\’on sache comment, les voilà réveillés.$B$BCette fois, nous ne commettrons pas la même erreur, même si je dois tous les tuer moi-même !', `VerifiedBuild`=29981 WHERE (`ID`=97139 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Nagas sont connus pour amasser toutes sortes de potions. Qui sait, ils sont peut-être en possession des bouchons dont nous avons besoin ? Et le meilleur endroit où chercher, c\’est dans l\’Œil d\’Azshara lui-même !', `VerifiedBuild`=29981 WHERE (`ID`=97041 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le courroux de la Légion vous détruira !', `VerifiedBuild`=29981 WHERE (`ID`=96892 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Sur ce bouclier a été gravée une représentation d\’Eyir devant l\’entrée du caveau des Titans.\n\nElle semble accueillir une championne ailée des vierges guerrières.', `VerifiedBuild`=29981 WHERE (`ID`=96740 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Eyir, mère des Val\’kyrs. Je te laisse une chance de te rendre.', `VerifiedBuild`=29981 WHERE (`ID`=96579 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La tailleuse Tanithria a besoin de paillettes de soufre pour un patron.', `Text1_lang`='La tailleuse Tanithria a besoin de paillettes de soufre pour un patron.', `VerifiedBuild`=29981 WHERE (`ID`=96193 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est un assemblage des Titans ! Il devait garder l\’objet que recherche Sylvanas.', `VerifiedBuild`=29981 WHERE (`ID`=96149 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='C\’est un honneur de combattre à vos côtés, $n. Votre présence m\’a inspirée dès notre première rencontre, dans cet horrible tunnel derrière la Porte des ténèbres.$b$bK\’ara aussi est capable de voir votre force intérieure. Êtes-vous $gprêt:prête; à parler au Naaru ?', `VerifiedBuild`=29981 WHERE (`ID`=95895 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Avez-vous entendu quelque chose ? Le Naaru vous a-t-il parlé ?', `VerifiedBuild`=29981 WHERE (`ID`=95752 AND `locale`='frFR');
