UPDATE `broadcast_text_locale` SET `Text1_lang`='Ces animaux se battent sans le moindre honneur. Notre peuple a-t-il un jour été aussi sauvage ?', `VerifiedBuild`=29981 WHERE (`ID`=94821 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Je vous dois la vie. Je retourne au camp !', `VerifiedBuild`=29981 WHERE (`ID`=94820 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Satyres affluent de toute part… Comment pouvons-nous espérer les vaincre ?', `VerifiedBuild`=29981 WHERE (`ID`=94470 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='La Troisième flotte arrive en renfort !', `VerifiedBuild`=29981 WHERE (`ID`=94240 AND `locale`='frFR');
