UPDATE `broadcast_text_locale` SET `Text_lang`='|TInterface\\Icons\\spell_fel_elementaldevastation.blp:20|tL\’|cFFFF0000|Hspell:182008|h[Énergie latente]|h|r de $n réagit violemment lorsqu\’$gil:elle; pénètre dans la|cFFFF0000|Hspell:179582|h[Fissure grondante]|h|r !', `Text1_lang`='|TInterface\\Icons\\spell_fel_elementaldevastation.blp:20|tL\’|cFFFF0000|Hspell:182008|h[Énergie latente]|h|r de $n réagit violemment lorsqu\’$gil:elle; pénètre dans la|cFFFF0000|Hspell:179582|h[Fissure grondante]|h|r !', `VerifiedBuild`=29981 WHERE (`ID`=94032 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Naaru n\’ont pas tenu leurs promesses. Notre nouveau maître nous a fait don de véritables pouvoirs !', `Text1_lang`='Les Naaru n\’ont pas tenu leurs promesses. Notre nouveau maître nous a fait don de véritables pouvoirs !', `VerifiedBuild`=29981 WHERE (`ID`=93936 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ces Harpies coexistent paisiblement avec nous depuis une éternité.$b$bQu\’est-ce qui a bien pu les rendre si agressives ?', `VerifiedBuild`=29981 WHERE (`ID`=93796 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='À moi, $p ! Les Nagas ne vont pas tarder à réussir leur percée !', `VerifiedBuild`=29981 WHERE (`ID`=93764 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les chansons des Titans d\’Ulduar sont extrêmement difficiles à trouver de nos jours.', `VerifiedBuild`=29981 WHERE (`ID`=93712 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Besoin d\’aide avec votre liste de course ?\n\nPour le caisson de basses, c\’est simple. Les Ogres adorent écouter de la musique puissante dans l\’arène de Sang. Les spectateurs ne sont pas là pour se battre. Vous n\’avez qu\’à leur prendre !\n\nJ\’ai vu un Laz-tron au poste de Sifflepince quand j\’y suis allé pour faire un bœuf.\n\nNous ne trouverons jamais de véritable amplificateur phonique, mais un gros morceau de métal récupéré sur un de ces assemblages solaires arakkoa devrait faire l\’affaire.\n\nQuant au condensateur, vous devrez le récupérer sur un déchiqueteur de la Horde de Fer. \n\nOh, et le type de bois dont j\’ai besoin doit être vraiment ancien, donc votre meilleure option en Draenor est probablement le séjour de la Flore éternelle.', `Text1_lang`='Besoin d\’aide avec votre liste de course ?\n\nPour le caisson de basses, c\’est simple. Les Ogres adorent écouter de la musique puissante dans l\’arène de Sang. Les spectateurs ne sont pas là pour se battre. Vous n\’avez qu\’à leur prendre !\n\nJ\’ai vu un Laz-tron au poste de Sifflepince quand j\’y suis allée pour faire un bœuf.\n\nNous ne trouverons jamais de véritable amplificateur phonique, mais un gros morceau de métal récupéré sur un de ces assemblages solaires arakkoa devrait faire l\’affaire.\n\nQuant au condensateur, vous devrez le récupérer sur un déchiqueteur de la Horde de Fer. \n\nOh, et le type de bois dont j\’ai besoin doit être vraiment ancien, donc votre meilleure option en Draenor est probablement le séjour de la Flore éternelle.', `VerifiedBuild`=29981 WHERE (`ID`=93686 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des Murlocs ? Noooon ! Pourquoi fallait-il que ce soit des Murlocs ?', `Text1_lang`='Des Murlocs ? Noooon ! Pourquoi fallait-il que ce soit des Murlocs ?', `VerifiedBuild`=29981 WHERE (`ID`=93472 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Reine Azshara… vous… C\’est VOUS qui êtes à la tête des Nagas ?', `VerifiedBuild`=29981 WHERE (`ID`=93458 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Au temps jadis, les Titans façonnèrent Azeroth à l\’aide de puissants outils, les piliers de la Création. Ces piliers sont la clé qui condamnera à jamais la porte par laquelle la Légion se déverse dans notre monde.', `VerifiedBuild`=29981 WHERE (`ID`=93321 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Esprit à vous doit être fort, comme Ogre ! Si vous être faible, alors vous mourir. Ça pas être compliqué.', `VerifiedBuild`=29981 WHERE (`ID`=93075 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='L\’heure est venue de payer le prix du fer, Skrogs !', `Text1_lang`='L\’heure est venue de payer le prix du fer, Skrogs !', `VerifiedBuild`=29981 WHERE (`ID`=91836 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='L\’|c00FFFF00|Hspell:178021|h[Évènement : Puits de feu des Ogres]|h|r commence sur la cime de la Brute dans 3 minutes.', `VerifiedBuild`=29981 WHERE (`ID`=91710 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’ai dit à Appaloosa Course-Sauvage que j\’irais explorer tout A\’shran, hormis la zone de l\’Autel. Les Ogres, passe encore, mais les fantômes ? Désolé, ça me glace les sangs.', `VerifiedBuild`=29981 WHERE (`ID`=91280 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ça territoire ogre ! Toi pas Ogre !', `Text1_lang`='Ça territoire ogre ! Toi pas Ogre !', `VerifiedBuild`=29981 WHERE (`ID`=91172 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Cela me semble un peu tiré par les cheveux. Je n\’ai rien vu qui puisse relier les Titans à ce monde.', `VerifiedBuild`=29981 WHERE (`ID`=91133 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est pas les piaules, le problème. Où que tu regardes, y a soit un Ogre prêt à te briser le crâne, soit un de ces benêts de l\’Alliance qui te pointe une épée sous le menton !', `VerifiedBuild`=29981 WHERE (`ID`=90801 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Assez ri ! Renvoyons ces Ogres à Cognefort !', `VerifiedBuild`=29981 WHERE (`ID`=90398 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Alors comme ça, les Ogres aiment nous jeter des caillasses, hein ?', `VerifiedBuild`=29981 WHERE (`ID`=89869 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Apparemment, les Ogres de la cime de la Brute s\’en prennent à nos troupes à l\’aide de gros bestiaux qui leur balancent des rochers !', `VerifiedBuild`=29981 WHERE (`ID`=89868 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je ne sais pas pourquoi Harrison Jones nous a demandé de venir l\’aider dans ses fouilles. À chaque fois que je me lance à la recherche d\’un artéfact, un Ogre tente de me couper en deux !', `VerifiedBuild`=29981 WHERE (`ID`=89839 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Très chers Ogres, très chères Ogresses, l\’arène de sang va devenir le théâtre d\’un évènement historique ! Mogor, le champion actuel de l\’arène, va défendre son titre contre $n et ses compagnons d\’armes. Le spectacle va valoir le coup d\’œil !', `VerifiedBuild`=29981 WHERE (`ID`=87696 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Aux armes ! Tous à vos postes ! Aujourd\’hui, nous avons affaire aux Ogres.', `VerifiedBuild`=29981 WHERE (`ID`=87628 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Ces ossements sont énormes ! Ils doivent appartenir à un Ogre… un Ogre GÉANT, si ça se trouve !', `VerifiedBuild`=29981 WHERE (`ID`=86897 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le Naaru… c\’est impossible !', `VerifiedBuild`=29981 WHERE (`ID`=86767 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tenez bon, $n ! Le Naaru est en train de se transformer en dieu du Vide… nous allons devoir combattre !', `VerifiedBuild`=29981 WHERE (`ID`=86763 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Approchez, mesdames et mes Ogres. Au programme dans l\’arène de Sang, carnage et dévastation pour le seul plaisir de vos yeux ! Ce combat historique pour le titre de champion sanglant va opposer $n, qui arrive d\’on ne sait trop où, à Katsuo, de la Lame-Ardente !', `VerifiedBuild`=29981 WHERE (`ID`=86343 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Capitaine ! Ils sont sur les étoiles de Fer !', `VerifiedBuild`=29981 WHERE (`ID`=85927 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est vraiment la poisse, mec ! J\’ai repéré le meilleur coin pour pêcher dans les parages, mais les élémentaires et les Ogres, ils ont tout pété mon matériel. \n\nMaintenant j\’ai besoin d\’une canne, d\’un moulinet et d\’un appât vaudou spécial pour attirer les grosses prises qui se cachent dans les algues.', `VerifiedBuild`=29981 WHERE (`ID`=85674 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ces Ogres ne seraient pas fichus de reconnaître un artéfact de valeur s\’il leur tombait dans les mains accompagné d\’une note disant « attention, précieux ». En fait, ils sont à peine capables de distinguer leur tête de leur… enfin… vous voyez ce que je veux dire ?', `VerifiedBuild`=29981 WHERE (`ID`=85534 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Depuis que le « roi-sorcier » Mar\’gok est arrivé au pouvoir et qu\’il a découvert ces artéfacts, c\’est briseur gangrené par-ci et briseur de feu par-là. Il s\’imagine que ses nouveaux joujoux vont lui permettre de se passer de la Légion !$b$bCet empire est né de la force des Ogres, de la solidité de leurs lames, et je ne me suis pas privé de lui dire !', `VerifiedBuild`=29981 WHERE (`ID`=85354 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Attendez, mes amis ! Cette personne ne semble pas faire partie des serviteurs des Ogres.', `VerifiedBuild`=29981 WHERE (`ID`=85220 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Salut, Anna !', `VerifiedBuild`=29981 WHERE (`ID`=85165 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tuez les Ogres ! Attendez… c\’est vrai qu\’il n\’y a plus d\’ogres… ils ont disparu il y a longtemps déjà. Il ne reste d\’eux que ces ruines, et toute trace doit en disparaître à jamais…', `VerifiedBuild`=29981 WHERE (`ID`=85057 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Où allez-vous, mes frères ? Les Ogres ont disparu il y a un millier d\’années seulement ! Ils peuvent revenir à tout moment, nous devons rester vigilants !', `VerifiedBuild`=29981 WHERE (`ID`=85051 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Désormais, je suis libre de tuer qui je veux et quand je veux ! Retrouvez-moi au tertre des Ogres quand vous aurez terminé, et ensemble, nous irons leur arracher les yeux !', `VerifiedBuild`=29981 WHERE (`ID`=85013 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Marchandises seulement pour Ogres et gladiateurs ! Si toi ni l\’un ni l\’autre, moi écraser ta tête avec marteau !', `VerifiedBuild`=29981 WHERE (`ID`=84777 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous ne pouvons pas laisser cette relique aux mains des Ogres ! Sa place est dans une collection privée !', `VerifiedBuild`=29981 WHERE (`ID`=84640 AND `locale`='frFR');
