UPDATE `broadcast_text_locale` SET `Text_lang`='Après tout ce que j\’ai traversé, qui aurait cru que je me retrouverais ici ?$b$bIl n\’y a rien de tel que d\’étriper des Ogres ! Et en plus, ça me permet de faire suer mes anciens chefs de la Horde de Fer, ce ramassis de péteux arrogants !', `VerifiedBuild`=29981 WHERE (`ID`=82857 AND `locale`='frFR');
