UPDATE `broadcast_text_locale` SET `Text_lang`='Justement, cher Ogre, c\’est là que tu te trompes. Vois-tu, c\’est nous qui allons vous écraser, aujourd\’hui. Thaelin ?', `VerifiedBuild`=29981 WHERE (`ID`=80304 AND `locale`='frFR');
