UPDATE `broadcast_text_locale` SET `Text_lang`='Sens-tu la puissance dont ils se nourrissent ? (C\’est le Naaru de Nagrand !)', `VerifiedBuild`=29981 WHERE (`ID`=76717 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Très bien, mettons à l\’épreuve vos connaissances de l\’histoire ! Comment s\’appelle le premier Satyre créé ?', `VerifiedBuild`=29981 WHERE (`ID`=76225 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Très bien, mettons à l\’épreuve vos connaissances de l\’histoire ! Les Draeneï aiment plaisanter sur la signification du mot Exodar dans la langue des Naaru.', `VerifiedBuild`=29981 WHERE (`ID`=76223 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Très bien, mettons à l\’épreuve vos connaissances de l\’histoire ! Quelle épée puissante pouvait châtier les Morts-vivants et les transformer en un tas de cendres ?', `VerifiedBuild`=29981 WHERE (`ID`=76203 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Très bien, mettons à l\’épreuve vos connaissances de l\’histoire ! Cette installation, située dans le marécage de Zangar, était contrôlée par les Nagas qui tentaient de drainer une ressource limitée et précieuse en Outreterre : l\’eau.', `VerifiedBuild`=29981 WHERE (`ID`=76201 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Très bien, mettons à l\’épreuve vos connaissances de l\’histoire ! Dites-moi, $ghéros:héroïne;, comment s\’appellent les Murlocs morts-vivants ?', `VerifiedBuild`=29981 WHERE (`ID`=76189 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les tisserands sont des arcanistes spécialisés dans la chronomancie : l\’art de tisser le temps.\n\nAu sein des marcheurs du temps, nous seuls sommes à même de restaurer les voies du temps, d\’ouvrir des portails temporels ou autres tâches qui nous incombent.\n\nAutrefois, tout cela était on ne peut plus simple pour le Vol draconique de bronze, mais hélas, ce n\’est plus le cas.', `VerifiedBuild`=29981 WHERE (`ID`=75802 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='|TInterface\\Icons\\ability_garrosh_siege_engine.blp:20|t Le capitaine de la flotte a détecté un groupe ! Tir d\’|cFFFF0000|Hspell:147047|h[Étoile de Fer instable]|h|r !', `VerifiedBuild`=29981 WHERE (`ID`=75799 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le val est à moitié détruit ! Ces étrangers sont plus destructeurs que les mantides et les Mogu réunis !', `VerifiedBuild`=29981 WHERE (`ID`=75748 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Une délicieuse prêtresse de la Lune. Vous allez faire un morceau de choix, ma chère Délas.', `VerifiedBuild`=29981 WHERE (`ID`=75516 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quel adversaire pourrait se montrer plus redoutable que les Mogu que nous avons combattus ?', `VerifiedBuild`=29981 WHERE (`ID`=75449 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La prêtresse de la Lune a également quelque chose à vous demander.', `VerifiedBuild`=29981 WHERE (`ID`=75371 AND `locale`='frFR');
