UPDATE `broadcast_text_locale` SET `Text_lang`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|tDes |cFFFF0000ingénieurs de siège|r apparaissent dans les ailes et commencent à incanter |cFFFF0000|Hspell:144616|h[Alimentation de l\’étoile de Fer]|h|r !', `VerifiedBuild`=29981 WHERE (`ID`=74586 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les champions du roi ont réussi : la tempête est passée ! En avant, Sombrefer ! NOUS MARCHONS AU COMBAT !', `VerifiedBuild`=29981 WHERE (`ID`=73458 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='« Nous ne pouvons pas vous aider », dit le Nain marteau-hardi, « car si nous ne surveillons pas les Sombrefer, ils battront les Barbe-de-Bronze et s\’empareront de Forgefer ! »', `VerifiedBuild`=29981 WHERE (`ID`=73225 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='« Nous ne pouvons pas vous aider », dit le Nain barbe-de-bronze, « car si nous ne surveillons pas les Sombrefer, ils battront les Marteaux-Hardis et s\’empareront de Forgefer ! »', `VerifiedBuild`=29981 WHERE (`ID`=73224 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La chef Bazzelcol trouve qu\’on manque de combattants et que le spectacle n\’est pas à la hauteur.\n\nElle a parlé de « motivation » avant de déclarer que « nous devions donner aux combattants de meilleures raisons de se battre. » !\n\nElle a donc ordonné la construction de ce zeppelin. Il propose une vue imprenable sur le combat, de l\’alcool jusqu\’à plus soif, et le plaisir de pouvoir narguer ceux de vos amis qui n\’y ont pas leurs entrées, car… en dessous du rang 6, personne n\’y est admis.\n\nVous voulez monter à bord ? Alors continuez d\’enchaîner les victoires, l\’athlète.', `VerifiedBuild`=29981 WHERE (`ID`=73179 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Une |cFFFF2222[enclume foudroyante]|r est en surcharge ! Cliquez pour provoquer une |cFFFF2222|Hspell:138834|h[Éruption de foudre]|h|r !', `VerifiedBuild`=29981 WHERE (`ID`=73003 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quand arrive la pleine lune, les fées fléchetteuses des bois des Perdus, dans la forêt de Jade, muent et perdent leurs écailles. L\’évènement survient d\’ordinaire tard dans la nuit et c\’est un spectacle de toute beauté. $b $b Leurs écailles émettent une lueur de jade et tombent à la surface de l\’eau, où elles attirent irrésistiblement les dipneustes de jade ! Un peu comme les papillons près d\’une lanterne ! $b $b Mais attention, mieux vaut éviter de déranger les Mogu… ils ne sont pas vraiment amicaux, dans leur genre.', `VerifiedBuild`=29981 WHERE (`ID`=72893 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ahah ! Ça fait du bien de refaire couler le sang. Alliance ou Mogu, ça n\’a aucune importance.', `VerifiedBuild`=29981 WHERE (`ID`=72797 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Démembrement de Mogu !', `VerifiedBuild`=29981 WHERE (`ID`=72746 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Crève en souffrant, Mogu !', `VerifiedBuild`=29981 WHERE (`ID`=72745 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mort aux Mogu !', `VerifiedBuild`=29981 WHERE (`ID`=72743 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Voulez-vous vraiment supprimer le Codex de Xerrath ?', `Text1_lang`='Voulez-vous vraiment supprimer le Codex de Xerrath ?', `VerifiedBuild`=29981 WHERE (`ID`=72671 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Mogu, les mantides, les sauroks… ce sont plus que des adversaires à terrasser. Ce sont des mystères, des énigmes à résoudre !', `VerifiedBuild`=29981 WHERE (`ID`=72619 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Partir en montagne à dos de yack sans « traînechance » calcifié ? Faudrait avoir un problème dans sa tête ! J\’en vends… et pas cher.', `VerifiedBuild`=29981 WHERE (`ID`=72546 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Eskrokar, vous avez le nez trop étroit pour flairer la chance… et vous sentez le yack pas propre.', `VerifiedBuild`=29981 WHERE (`ID`=72540 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le roi-tonnerre s\’est imprégné des pouvoirs d\’un gardien des Titans. Nous devons les lui reprendre !', `VerifiedBuild`=29981 WHERE (`ID`=72375 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah ! La pièce finale du puzzle. Le roi-tonnerre s\’empara des pouvoirs de Ra-Den, de l\’essence même des titans. Il unifia les Mogu en un empire et tenta de poursuivre l\’œuvre des titans. Il se prenait évidemment pour un dieu !', `VerifiedBuild`=29981 WHERE (`ID`=72372 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Une autre pièce du puzzle ! Elle a été gravée par les Mogu. Ils étaient frustrés : mille ans sans ordres de leurs maîtres et leurs corps étaient devenus de chair. Les Mogu ont commencé à se disputer les uns les autres.', `VerifiedBuild`=29981 WHERE (`ID`=72370 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les pièces du puzzle commencent à s\’assembler. Les Mogu ont été créés pour garder le val pour les titans. Mais le garder de quoi ? Les Dieux très anciens étaient-ils encore une menace ?', `VerifiedBuild`=29981 WHERE (`ID`=72367 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Mogu servaient un gardien des Titans. Son nom était « Ra ». En langue mogu, « Ra Den » signifie « Maître Ra ». Fascinant ! Je dois en apprendre plus !', `VerifiedBuild`=29981 WHERE (`ID`=72363 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Une autre pierre ! Qu\’avons-nous appris ? La « malédiction de la chair » rendit les Mogu mortels. Ah… mais plus tard, ils découvrirent un moyen d\’inverser le processus. Une race intelligente.', `VerifiedBuild`=29981 WHERE (`ID`=72362 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Que devaient garder les Mogu ? Ou que devaient-ils détruire ? Il nous manque les dernières pièces du puzzle. Mais vous allez m\’aider à les découvrir !', `VerifiedBuild`=29981 WHERE (`ID`=72357 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous savons maintenant que les Mogu sont liés aux titans. Mais de nombreux mystères demeurent. Pourquoi étaient-ils ici ? Pourquoi en Pandarie ?', `VerifiedBuild`=29981 WHERE (`ID`=72356 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Mogu, ah ! Les Mogu ! Leur esprit était si étriqué ! Ils ont été conçus pour servir, et lorsqu\’ils perdirent leurs maîtres, ils se servirent eux-mêmes.', `VerifiedBuild`=29981 WHERE (`ID`=72350 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Mogu ont été renversés, après tout ! C\’est ÇA que devrait retenir le roi-tonnerre. Au fait, c\’est à vous de jouer.', `VerifiedBuild`=29981 WHERE (`ID`=72316 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='L\’archimage Modera a choisi une stratégie on-ne-peut-plus directe : vaincre les Mogu par la force. Mais je pense qu\’en cherchant davantage, nous pourrions bien découvrir leurs faiblesses.', `VerifiedBuild`=29981 WHERE (`ID`=72221 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='<L\’Elfe de sang semble en état de choc.>$B$BC\’était horrible… atroce ! Quand nous avons été capturés, un Mogu m\’a saisi à la gorge. J\’ai cru ma dernière heure arrivée, mais au lieu de me tuer, le Mogu a resserré son étreinte, avant de me tirer brutalement à lui. J\’ai suffoqué, comme si l\’air avait déserté mes poumons.$B$BJ\’ai senti tout mon être se tordre, se déchirer… Ma peau et mes os semblaient avoir pris feu. Soudain, je me suis senti flotter hors de mon corps.$B$BLe Mogu m\’a dévisagé en ricanant, et j\’ai su que mon âme était destinée à souffrir jusqu\’à la fin des temps.$B$BAvez-vous déjà dû faire face à vos angoisses les plus profondes, $c ? Moi… oui.$B$B<L\’Elfe de sang frémit et se tait.>', `VerifiedBuild`=29981 WHERE (`ID`=72217 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La rancœur s\’amplifia chez les Mogu. Bien des générations plus tard, quand le roi-tonnerre les unifia, ils reprirent leur œuvre !', `VerifiedBuild`=29981 WHERE (`ID`=72131 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous avez vu les golems qui arpentent ces chemins, $c ? Des esprits soumis par les Zandalari et destinés à les servir jusqu\’à la fin des temps.$b$bLes Mogu et les Zandalari se ressemblent peut-être plus que nous ne le pensions.', `VerifiedBuild`=29981 WHERE (`ID`=71805 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les prêtres imprègnent le gardien du pouvoir de leurs Loas ! Il faut les arrêter !', `VerifiedBuild`=29981 WHERE (`ID`=71793 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les prêtres imprègnent le gardien du pouvoir de leurs Loas ! Il faut les arrêter !', `VerifiedBuild`=29981 WHERE (`ID`=71784 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Regardez en bas ! Nos assauts répétés sur la ville et les cryptes ont dérouté l\’ennemi. Les Mogu et les Zandalari craignent déjà la puissance de la Horde.', `VerifiedBuild`=29981 WHERE (`ID`=71648 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ils ont chanté « Tuer les Mogu » toute la journée. Quoi qu\’Aethas vous ai demandé de faire, ça fonctionne.', `VerifiedBuild`=29981 WHERE (`ID`=71556 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Comment les Mogu ont-ils pu commettre une telle atrocité ? Heureusement que vous êtes $garrivé:arrivée; au bon moment.', `Text1_lang`='Comment les Mogu ont-ils pu commettre une telle atrocité ? Heureusement que vous êtes $garrivé:arrivée; au bon moment.', `VerifiedBuild`=29981 WHERE (`ID`=71529 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Comment les Mogu ont-ils pu commettre une telle atrocité ? Heureusement que vous êtes $garrivé:arrivée; au bon moment.', `Text1_lang`='Comment les Mogu ont-ils pu commettre une telle atrocité ? Heureusement que vous êtes $garrivé:arrivée; au bon moment.', `VerifiedBuild`=29981 WHERE (`ID`=71511 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Mogu sont nos ennemis. Ils cherchent à nous éradiquer de ce monde. Pourquoi devrions-nous croire aux mythes créateurs dont ils nous abreuvent ?', `VerifiedBuild`=29981 WHERE (`ID`=71459 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Mogu prétendent nous avoir créés… avoir modelé notre forme actuelle. Ne croyez pas leurs mensonges.$b$bNous nous sommes modelés nous-mêmes et nous descendons du plus grand des créateurs, Kros lui-même !', `VerifiedBuild`=29981 WHERE (`ID`=71457 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Regardez-vous, propre-écaille. Vous voulez que les Mogu vous attaquent ? Vous voulez devenir leur esclave ?$b$bProtégez-vous, $gmon frère:ma sœur;. Encrassez-vous.', `VerifiedBuild`=29981 WHERE (`ID`=71449 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Mogu cherchent à nous détruire. Les Mogu sont nos ennemis. Je tuerai jusqu\’au dernier ceux qui s\’approchent de nos terres.$b$bEst-ce que vous m\’aiderez ?', `VerifiedBuild`=29981 WHERE (`ID`=71442 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je surveille nos nouveaux ennemis.$b$bLes Trolls qui se tiennent droit se sont alliés aux Mogu, mais les autres envahisseurs les combattent.$b$bBah ! Je m\’en fiche. Leurs querelles nous ont donné beaucoup de nouveaux cadavres à récolter. Les Crasselames n\’ont jamais été aussi forts.', `VerifiedBuild`=29981 WHERE (`ID`=71437 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Mogu mentent à mon peuple. Ils nous disent que nous sommes leurs créatures, qu\’ils ont modelé notre chair pour lui donner la forme que nous avons. Ils déclarent que nous leur devons notre existence.$b$bHé bien je DÉFIE les mogu ! Ils n\’ont pas de pouvoir sur nous ! Ils ignorent comment nous vivons, ce que nous voyons, ce que nous ressentons ! Ils ne peuvent pas voir dans nos âmes !$b$bSeul Kros, le grand créateur sait ce qu\’elles contiennent. Kros sait et Kros comprend. C\’est lui qui vous a donné votre force, sauroks. Vous ne devez rien aux Mogu.', `VerifiedBuild`=29981 WHERE (`ID`=71425 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Tous ceux qui ne sont pas déjà debouts sont morts. Garde-Sanglante n\’obtiendra pas d\’autres combattants.\n\nBon… Je meurs de faim. On va se chercher de quoi manger ?', `VerifiedBuild`=29981 WHERE (`ID`=71247 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Bienvenue dans la jungle, terrible jungle, $R, vous serez $gmort:morte; ce soir !', `Text1_lang`='Bienvenue dans la jungle, terrible jungle, $R, vous serez $gmort:morte; ce soir !', `VerifiedBuild`=29981 WHERE (`ID`=71002 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Appelez votre roi, $R ! Faites-le venir !', `Text1_lang`='Appelez votre roi, $R ! Faites-le venir !', `VerifiedBuild`=29981 WHERE (`ID`=70994 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ces « Mogu », ils font de la magie noire et tordue, ici.', `VerifiedBuild`=29981 WHERE (`ID`=70799 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pathétique ! Vos Mogu et vous n\’êtes rien face à la puissance de la Horde !', `VerifiedBuild`=29981 WHERE (`ID`=70164 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='On n\’a pas toute la nuit. Dépêchez-vous un peu !', `VerifiedBuild`=29981 WHERE (`ID`=70139 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous avez obtenu un peu de puissance des Mogu ! Ramassez des runes et votre pouvoir grandira.', `VerifiedBuild`=29981 WHERE (`ID`=70095 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='QUOI ?! Vous avez vu où les Mogu ont caché la Cloche divine ? Je vais prévenir le territoire du Lion immédiatement. Nous devons nous en emparer avant Garrosh. Nous vous contacterons dès que nous l\’aurons trouvée.', `VerifiedBuild`=29981 WHERE (`ID`=70083 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Attendez… Vous n\’êtes pas des Mogu. Des intrus !', `VerifiedBuild`=29981 WHERE (`ID`=69695 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Là où ça devient compliqué, c\’est qu\’il s\’est fait emprisonner dans le jade au cours d\’un combat contre un Mogu que l\’on surnomme le « seigneur de guerre de jade ».', `VerifiedBuild`=29981 WHERE (`ID`=69530 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah bon ? On dirait que j\’ai beaucoup à apprendre de ces Mogu.', `VerifiedBuild`=29981 WHERE (`ID`=69230 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous ne nous aviez pas prévenus au sujet des Mogu, chef de guerre. Ces statues se sont animées !', `VerifiedBuild`=29981 WHERE (`ID`=69091 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Affrontez le courroux d\’Obsidion !', `VerifiedBuild`=29981 WHERE (`ID`=68748 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Déchire-les, Éventreur !', `VerifiedBuild`=29981 WHERE (`ID`=68734 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Toi pas Ogre. Pourquoi toi gagner ?', `VerifiedBuild`=29981 WHERE (`ID`=68541 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quand j\’en aurai fini avec vous, vous nagerez au milieu des Murlocs !', `VerifiedBuild`=29981 WHERE (`ID`=68523 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’empêche les autres Mogu d\’entrer dans le palais. Dépêchez-vous !', `VerifiedBuild`=29981 WHERE (`ID`=68320 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je peux les sentir, les esprits des Mogu morts depuis des lustres !', `VerifiedBuild`=29981 WHERE (`ID`=67822 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous savez, j\’ai été beaucoup coincé dans ces cages à observer les Mogu, mais je suis à peu près certain de jamais avoir vu de Mogu femelle. Comment ça se fait ?', `VerifiedBuild`=29981 WHERE (`ID`=67055 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quand les Mogu ont-ils appris à créer des portails magiques ?', `Text1_lang`='Depuis quand les Mogu sont-ils capables de créer des portails magiques ?', `VerifiedBuild`=29981 WHERE (`ID`=67003 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='D\’où diable venaient tous ces Mogu ?', `Text1_lang`='D\’où viennent tous ces Mogu ?', `VerifiedBuild`=29981 WHERE (`ID`=66998 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pitoyables vermisseaux sans ailes. Vous entrez dans MON domaine, et j\’écouterai avec délectation vos hurlements d\’agonie quand vous tomberez de cette terrasse !', `VerifiedBuild`=29981 WHERE (`ID`=66433 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='« Nos dos ont été durcis par les fouets des Mogu », leur dit-il. « Nos bras sont devenus plus forts d\’avoir construit leurs forteresses. Nos esprits sont aiguisés d\’avoir travaillé aux côtés de notre ennemi. Vous croyez que les Mogu sont plus forts ? Moi, je dis que nous sommes leur force ! »', `VerifiedBuild`=29981 WHERE (`ID`=66428 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ah ! Le voilà. Il y a plus de quatorze mille ans, l\’ensemble de cette terre était gouverné par un peuple de terrifiants seigneurs de guerre appelés « les Mogu. »', `VerifiedBuild`=29981 WHERE (`ID`=66180 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les mantides vont submerger cette terre et dévorer ceux qui résistent !', `Text1_lang`='Les mantides vont submerger cette terre et dévorer ceux qui résistent !', `VerifiedBuild`=29981 WHERE (`ID`=66122 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Malheur aux usurpateurs pandarens ! Les Mogu ils vont régner de nouveau, et les Zandalari ils auront un nouveau foyer…', `VerifiedBuild`=29981 WHERE (`ID`=65409 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\’est donc chose faite. Et pourtant… combien de ces machines sont cachées sous terre ? Que nous reste-t-il encore à découvrir des sombres secrets des Mogu ?', `VerifiedBuild`=29981 WHERE (`ID`=65195 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les antiques caveaux des Mogu, épargnés par le temps pendant des milliers d\’années. Qui sait quels secrets nous y attendent ?', `VerifiedBuild`=29981 WHERE (`ID`=65168 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='… Je les ai vus de mes propres yeux : des légions mogu qui prenaient d\’assaut le Val. Nous ne sommes pas entraînés pour une bataille rangée !', `VerifiedBuild`=29981 WHERE (`ID`=64888 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Battre en même temps les Zandalari et les Mogu, vous n\’y arriverez pas !', `VerifiedBuild`=29981 WHERE (`ID`=64662 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pourquoi anciens Mogu construire piliers et murs brisés ici ? Pourquoi pas faire bâtiments entiers comme tous les autres ? Mogu idiots.', `VerifiedBuild`=29981 WHERE (`ID`=64405 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Freux veut écraser Mogu, mais villageois pas sécurité ! Si Freux met villageois en sûreté, vous aidez écraser Mogu ?', `VerifiedBuild`=29981 WHERE (`ID`=64404 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Eh bien, tout ça fait froid dans le dos, n\’est-ce pas ? Et ces pièges, ce n\’est pas très accueillant. Ces Mogu auraient bien besoin de quelques conseils en matière de décoration.', `VerifiedBuild`=29981 WHERE (`ID`=64401 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le val ne tombera jamais entre les mains des Mogu !', `Text1_lang`='Le val ne tombera jamais entre les mains des Mogu !', `VerifiedBuild`=29981 WHERE (`ID`=64363 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nos écrits anciens disent que les mantides ont toujours été là. Ils remontent à encore plus loin que les Mogu. D\’où viennent-ils ?', `VerifiedBuild`=29981 WHERE (`ID`=63712 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Ah, très bien ! Vous avez trouvé le safari. C\’est assez délicat de trouver son chemin dans cette jungle sans un certain sens d\’orientation.$b$bCes Mogu n\’arrêtent pas de me mettre des bâtons dans les roues quand je pars à la chasse.', `VerifiedBuild`=29981 WHERE (`ID`=63641 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='La première fois que j\’ai rencontré les Nesingwary, c\’était à Strangleronce. Depuis, je n\’ai pas arrêté de leur tomber dessus. J\’ai enfin gagné ma place dans leur safari !', `VerifiedBuild`=29981 WHERE (`ID`=63638 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='T\’es $gun:une; Mogu ?', `Text1_lang`='T\’es $gun:une; Mogu ?', `VerifiedBuild`=29981 WHERE (`ID`=63515 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Sauroks sont le fléau de cette terre depuis l\’époque des Mogu. Il est impossible de négocier avec eux, mais nous ne cessons d\’essayer ! Nous ne les combattons qu\’en dernier recours.', `VerifiedBuild`=29981 WHERE (`ID`=62712 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Mogu ne peuvent pas revendiquer la gloire qui nous est due sans la force de notre clan !', `VerifiedBuild`=29981 WHERE (`ID`=61563 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='C\’est pas des Gnolls, imbécile. Ouvre un peu les yeux !', `VerifiedBuild`=29981 WHERE (`ID`=61402 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Hé, regardez ! Des Gnolls !', `VerifiedBuild`=29981 WHERE (`ID`=61401 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous osez défier les Mogu ? Alors mourez !', `VerifiedBuild`=29981 WHERE (`ID`=60988 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Le clan Harthak va vous montrer pourquoi ils sont les plus parfaits des Mogu !', `VerifiedBuild`=29981 WHERE (`ID`=60934 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Lors des explorations des îles, votre objectif consiste à récupérer de l\’azérite. La faction adverse y a envoyé des troupes pour faire de même.\n\nLes premiers à en accumuler 6 000 unités l\’emportent.\n\nVous en trouverez sur de puissantes créatures, dans des gisements et coffres au trésor, en aidant des alliés, etc.\n\nLes sources proches apparaissent sur la carte de groupe.\n\nAu bout de quelques minutes, le détecteur d\’azérite est opérationnel et indique toute celle de l\’île.\n\nTemples, vivres et objets peuvent contribuer à retourner la situation en votre faveur.\n\nMais restez sur vos gardes, car certaines créatures insulaires sont redoutables !', `VerifiedBuild`=29981 WHERE (`ID`=60678 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pfff ! Ces Mogu vont devoir faire mieux que ça !$B$BLe Lotus doré défendra le Val… quoi qu\’il lui en coûte.$B$BLes secrets que nous protégeons sont trop précieux… et trop puissants… pour permettre qu\’ils tombent entre les mains des Shao-Tien !', `VerifiedBuild`=29981 WHERE (`ID`=59622 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Aux armes ! Les Mogu attaquent !', `VerifiedBuild`=29981 WHERE (`ID`=59604 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Avez-vous oublié, jeune fille ? Je suis le Sombre Maître ! Je commande les Morts-vivants !', `VerifiedBuild`=29981 WHERE (`ID`=58421 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Dans les temps jadis, les Mogu posaient des petits pièges comme celui-ci pour empêcher les gens de voyager un petit peu partout avec les portails. Ils sont alimentés par les gens coincés dedans et ils ne s\’éteignent pas tant qu\’ils ne sont pas morts.$b$bComme Maman Bâton de Roncier le disait toujours : « Ne jamais mettre sa main dans le portail d\’un inconnu ».', `VerifiedBuild`=29981 WHERE (`ID`=58074 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous croyez qu\’ils sont apparentés aux Murlocs ?', `VerifiedBuild`=29981 WHERE (`ID`=57834 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous ne connaîtrez jamais le secret des Mogu !', `Text1_lang`='Vous ne connaîtrez jamais le secret des Mogu !', `VerifiedBuild`=29981 WHERE (`ID`=57808 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Serviteurs des Mogu !', `Text1_lang`='Serviteurs des Mogu !', `VerifiedBuild`=29981 WHERE (`ID`=57807 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quand les Mogu ont-ils appris à créer des portails magiques ?', `Text1_lang`='Depuis quand les Mogu sont-ils capables de créer des portails magiques ?', `VerifiedBuild`=29981 WHERE (`ID`=57789 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='D\’où diable venaient tous ces Mogu ?', `Text1_lang`='D\’où viennent tous ces Mogu ?', `VerifiedBuild`=29981 WHERE (`ID`=57784 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='$p ! Il y a des Mogu par ici ! Attention !', `Text1_lang`='$p ! Il y a des Mogu par ici ! Attention !', `VerifiedBuild`=29981 WHERE (`ID`=57419 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Peuh, vous vous battez comme deux Gnolls frappés d\’insolation. Distraits, mous, hésitants. Dehors. J\’ai dit DEHORS ! Suivant !', `VerifiedBuild`=29981 WHERE (`ID`=55512 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Battez le grand faucon des plaines blanc !', `VerifiedBuild`=29981 WHERE (`ID`=55125 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='[Démoniaque] Revos ill ok mordanas archim maz naztheros ! Archim xi ante maz-re mishun te Nagas !', `VerifiedBuild`=29981 WHERE (`ID`=54266 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les ombres nous dissimuleront.\n$bJe suis camouflé par cet écran d\’ombre, mais je peux étendre sa magie sur vous.\n$bCela ne nous rendra pas invisibles, mais tant que nous restons à distance de nos ennemis, ils ne nous remarqueront pas.', `VerifiedBuild`=29981 WHERE (`ID`=54224 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Alors, les autres enfants, pas moi, ils ont mis Shin au défi de frapper à la porte de la sorcière de Jade. Mais il voulait pas le faire alors quelqu\’un, mais pas moi, lui a dit même pas cap\’.$b$bShin il s\’est défilé, mais après, quelqu\’un, pas moi, l\’a traité de hozen mouillé. Et quand on te dit ça, personne, même Shin, peut laisser tomber.$b$bIl est allé frapper, mais on n\’a pas vu ce qui s\’est passé. Des monstres de jade nous ont attaqués et on est partis en courant.$b$bJ\’aurais jamais dû traiter Shin de hozen mouillé…', `VerifiedBuild`=29981 WHERE (`ID`=53906 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous croyez que Sayge joue à Cogne-Gnoll ?', `Text1_lang`='Vous croyez que Sayge joue à Cogne-Gnoll ?', `VerifiedBuild`=29981 WHERE (`ID`=53735 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous ne ploierons jamais sous le joug des Mogu !', `Text1_lang`='Nous ne ploierons jamais sous le joug des Mogu !', `VerifiedBuild`=29981 WHERE (`ID`=53566 AND `locale`='frFR');
