UPDATE `broadcast_text_locale` SET `Text_lang`='J\’y étais pas, mais on m\’a dit que Sylvanas était morte aux Pins-Argentés et que ces précieuses Val\’kyrs l\’ont ressuscitée au prix de leurs vies. Vous êtes au courant ?', `VerifiedBuild`=29981 WHERE (`ID`=48712 AND `locale`='frFR');
