UPDATE `broadcast_text_locale` SET `Text_lang`='Le seigneur Krogg m\’a dépêché ici pour verrouiller ce front. Mais il ne m\’a pas encore envoyé de soldats.$B$BRegardez-moi cet endroit ! J\’ai des Ogres. Et le Marteau du crépuscule. Autant dire… rien.', `VerifiedBuild`=29981 WHERE (`ID`=48011 AND `locale`='frFR');
