UPDATE `broadcast_text_locale` SET `Text_lang`='Je peux vous montrer les bases de n\’importe quel métier de récolte ou de production, mais pas plus que ça.\n\nPour dépasser le niveau d\’apprenti, vous devrez aller voir un spécialiste d\’un métier précis.\n\nVous pouvez apprendre jusqu\’à deux métiers : deux de récolte, deux de production, ou un de chaque.\n\nLes métiers secondaires comme l\’archéologie, la cuisine ou la pêche ne comptent pas dans ces deux : vous pouvez en apprendre autant que vous le voulez.', `Text1_lang`='Je peux vous montrer les bases de n\’importe quel métier de récolte ou de production, mais pas plus que ça.\n\nPour dépasser le niveau d\’apprenti, vous devrez aller voir un spécialiste d\’un métier précis.\n\nVous pouvez apprendre jusqu\’à deux métiers : deux de récolte, deux de production, ou un de chaque.\n\nLes métiers secondaires comme l\’archéologie, la cuisine ou la pêche ne comptent pas dans ces deux : vous pouvez en apprendre autant que vous le voulez.', `VerifiedBuild`=29981 WHERE (`ID`=47105 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous nous retrouvons une nouvelle fois, mesdames et messieurs. L\’affrontement épique entre la Vie et la Mort dans le Creuset du carnage ! Pour le round suivant, je vous présente $n contre… un Ogre obèse ? Euh, sérieusement ?! Vous n\’avez pas eu le temps de trouver mieux ? Mais à quoi je vous paie ?', `VerifiedBuild`=29981 WHERE (`ID`=46989 AND `locale`='frFR');
