UPDATE `broadcast_text_locale` SET `Text_lang`='L\’atelier de siège de l\’arène Engloutie est attaqué par la Horde !', `VerifiedBuild`=29981 WHERE (`ID`=33060 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='L\’atelier de siège de l\’arène Engloutie est attaqué par l\’Alliance !', `VerifiedBuild`=29981 WHERE (`ID`=33059 AND `locale`='frFR');
