UPDATE `broadcast_text_locale` SET `Text_lang`='L\’atelier de siège du temple Brisé a été pris par la Horde !', `VerifiedBuild`=29981 WHERE (`ID`=30941 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='L\’atelier de siège de l\’arène Engloutie a été pris par la Horde !', `VerifiedBuild`=29981 WHERE (`ID`=30940 AND `locale`='frFR');
