UPDATE `broadcast_text_locale` SET `Text_lang`='L\’atelier de siège de l\’arène Engloutie a été pris par l\’Alliance !', `VerifiedBuild`=29981 WHERE (`ID`=30938 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\'est MES morceaux, Gnoll !', `VerifiedBuild`=29981 WHERE (`ID`=30514 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Va-t-en, Gnoll !', `VerifiedBuild`=29981 WHERE (`ID`=30512 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Père, je veux me joindre à ton combat contre les Morts-vivants. Je veux me battre ! Je ne peux plus rester à ne rien faire !', `VerifiedBuild`=29981 WHERE (`ID`=29774 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tout comme les chasseurs, les familiers ont aussi une spécialisation. Les animaux féroces, comme les félins, infligent beaucoup de dégâts mais n\’encaissent pas aussi bien. Les animaux tenaces, comme les tortues, sont plus défensifs et peuvent retenir l\’attention d\’un ennemi pendant que vous vous tenez à distance. Les animaux rusés, comme les araignées, savent attaquer aussi bien que défendre et sont particulièrement efficaces sur les champs de bataille et dans les arènes.$B$BChaque familier a une spécialisation par défaut.', `Text1_lang`='Tout comme les chasseurs, les familiers ont aussi une spécialisation. Les animaux féroces, comme les félins, infligent beaucoup de dégâts mais n\’encaissent pas aussi bien. Les animaux tenaces, comme les tortues, sont plus défensifs et peuvent retenir l\’attention d\’un ennemi pendant que vous vous tenez à distance. Les animaux rusés, comme les araignées, savent attaquer aussi bien que défendre et sont particulièrement efficaces sur les champs de bataille et dans les arènes.$B$BChaque familier a une spécialisation par défaut.', `VerifiedBuild`=29981 WHERE (`ID`=29626 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous vouliez éradiquer les Morts-vivants de ces terres ? Goûtez à la vraie puissance du Fléau, et perdez tout espoir !', `VerifiedBuild`=29981 WHERE (`ID`=29507 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Réfléchissez, $n. Pensez au passé. Essayez de vous rappeler Gnomeregan avant ces salauds de Troggs ! Rappelez-vous la douce chaleur d\’une clé à molette, $gpetit frère:petite sœur;. Autrefois, vous étiez $gun champion:une championne; de la gnomité ! Ça, ce n\’est pas vous.', `Text1_lang`='Réfléchissez, $n. Pensez au passé. Essayez de vous rappeler Gnomeregan avant ces salauds de Troggs ! Rappelez-vous la douce chaleur d\’une clé à molette, $gpetit frère:petite sœur;. Autrefois, vous étiez $gun champion:une championne; de la gnomité ! Ça, ce n\’est pas vous.', `VerifiedBuild`=29981 WHERE (`ID`=29352 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Depuis la Couronne de glace, le glacier s\’étend… Et les Morts-vivants sont partout ! Attendez que le professeur apprenne ça !', `VerifiedBuild`=29981 WHERE (`ID`=28699 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous ne pouvons pas tolérer ça. Il faut que les Morts-vivants paient !', `VerifiedBuild`=29981 WHERE (`ID`=28381 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Alors, où j\'en étais ? Ah oui… Donc je lui ai dit : « Mais j\'ai besoin de toi ! J\'ai besoin de toi ! »… Elle m\'a juste ri au nez et s\'est éloignée en ondulant ! C\'est la vérité, $n. Les Nagas peuvent être tellement cruels !', `VerifiedBuild`=29981 WHERE (`ID`=27492 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Dommage que la navre-bière de Coren ne puisse pas soulager plus de gosiers asséchés ! Je sais que c\’est un blasphème de dire ça, mais vraiment, j\’envie les nains sombrefer !', `VerifiedBuild`=29981 WHERE (`ID`=27420 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Et vous croyiez avoir tout vu, tout entendu ? Sous vos yeux ébahis, $n va se frotter à un authentique Furbolg férocement félé des Grisonnes, ici dans la fosse des Conquérants ! Faites vos jeux, mes amis !', `VerifiedBuild`=29981 WHERE (`ID`=27018 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Soldats, je vous ai déjà raconté la fois où j\’ai détruit le viaduc de Thandol ? Ouais, c\’est pas les Sombrefer qui ont fait sauter le pont. C\’est moi !', `Text1_lang`='Soldats, je vous ai déjà raconté la fois où j\’ai détruit le viaduc de Thandol ? Ouais, c\’est pas les Sombrefer qui ont fait sauter le pont. C\’est moi !', `VerifiedBuild`=29981 WHERE (`ID`=26972 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Belgaristrasz dit vrai, le temps va nous manquer !\n\nJe peux vous donner le pouvoir de faire appel à un drake du Vol de bronze. Allez voir Belgaristrasz ou Verdisa si vous préférez invoquer la puissance des vols rouge ou vert.', `VerifiedBuild`=29981 WHERE (`ID`=26952 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Peu importent les Morts-vivants ! Nous passerons par les bois, compagnons !', `VerifiedBuild`=29981 WHERE (`ID`=26713 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous osez envahir la terre des Magnataures ? Scinde-les-os sera content de vous écraser et de garder vos membres comme trophées !', `VerifiedBuild`=29981 WHERE (`ID`=26665 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je sais pourquoi vous êtes là : l\’un de ces idiots de Magnataures des plaines s\’est mêlé de ce qui ne le regardait pas et a réussi à faire intervenir les dragons. Cela vous plaît, de leur obéir comme un gentil petit chien ?', `Text1_lang`='Je sais pourquoi vous êtes là : l\’un de ces idiots de Magnataures des plaines s\’est mêlé de ce qui ne le regardait pas et a réussi à faire intervenir les dragons. Cela vous plaît, de leur obéir comme un gentil petit chien ?', `VerifiedBuild`=29981 WHERE (`ID`=26544 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous n\’êtes pas un Magnataure ! Où avez-vous… trouvé… une telle force ?', `VerifiedBuild`=29981 WHERE (`ID`=26337 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='NOOON ! Ma machine ! Mes bombes ! ANAMARRE ! C\’est fini pour les Harpies !', `VerifiedBuild`=29981 WHERE (`ID`=25926 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='À votre avis, sur quoi on devrait utiliser la bombe ? Sur les Harpies ? Haha ! Attendez… Qu\'est-ce qui se passe ?', `VerifiedBuild`=29981 WHERE (`ID`=25925 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pour moi, tout ça ne ressemblait pas vraiment à une « guérison », et je n\’allais pas rester planté là à écouter parler un robot maboul pendant qu\’il massacrait mes hommes ! $B$BNous avons déguerpi, et c\’est ce qu\’aurait fait tout Gnome un tant soit peu sensé ! En fait, la plupart d\’entre nous ont tout simplement sauté de la plateforme en parachute, mais bon, vous voyez.$B$BPeu d\’entre nous ont réussi à revenir jusqu\’ici, et nous manquons encore d\’effectifs pour nous occuper de tout, entre les Magnataures au nord et le Fléau à l\’est. Sans compter que la Horde vient de s\’installer tranquillement au nord-ouest !', `VerifiedBuild`=29981 WHERE (`ID`=24907 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il se fait appeler le maître des rouages Mécazod. Quand nous sommes arrivés, il était en train de transformer les survivants en machines !$B$BIl nous a accueillis chaleureusement et nous a expliqué qu\’il était l\’un des premiers Gnomes à avoir été créé par quelque chose qu\’il appelait « le Grand Architecte », un gardien des Titans de la légendaire ville d\’Ulduar.$B$BApparemment, le bouchon que mon équipe avait dégagé des tuyaux de pompage, c\’était lui. Il était resté bloqué il y a des milliers d\’années, suite à une panne. C\’était bien notre veine d\’avoir construit la station de pompage juste au-dessus de lui.', `VerifiedBuild`=29981 WHERE (`ID`=24905 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quel genre de petit bout de viande vient par là ? Ce n\’est pas un des Murlocs, je crois.', `VerifiedBuild`=29981 WHERE (`ID`=24435 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Nous avons pris le port, et ce bateau est un joli bonus. Dommage qu\’il ne soit pas encore prêt à naviguer.$B$BEn attendant, j\’ai reçu l\’ordre d\’organiser la liquidation des Nagas de la côte de Verte-branchie.$B$BVous pensez pouvoir m\’aider ?', `VerifiedBuild`=29981 WHERE (`ID`=24151 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Lame de l\’aube, démons et Nagas, numérotez vos abattis ! $n est de retour.', `Text1_lang`='Lame de l\’aube, démons et Nagas, numérotez vos abattis ! $n est de retour.', `VerifiedBuild`=29981 WHERE (`ID`=24088 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Y\’a pas meilleure fête que celle des brasseurs ! Mais il y a un problème : les attaques des nains sombrefer. Il y en a presque toutes les demi-heures !$b$bLes assaillants visent les tonneaux qui dispensent la bière GRATUITE ! Et c\’est vraiment de la bonne bière que les maîtres brasseurs distribuent !$b$bAlors, si vous êtes dans le coin quand les nains Sombrefer débarquent, prêtez main-forte pour protéger la bière GRATUITE.', `VerifiedBuild`=29981 WHERE (`ID`=23839 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il y a quelque chose qui a vraiment énervé les nains sombrefer. Ils débarquent quasiment toutes les demi-heures, cassent tous les tonneaux et repartent !$B$BJ\’imagine que vous vous demandez : « Pourquoi j\’en aurais quelque chose à faire ? »$B$BJe vais vous le dire... Parce que perdre tous ces tonneaux nous empêche de distribuer nos bières gratuites ! Vous avez bien entendu : de la bière gratuite !$B$BAlors si vous êtes dans le coin quand les nains Sombrefer arrivent, prenez une minute pour nous aider à protéger les tonneaux !', `VerifiedBuild`=29981 WHERE (`ID`=23838 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='L\’accident sur la route de Tranchecolline a porté un sacré coup à notre approvisionnement en bière ! Et le fait que les nains sombrefer nous attaquent toutes les heures n\’arrange rien !$b$bDonc si vous voulez nous aider, voici ma proposition. Je vous laisse emprunter un de mes béliers et je vous passe les rênes.$b$bChaque fois que vous me rapporterez un tonneau, je vous donnerai quelques jetons. Je vous laisserai même garder le bélier un peu plus longtemps pour chaque tonneau rapporté !$b$bMAIS, une fois que vous aurez commencé, vous ne pourrez pas y retourner avant le lendemain.\n$b$bVous êtes $gsûr:sûre; de vouloir y aller ?', `Text1_lang`='L\’accident sur la route de Tranchecolline a porté un sacré coup à notre approvisionnement en bière ! Et le fait que les nains sombrefer nous attaquent toutes les heures n\’arrange rien !$b$bDonc si vous voulez nous aider, voici ma proposition. Je vous laisse emprunter un de mes béliers et je vous passe les rênes.$b$bChaque fois que vous me rapporterez un tonneau, je vous donnerai quelques jetons. Je vous laisserai même garder le bélier un peu plus longtemps pour chaque tonneau rapporté !$b$bMAIS, une fois que vous aurez commencé, vous ne pourrez pas y retourner avant le lendemain.\n$b$bVous êtes $gsûr:sûre; de vouloir y aller ?', `VerifiedBuild`=29981 WHERE (`ID`=23544 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Alors vous voulez savoir ce que je recherche ? J\'aime cet esprit… Je recherche quelqu\'un de fort et courageux. Savoir réfléchir, c\'est très bien, mais il faut aussi avoir le muscle qui va avec.$B$BQuand ces casse-pieds de Nains sombrefer attaquent, vous pouvez leur balancer une chope à la tête. Il suffit de la vider et de la lancer. Rien de compliqué.$B$BPour chaque nain dégommé, vous gagnerez une marque. Venez me voir et je vous donnerai un bon en échange de chaque marque.', `Text1_lang`='Alors vous voulez savoir ce que je recherche ? J\'aime cet esprit… Je recherche quelqu\'un de fort et courageux. Savoir réfléchir, c\'est très bien, mais il faut aussi avoir le muscle qui va avec.$B$BQuand ces casse-pieds de Nains sombrefer attaquent, vous pouvez leur balancer une chope à la tête. Il suffit de la vider et de la lancer. Rien de compliqué.$B$BPour chaque nain dégommé, vous gagnerez une marque. Venez me voir et je vous donnerai un bon en échange de chaque marque.', `VerifiedBuild`=29981 WHERE (`ID`=23437 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Combattez sans peur et les Val\’kyrs vous récompenseront !', `VerifiedBuild`=29981 WHERE (`ID`=23063 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quelle faiblesse… Ça ne mérite que la plus indigne des Non-morts. Dans la fosse !', `VerifiedBuild`=29981 WHERE (`ID`=23040 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous sommes encerclés par les Val\’kyrs, frères et sœurs ! Gloire à ceux qui sacrifient tout pour le roi-liche !', `VerifiedBuild`=29981 WHERE (`ID`=22862 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mon cœur noircit… Bientôt, je serai jugé… Digne des Val\’kyrs ! Digne du roi-liche !', `VerifiedBuild`=29981 WHERE (`ID`=22782 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Sauve qui peut ! Voilà les nains sombrefer !', `Text1_lang`='Sauve qui peut ! Voilà les nains sombrefer !', `VerifiedBuild`=29981 WHERE (`ID`=22676 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les nains sombrefer !!!', `Text1_lang`='Les nains sombrefer !!!', `VerifiedBuild`=29981 WHERE (`ID`=22672 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Question de point de vue. Je pense que quelqu\’un a construit les Ogres trop grands. Bon, je ne vais pas te convaincre de bouger, mais ne t\’imagine pas que c\’est définitif !', `VerifiedBuild`=29981 WHERE (`ID`=22592 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous pourriez vous demander : « et maintenant ? » J\’ai la réponse. Pour en apprendre plus sur notre art, vous devez voyager par-delà les mers, jusqu\’à l\’imposante cité de Forgefer. La forge qui s\’y trouve est l\’une des plus grande du monde ! Bengus Forge-Profonde demeure dans la Grande Forge. Il pourra poursuivre votre enseignement.', `VerifiedBuild`=29981 WHERE (`ID`=22573 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tous ils veulent détruire l\’empire amani. Mais on a des amis, maintenant. On est avec les Zandalari. On est gros, maintenant. Vous pouvez pas tous nous arrêter. Le monde tout entier il va se noyer dans le sang !!', `VerifiedBuild`=29981 WHERE (`ID`=22390 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='BIEN PARLÉ ! On va leur montrer pourquoi il ne faut pas se mettre les nains sombrefer à dos !', `VerifiedBuild`=29981 WHERE (`ID`=22389 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La bande de Budd ?$B$BAh, y respecte pas ses troupes, celui-là. Y prendra n\’importe quel type capable de tenir une pelle.$B$BSauf les Morts-vivants. Y peut pas les sacquer. À mon avis, il a peur d\’eux.', `VerifiedBuild`=29981 WHERE (`ID`=22231 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La bande de Budd ?$B$BAh, y respecte pas ses troupes, celui-là. Y prendra n\’importe quel type capable de tenir une pelle.$B$BSauf les Morts-vivants. Y peut pas les sacquer. À mon avis, il a peur d\’eux.', `VerifiedBuild`=29981 WHERE (`ID`=22224 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Personne n\’attendait les nains sombrefer !!', `VerifiedBuild`=29981 WHERE (`ID`=22163 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Je vous recommande chaudement d\’aller voir Sayge pour qu\’il vous prédise votre avenir. Je sais, je sais... c\’est un Gnoll. Mais c\’est un Gnoll très spécial qui a le pouvoir de deviner le futur !$B$BEt nous continuons sans cesse à agrandir la foire avec de nouvelles attractions !', `VerifiedBuild`=29981 WHERE (`ID`=22156 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Qui est cette marchande de fruit qui se permet une manœuvre aussi osée ? Elle a amené un Ogre pour l\’aider.', `Text1_lang`='Qui est cette marchande de fruit qui se permet une manœuvre aussi osée ? Elle a amené un Ogre pour l\’aider.', `VerifiedBuild`=29981 WHERE (`ID`=22057 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Regardez-moi ça ! Près du chariot à fruits, un Ogre. La marchande de fruits prépare la guerre…', `Text1_lang`='Regardez-moi ça ! Près du chariot à fruits, un Ogre. La marchande de fruits prépare la guerre…', `VerifiedBuild`=29981 WHERE (`ID`=22055 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\'est $n, $c de grand renom et $gfrère:sœur; des Ogres de tous les pays !', `VerifiedBuild`=29981 WHERE (`ID`=21946 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='$n, $groi:reine; des Ogres, être ici !', `VerifiedBuild`=29981 WHERE (`ID`=21859 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='$n, $groi:reine; des Ogres, est ici !', `VerifiedBuild`=29981 WHERE (`ID`=21839 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous prenez du bon temps avec nous à Ogri\’la ?$B$BJour et nuit, nos Ogres fabriquent beaucoup de choses. On garde le meilleur pour le vendre à la crème de nos invités, des gens comme vous !$B$BDonc, tant que vous vaquez à vos occupations dans la région, et que vous rendez la montagne plus sûre, pensez à passer de temps à autres pour voir ce que nous avons.$B$BBonne chance dehors, $gmon gars:ma poule;.', `VerifiedBuild`=29981 WHERE (`ID`=21618 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vraiment, on voir vous par ici tout l\’temps !$B$BChu\’a\’lor dire que mini-$r est notre $ghéros:héroïne; !$B$BEt que $n être Ogre comme nous maintenant. Mais Gahk tout brouillé, $n pas assez $ggrand:grande; pour ça !', `VerifiedBuild`=29981 WHERE (`ID`=21603 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='C\'est un honneur pour nous autres Ogres de recevoir l\'aide d\'$gun:une:r; $r tel que vous. Vous maintenez en vie notre espoir d\'un avenir meilleur.$B$BSi seulement nous pouvions aussi nous débarrasser de ces maux de tête. Êtes-vous bien $gsûr:sûre; de ne pas vouloir d\'un de nos fils ?', `VerifiedBuild`=29981 WHERE (`ID`=21595 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Oui, chef. Un Ogre, chef. Mais laissez-nous une chance, chef ! Nous nous entraînons depuis le premier passage de la Garde-ciel sur Ogri\’la, chef !', `VerifiedBuild`=29981 WHERE (`ID`=21449 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tous les Fils de Gruul être morts ! Maintenant, $gnouveau roi:nouvelle reine; conduire tous les Ogres à Ogri\’la !', `VerifiedBuild`=29981 WHERE (`ID`=20957 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Saluez $n, $gnouveau roi:nouvelle reine; des Ogres ! Vive $gle roi:la reine; !', `VerifiedBuild`=29981 WHERE (`ID`=20791 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La violence du tremblement de terre a alerté des Murlocs qui passaient non loin !', `VerifiedBuild`=29981 WHERE (`ID`=20700 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Est-ce que quelqu\’un pourrait aider cet Ogre, qu\’il ne revienne pas ?', `VerifiedBuild`=29981 WHERE (`ID`=20661 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il faut vaincre les fils de Gruul si nous voulons nous débarrasser de nos chaînes et vivre à nouveau en Ogres libres !$B$BNous devons agir discrètement, mais rapidement, si notre résistance clandestine veut avoir une chance de succès.', `VerifiedBuild`=29981 WHERE (`ID`=20645 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='%s appelle un Ogre proche à l\'aide !', `VerifiedBuild`=29981 WHERE (`ID`=20102 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tu pourrais au moins essayer d\’avoir l\’air un peu convaincant.$B$BÉcoute, Nuaar, je ne comptais pas te le dire, mais autant le faire puisque ça te concerne aussi. Maxnar prépare une attaque frontale contre les druides à la sylve Ruuan. Et il compte bien les anéantir.$B$BNotre guerre avec les Ogres Roche\’mok nous pose déjà assez de problèmes, et nous ne pouvons pas nous permettre de tenir deux fronts à la fois. J\’ai mis en place une trêve provisoire avec les arakkoa.$B$BEh bien, qu\’en penses-tu ?', `VerifiedBuild`=29981 WHERE (`ID`=19688 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Si un conseil peut vous aider dans votre combat contre les Ogres, vous l\’aurez !', `VerifiedBuild`=29981 WHERE (`ID`=19620 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Est-ce que d\’autres Ogres parmi vous veulent rejoindre votre ami ?', `VerifiedBuild`=29981 WHERE (`ID`=19036 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='C\'est mon étude de cette culture archaïque qu\'incarnait le clan Sire-tonnerre qui m\'a amenée ici.$B$BLes membres du clan étaient faibles, et succombèrent à l\'illusion de puissance que leur donnait la transformation en Gangr\’orcs par le sang de Mannoroth.$B$BJ\'ai lu tous leurs écrits. Je souhaite tout particulièrement retrouver un artéfact, un tambour, une flèche et une tablette qui furent perdus quand nous avons écrasé les Ogres de Flèchelame pour les repousser jusque dans leur bastion.', `VerifiedBuild`=29981 WHERE (`ID`=18970 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Cesssez de frapper le commandant glissssentaille, Orc ! Je vais parler ! La forrrmule… Elle est dissssimulée dans un coffre à la halte de Glisssentaille… Les Nagas conssservent la clé…', `VerifiedBuild`=29981 WHERE (`ID`=18965 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Hé, n\’ouvrez pas la cage ! D\’accord ?$B$BCes Ogres me tiennent exactement comme je le veux.', `VerifiedBuild`=29981 WHERE (`ID`=18915 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Peuh ! Est-ce que j\’ai l\’air d\’avoir le temps de tailler le bout de gras ?$B$BHein ?$B$BFaites vite. Il y a des Ogres à tuer !', `VerifiedBuild`=29981 WHERE (`ID`=18783 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il ne s\’est pas écoulé longtemps depuis que nous avons dû arracher le contrôle du bastion des Sire-Tonnerre aux Ogres de la région.$B$BVous êtes là pour nous aider à étayer nos défenses ? Je sais que Gor\’drek recherche de l\’aide.', `VerifiedBuild`=29981 WHERE (`ID`=18746 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Nagas attaquent ! Défendez-vous !', `VerifiedBuild`=29981 WHERE (`ID`=18688 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Nagas torturent les esprits de l\’eau. Ils apportent le chaos et la destruction !', `VerifiedBuild`=29981 WHERE (`ID`=18674 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je ne vois pas en quoi cet objet maléfique concerne les Morts-vivants. Nous devons le détruire !', `VerifiedBuild`=29981 WHERE (`ID`=18104 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je ne suis pas sûr que ça convienne. Il ne s\’agit pas de tromper des Troggs.', `VerifiedBuild`=29981 WHERE (`ID`=17438 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il s\’ensuivit de terribles représailles pour la défection des troupes. Illidan et Kael\’thas attaquèrent Shattrath sans relâche.$B$BDes armées d\’Elfes de sang, de Nagas et de Roués déferlaient sur la ville pour se voir repoussées par la puissance des Sha\’tar.$B$BUne chose devint claire pour les naaru : s\’ils voulaient pourchasser la Légion, il faudrait d\’abord vaincre Illidan.', `VerifiedBuild`=29981 WHERE (`ID`=17162 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Accueillez la Lumière en vous, mes amis ! Fermez-vous aux ténèbres…', `VerifiedBuild`=29981 WHERE (`ID`=16775 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Combien faut-il de Kobolds pour changer la mèche d\’une lanterne ?', `VerifiedBuild`=29981 WHERE (`ID`=16657 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pour quoi faire ? Si les démons illidari ne me rattrapent pas, alors ce sera les Nagas du marécage de Zangar.$B$BSe joindre à Illidan et ses alliés n\’aura en fait apporté que l\’esclavage à la plupart des tribus de Roués. Il n\’y a pas d\’espoir pour mon peuple.', `VerifiedBuild`=29981 WHERE (`ID`=16487 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous pensez que les démons respectent les règles ? Ces bêtes sont plus sauvages que les Orcs et plus rusées que les Morts-vivants. N\’essayez pas d\’affronter la Légion selon les principes classiques de la guerre.', `VerifiedBuild`=29981 WHERE (`ID`=16454 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’aime bien le rat brun là-bas. HÉ ! Il m\’a fait signe !', `Text1_lang`='J\’aime bien le rat brun là-bas. HÉ ! Il m\’a fait signe !', `VerifiedBuild`=29981 WHERE (`ID`=16270 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous vous souvenez de la fois où on a pris un Murloc à nageoire rouge, près d\’Elwynn ?', `VerifiedBuild`=29981 WHERE (`ID`=15664 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Oui, tapez-le sans pitié ! Il a le crâne aussi dur qu\’un Ogre !', `VerifiedBuild`=29981 WHERE (`ID`=15575 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Fini le gentil Ogre ! Toi faire mal à Mogor !', `VerifiedBuild`=29981 WHERE (`ID`=15483 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Plus de chance ! Maintenant toi payer Ogre !', `VerifiedBuild`=29981 WHERE (`ID`=15479 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mort aux Ogres !', `Text1_lang`='Mort aux Ogres !', `VerifiedBuild`=29981 WHERE (`ID`=15388 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Ogres ont les clés ! Tuez-les et sortez-moi de là !', `Text1_lang`='Les Ogres ont les clés ! Tuez-les et sortez-moi de là !', `VerifiedBuild`=29981 WHERE (`ID`=15385 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Que ces Ogres soient maudits. Que le Néant les engloutisse. Personne ne nous sauvera donc de ces sauvages ? C\’est la cinquième personne qui est enlevée ces jours-ci.', `VerifiedBuild`=29981 WHERE (`ID`=15371 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Moi massacrouiller autre Ogre cogneguerre ! Moi être Conseil Ombres ! Venir me battre !', `VerifiedBuild`=29981 WHERE (`ID`=15348 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='En Nagrand, bouffe chasser Ogre !', `VerifiedBuild`=29981 WHERE (`ID`=15278 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Hé ! Je ne vous ai pas donné un paquet de peaux, un jour ?$B$BDe toute façon, je suis contente d\’avoir été sauvée des griffes de ce cruel Gankly Poings-Pourris !', `VerifiedBuild`=29981 WHERE (`ID`=15140 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Je suis SI contente que le méchant Gankly Poings-Pourris ait reçu ce qu\’il mérite !', `VerifiedBuild`=29981 WHERE (`ID`=15138 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Je suis SI contente que le méchant Gankly Poings-Pourris ait reçu ce qu\’il mérite ! J\’ai des tas de peaux si vous voulez en donner à Harold.', `VerifiedBuild`=29981 WHERE (`ID`=15113 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Ce que nous avons vu explique ce qui s\’est passé dans la Morte-bourbe. C\’était un lac autrefois. Si nous n\’arrêtons pas les Nagas, tout le marais finira par ressembler à ça !', `VerifiedBuild`=29981 WHERE (`ID`=14714 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Nagas sont même en train de pomper l\’eau de leur propre lac ! Dans quel but peuvent-ils bien faire une chose pareille ?', `VerifiedBuild`=29981 WHERE (`ID`=14712 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='C\'est exactement comme la structure que vous décriviez au lac d\'Umbretourbe. Cela veut-il dire que les Nagas sont en train de pomper l\'eau de tous les lacs du marécage de Zangar ?', `VerifiedBuild`=29981 WHERE (`ID`=14706 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ha ha, Naga tout mou !', `VerifiedBuild`=29981 WHERE (`ID`=14644 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Fhwoor aime les petits sporelins. Eux sauver Fhwoor. Pas les manger.$B$BFhwoor détester Nagas. Fhwoor écraser !', `VerifiedBuild`=29981 WHERE (`ID`=14549 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Chuuuut ! Ne faites pas de bruit, j\’observe des Murlocs.$B$BVivre dans une énorme carapace de tortue est un sacrifice que je suis prêt à faire dans l\’intérêt de la science. Après tout, si les Murlocs me voyaient, ils réagiraient à ma présence et contamineraient mes données !$B$BEn tant que premier Gnome à entrer dans la Ligue des Explorateurs, je vais m\’aventurer courageusement là où nul Nain n\’est jamais allé !', `VerifiedBuild`=29981 WHERE (`ID`=14362 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Jessera, où puis-je trouver un Satyre puant aquatique ?', `Text1_lang`='Jessera, où puis-je trouver un Satyre puant aquatique ?', `VerifiedBuild`=29981 WHERE (`ID`=14284 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Nous devons vaincre ces Satyres, $n. Nous ne souffrirons pas la présence de la Légion sur ces terres !', `VerifiedBuild`=29981 WHERE (`ID`=14032 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Non, ce n\’est pas possible… Il est expliqué que cette créature est devenue volontairement un serviteur de la Légion. Elle s\’est transformée en Satyre, et a reçu la « bénédiction » de la Légion.', `VerifiedBuild`=29981 WHERE (`ID`=14031 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='[Furbolg] Les Furbolgs calmepins n\'oublieront pas votre bravoure de sitôt !', `VerifiedBuild`=29981 WHERE (`ID`=13978 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='C\’est bon de voir un nouveau visage par ici. Nous avons à peine de quoi survivre, et de nombreux ennemis.$B$BNous sommes entourés de partis hostiles : les Satyres au nord, les Orcs du camp de bûcherons à l\’est, et les démons de la colline Gangrefeu.$B$BNous allons reprendre possession de cette zone, même si nous devons y laisser la vie. Et ça a l\’air bien parti pour !', `VerifiedBuild`=29981 WHERE (`ID`=13757 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='EURÊKA ! La recette du flacon de polyvalence renforcée a été découverte !', `Text1_lang`='EURÊKA ! La recette du flacon de polyvalence renforcée a été découverte !', `VerifiedBuild`=29981 WHERE (`ID`=12442 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous servez notre cause de manière exemplaire, $n. Entre les Gnolls des mines de Terradiance et les Trolls momifiés des catacombes des Amani, vous avez, à vous $gseul:seule;, porté de rudes coups à nos ennemis !$B$BNous devrions aller boire un verre ensemble un de ces jours, qu\’en dites-vous ?', `VerifiedBuild`=29981 WHERE (`ID`=12213 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Voilà qui est fâcheux ! Comment pourrais-je ramasser des échantillons de minerai pour les magistères, si les mines sont envahies par de la vermine gnolle ?', `VerifiedBuild`=29981 WHERE (`ID`=12181 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ce n\’est pas pour rire, espèce de ver de terre ! Les objets pestecœur renferment des ténèbres susceptibles de nous détruire tous les deux. C\’est pour ça qu\’ils sont si chers. Tant qu\’à mourir, autant que ce soit dans la peau d\’un homme riche, pas vrai ?$B$BHonnêtement, je ne donnerais pas une goutte de bave de Gnoll pour savoir comment vous mourrez, je veux juste que vous exécutiez mes ordres. Ramenez-moi ce dont j\’ai besoin et nous en profiterons tous les deux. Ou mourez en essayant, mais il me semble que je vous ai déjà expliqué ça…', `VerifiedBuild`=29981 WHERE (`ID`=12044 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='C\’est un affreux gâchis, $c, et c\’est entièrement de ma faute ! On m\’avait bien dit de quitter les quais tant qu\’il en était encore temps. Est-ce que j\’en ai tenu compte ? Non !$B$BQu\’est-ce que je vais faire, maintenant ? Ces Elfes de sang à l\’air malade, les Déshérités, se sont enfuis avec mes marchandises magiques. Je les soupçonne de les avoir mangées. Je suis à peu près sûre que cela veut dire que je ne pourrai pas les récupérer. Ensuite, les Murlocs sinistrécaille ont dérobé le reste de mes produits au milieu de la nuit ! Enfin, pour accumuler toutes les calamités sur la tête d\’une malheureuse marchande honnête, mon équipage a déserté !$B$BJe crois que je vais pleurer…', `VerifiedBuild`=29981 WHERE (`ID`=11697 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Le journal de Jandice Barov est une longue suite de propos délirants sur les Morts-vivants. Vers la fin, vous trouvez quelque chose qui ressemble à un patron. On dirait un sac en gangrétoffe, que les démonistes pourraient utiliser pour conserver des fragments d\’âme. Voulez-vous copier ce patron dans votre propre journal ?', `VerifiedBuild`=29981 WHERE (`ID`=11406 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Plusieurs choses me viennent à l\’esprit. Je vous recommande d\’aller rendre visite à Sayge pour qu\’il vous tire la bonne aventure. Je sais… c\’est un Gnoll. Mais c\’est un Gnoll très spécial, qui possède le don de prédire l\’avenir !\n\nEt la foire s\’agrandit sans cesse, avec toutes sortes de nouvelles attractions !', `VerifiedBuild`=29981 WHERE (`ID`=10782 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Plusieurs choses me viennent à l\’esprit. Je vous recommande d\’aller rendre visite à Sayge pour qu\’il vous tire la bonne aventure. Je sais… c\’est un Gnoll. Mais c\’est un Gnoll très spécial, qui possède le don de prédire l\’avenir !\n\nEt la foire s\’agrandit sans cesse, avec toutes sortes de nouvelles attractions !', `VerifiedBuild`=29981 WHERE (`ID`=10780 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='$n, la garde Foudrepique de la vallée d\’Alterac a plus que jamais besoin de votre aide dans son combat contre le clan Loup-de-Givre. Les occasions de gagner de l\’honneur et de la réputation y sont plus nombreuses que jamais ! Voulez-vous rejoindre la bataille ?', `Text1_lang`='$n, la garde Foudrepique de la vallée d\’Alterac a plus que jamais besoin de votre aide dans son combat contre le clan Loup-de-Givre. Les occasions de gagner de l\’honneur et de la réputation y sont plus nombreuses que jamais ! Voulez-vous rejoindre la bataille ?', `VerifiedBuild`=29981 WHERE (`ID`=10569 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='$n, avez-vous la moindre idée de ce qui se passe dans la vallée d\’Alterac ? Êtes-vous de taille à combattre le clan Loup-de-Givre ?', `VerifiedBuild`=29981 WHERE (`ID`=10526 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Fait froid là-haut ! Vous va dans Quartier royal, vous parle à Grison Demi-Crin.', `Text1_lang`='Fait froid là-haut ! Vous va dans Quartier royal, vous parle à Grison Demi-Crin.', `VerifiedBuild`=29981 WHERE (`ID`=10404 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Des combats inutiles, mais si les Elfes du fort d\’Aile-Argent refusent de parler de paix, quel choix nous laissent-ils ? Pour vous rendre au goulet des Chanteguerres, allez chercher l\’aide de Kergul Hache-sanglante, sur la cime des Chasseurs.', `Text1_lang`='Des combats inutiles, mais si les Elfes du fort d\’Aile-Argent refusent de parler de paix, quel choix nous laissent-ils ? Pour vous rendre au goulet des Chanteguerres, allez chercher l\’aide de Kergul Hache-sanglante, sur la cime des Chasseurs.', `VerifiedBuild`=29981 WHERE (`ID`=10399 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='La garde Foudrepique a besoin de votre aide dans son combat contre le clan Loup-de-Givre, $n. Parlez à Brogun Targe-Pierre sur la Terrasse des guerriers, et il vous aidera à trouver la route de la vallée d\’Alterac. Qu\’Elune soit louée !', `VerifiedBuild`=29981 WHERE (`ID`=10386 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Prend ça, espèce de Harpie pelée ! Hyaa !', `VerifiedBuild`=29981 WHERE (`ID`=10296 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Snivvle est ici ! Snivvle prend la mine de Froide-Dent !', `VerifiedBuild`=29981 WHERE (`ID`=10025 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Construite il y a douze mille ans par un ordre secret de sorciers Elfes de la nuit, l\’antique cité d\’Eldre\’Thalas protégeait les plus précieux secrets arcaniques de la reine Azshara. Elle fut ravagée par la Grande Fracture, mais la plus grande partie de ses merveilleux bâtiments survécut. Les trois quartiers distincts des ruines ont été envahis par toutes sortes de créatures, dont des Bien-nés spectraux, des Satyres répugnants et des Ogres brutaux, ce qui valut un nouveau nom à la cité : Hache-Tripes !', `Text1_lang`='Construite il y a douze mille ans par un ordre secret de sorciers Elfes de la nuit, l\’antique cité d\’Eldre\’Thalas protégeait les plus précieux secrets arcaniques de la reine Azshara. Elle fut ravagée par la Grande Fracture, mais la plus grande partie de ses merveilleux bâtiments survécut. Les trois quartiers distincts des ruines ont été envahis par toutes sortes de créatures, dont des Bien-nés spectraux, des Satyres répugnants et des Ogres brutaux, ce qui valut un nouveau nom à la cité : Hache-Tripes !', `VerifiedBuild`=29981 WHERE (`ID`=9944 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Uldaman est une ancienne cité des Titans, enterrée sous des tonnes de terre depuis la création du monde. Les fouilles menées par les nains ont récemment libéré les premières créations manquées des Titans : les Troggs. Selon les légendes, les Titans estimèrent que l\’expérience des Troggs était un échec. Mais ils firent une nouvelle tentative, qui leur permit de façonner la race des nains. Ces secrets sont inscrits sur les mythiques disques de Norgannon, d\’immenses reliques qui reposent dans les profondeurs de l\’ancienne cité, protégés par des créatures géantes taillées dans la pierre vivante.\n', `Text1_lang`='Uldaman est une ancienne cité des Titans, enterrée sous des tonnes de terre depuis la création du monde. Les fouilles menées par les nains ont récemment libéré les premières créations manquées des Titans : les Troggs. Selon les légendes, les Titans estimèrent que l\’expérience des Troggs était un échec. Mais ils firent une nouvelle tentative, qui leur permit de façonner la race des nains. Ces secrets sont inscrits sur les mythiques disques de Norgannon, d\’immenses reliques qui reposent dans les profondeurs de l\’ancienne cité, protégés par des créatures géantes taillées dans la pierre vivante.\n', `VerifiedBuild`=29981 WHERE (`ID`=9927 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Situé en Dun Morogh, Gnomeregan est la capitale des Gnomes depuis des générations, même si elle a été récemment infestée par des Troggs mutants. Lors de l\’attaque des Troggs, dans une tentative désespérée de représailles, le Grand Bricoleur Mekkanivelle ordonna la vidange d\’urgence des réservoirs de déchets radioactifs de la ville. Même irradiés, les Troggs maintinrent leur siège et les Gnomes furent obligés de trouver refuge dans la cité naine de Forgefer; C\’est là que le Grand Bricoleur recrute des âmes hardies pour aider son peuple à reconquérir sa chère cité.', `Text1_lang`='Situé en Dun Morogh, Gnomeregan est la capitale des Gnomes depuis des générations, même si elle a été récemment infestée par des Troggs mutants. Lors de l\’attaque des Troggs, dans une tentative désespérée de représailles, le Grand Bricoleur Mekkanivelle ordonna la vidange d\’urgence des réservoirs de déchets radioactifs de la ville. Même irradiés, les Troggs maintinrent leur siège et les Gnomes furent obligés de trouver refuge dans la cité naine de Forgefer; C\’est là que le Grand Bricoleur recrute des âmes hardies pour aider son peuple à reconquérir sa chère cité.', `VerifiedBuild`=29981 WHERE (`ID`=9914 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tant qu\’vous restez avec nous, z\’êtes l\’roi. Vous partez, un autre Ogre prend vot\’place. Ça s\’passe comme ça chez les Gordok !', `VerifiedBuild`=29981 WHERE (`ID`=9459 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='On est beaucoup plus propres qu\’les Ogres de Tanaris. Dans le désert, y a du caca d\’Ogre à perte de vue. Pas ici, non non non !', `VerifiedBuild`=29981 WHERE (`ID`=9458 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les autres Ogres étaient crétins d\’vous attaquer, patron ! C\’est pour ça que j\’suis toujours en vie : j\’suis malin !', `VerifiedBuild`=29981 WHERE (`ID`=9457 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Et donc, il n\’y aurait pas dans le coin un coffre qui contiendrait, par exemple, un gantelet que les Ogres gordok considèrent comme un trésor sans prix ?', `Text1_lang`='Et donc, il n\’y aurait pas dans le coin un coffre qui contiendrait, par exemple, un gantelet que les Ogres gordok considèrent comme un trésor sans prix ?', `VerifiedBuild`=29981 WHERE (`ID`=9453 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='OK Fengus, où t\’es ? Tu viens ici et tu m\’expliques que ma mère était une Gnolle pendant que je te donne un coup de marteau sur ta tête à toi !', `VerifiedBuild`=29981 WHERE (`ID`=9424 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Heu… c\’est comme ça que je les ai trouvés. Je voulais montrer au roi qu\’ils étaient dangereux ! Oh, capitaine… j\’ai entendu le garde Fengus vous traiter de gros incapable dont la mère était un Gnoll.', `Text1_lang`='Heu… c\’est comme ça que je les ai trouvés. Je voulais montrer au roi qu\’ils étaient dangereux ! Oh, capitaine… j\’ai entendu le garde Fengus vous traiter de gros incapable dont la mère était un Gnoll !', `VerifiedBuild`=29981 WHERE (`ID`=9423 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Hé, qui c\’est que Fengus traite de fils de Gnoll ? Amenez les prisonniers au roi. C\’t\’une bonne idée d\’les amener avec leurs armes, que l\’roi, y voie bien qu\’y sont dangereux. Moi, j\’vais voir si Fengus ouvre encore sa grand\’ gueule quand j\’la lui aurai cassée menu ! Har !', `VerifiedBuild`=29981 WHERE (`ID`=9416 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les fantômes de Bien-nés que vous voyez dans la cour et les salles d\’Eldre\’Thalas ont été tués, non par les envahisseurs, Ogres gordok ou Satyres, mais par le prince en personne !', `VerifiedBuild`=29981 WHERE (`ID`=9389 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Eh bien, d\’après ce que j\’ai compris en attendant de me faire manger par ces ploucs… vous n\’aurez peut-être pas besoin de tuer tous les Ogres.$B$BL\’autre jour, ils parlaient de la manière dont le roi Gordok a pris le pouvoir. Il a tué le précédent roi et a pris sa place. Ensuite, les sbires du roi – ceux que Gordok a épargnés – lui ont immédiatement juré fidélité.$B$BQui sait ? Les Ogres que vous ne tuerez pas pourraient bien être à vous… au figuré, bien sûr !', `VerifiedBuild`=29981 WHERE (`ID`=9369 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La vallée d\’Alterac appartient au clan Loup-de-Givre depuis des années, et nous ne laisserons pas les nains et leur Alliance s\’y installer ! C\’est pour cela que nous nous battons !$B$BPour reprendre Alterac, il faut vaincre leur général Vanndar Foudrepique à Dun Baldar.$B$BPour la Horde !', `VerifiedBuild`=29981 WHERE (`ID`=9311 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Il y a deux mines dans la vallée : celle de Gouffrefer sur le territoire de l\’Alliance, et celle de Froide-Dent sur le territoire de la Horde. Toutes deux sont riches en minerais. De plus, autrefois, elles ont été utilisées pour conserver du matériel.$B$BÀ présent, la Horde, l\’Alliance et les habitants du coin se les disputent férocement.', `VerifiedBuild`=29981 WHERE (`ID`=9232 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous voyez ce piège cassé, là-bas ? Les Ogres sont trop bêtes pour le réparer. Pourtant, il suffirait de le bricoler un peu ! Si vous le réparez, vous pourrez y attirer Slip\’kik et CRAC ! Un garde ogre piégé !', `VerifiedBuild`=29981 WHERE (`ID`=9220 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous ne pouvez pas battre le clan Loup-de-Givre !', `VerifiedBuild`=29981 WHERE (`ID`=8844 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je suis ici pour raser vos bases, clan Loup-de-Givre. Ivus vous punira pour votre trahison !', `VerifiedBuild`=29981 WHERE (`ID`=8737 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous continuez à parcourir le journal, à la recherche d\’informations susceptibles de vous aider à trouver le coffre perdu.$B$BVers la fin du livre, à l\’encre rouge, vous pouvez voir une note de James inscrite dans la marge : \"La vieille maison près du lac du Cairn... Les Gnolls feront de très bons gardes du corps.\"$B$BIl n\’y a pas de raison de croire que c\’est là que se trouve le coffre, mais il n\’y a pas d\’autre indice.', `VerifiedBuild`=29981 WHERE (`ID`=8658 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Kobolds sont en train de reprendre la mine de Froide-Dent !', `VerifiedBuild`=29981 WHERE (`ID`=8600 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Troggs sont en train de reprendre la mine de Gouffrefer !', `VerifiedBuild`=29981 WHERE (`ID`=8599 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La Horde s\’est emparée de la mine de Froide-Dent ! Ses fournitures vont permettre d\’équiper des renforts !', `VerifiedBuild`=29981 WHERE (`ID`=8596 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='L\’Alliance s\’est emparée de la mine de Froide-Dent ! Ses fournitures vont permettre d\’équiper des renforts !', `VerifiedBuild`=29981 WHERE (`ID`=8594 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La mine de Gouffrefer est tenue par les Troggs.', `VerifiedBuild`=29981 WHERE (`ID`=8593 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='La mine de Gouffrefer est sur le territoire de l\’Alliance, au nord du cimetière Foudrepique.$B$BElle est contrôlée par les Troggs.', `VerifiedBuild`=29981 WHERE (`ID`=8589 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Qui contrôle la mine de Froide-Dent ?', `Text1_lang`='Qui contrôle la mine de Froide-Dent ?', `VerifiedBuild`=29981 WHERE (`ID`=8579 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Livrer ces tonneaux au site de fouilles n\’est pas une tâche facile, mais ils comptent vraiment sur nous pour obtenir la poudre à canon.$B$BNous devons faire tout ce que nous pouvons contre les Sombrefer !', `VerifiedBuild`=29981 WHERE (`ID`=8113 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Merci ! Merci, $gprêtre:prêtresse;. Maintenant je vais pouvoir m\’occuper de ces Gnolls, avec votre puissance pour me soutenir.', `VerifiedBuild`=29981 WHERE (`ID`=7792 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Ne sentez-vous pas l\’angoisse de la Terre-Mère pour ses enfants perdus, les Morts-vivants ? Parlez, vite, $n. Chaque seconde me coûte terriblement. Nous devons les aider à revenir à elle !', `VerifiedBuild`=29981 WHERE (`ID`=7744 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='La première fois que j\’ai vu les Morts-vivants, j\’ai pleuré. Car je ne pouvais concevoir la profondeur de leur douleur ou de leur solitude. La Terre-Mère m\’a alors parlé, elle a chanté dans mon sang. Elle me disait : \"Sauve-les.\"', `VerifiedBuild`=29981 WHERE (`ID`=7743 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Merci ! Merci, $gprêtre:prêtresse;. Maintenant je peux m\’attaquer à ces Murlocs avec la Lumière à mes côtés !', `VerifiedBuild`=29981 WHERE (`ID`=7670 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mon coffre, de conception ingénieuse, nécessite deux clés pour être déverrouillé. Une en argent, une en or. J\’ai confié la clé en argent à mon maître d\’équipage et j\’ai gardé la clé en or.$B$BMais nous étions voués à les perdre… J\’ai perdu la mienne au cours de la deuxième attaque des Nagas, et celle de mon maître d\’équipage a disparu avec lui, un jour plus tard, quand des makruras claquesec nous ont attaqués et l\’ont entraîné sous les flots.$B$BLes Nagas et les makruras ont sûrement les clés. Je suis heureux que ces deux races soient ennemies : elles ne les réuniront pas.', `VerifiedBuild`=29981 WHERE (`ID`=7616 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='J\’ai vu de terribles choses arriver aux Furbolgs au cours des dernières années. Ils ont été des victimes, un peu partout. Mais j\’ignore ce qu\’il est advenu des membres de cette tribu. Ont-ils été atteints par la peste qui ravage Gangrebois ? Ou sont-ils furieux de ce qui est arrivé à leur peuple, naguère pacifique, et ils cherchent désormais à se défendre... Dans tous les cas, la plupart d\’entre eux se montrent hostiles envers ceux qui entrent dans cette région.', `VerifiedBuild`=29981 WHERE (`ID`=7605 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Ha ! À l\’exception de leurs chefs, le Satyre Bazzalan et le démoniste Jergosh, oui, c\’est le cas pour tous ! C\’est pourquoi je leur envoie constamment des adorateurs de Vol\’jin. Cela donne à ce dernier l\’impression que je travaille à éliminer le mal dans sa grande ville. La victoire tient en deux missions : tuer les fidèles de Thrall et tester la force de ceux de la Lame brûlante pour voir s\’ils méritent réellement de se joindre à moi.', `VerifiedBuild`=29981 WHERE (`ID`=7264 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Que pouvez-vous me dire sur les Furbolgs tombe-hiver ?', `Text1_lang`='Que pouvez-vous me dire sur les Furbolgs tombe-hiver ?', `VerifiedBuild`=29981 WHERE (`ID`=7139 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Comment puis-je prouver mon amitié aux Furbolgs grumegueules ?', `Text1_lang`='Comment puis-je prouver mon amitié aux Furbolgs grumegueules ?', `VerifiedBuild`=29981 WHERE (`ID`=7136 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Nous sommes les derniers des Furbolgs... La tribu Grumegueule reste pure, mais les étrangers nous témoignent la même hostilité qu\’aux corrompus. La plupart des gens pensent qu\’aucun Furbolg n\’a pu échapper à la corruption...$B$BFurieux contre ceux qui vous considèrent trop vite comme des ennemis, mes frères attaquent désormais quiconque approche, ils ne font confiance à personne.$B$BMais peut-être, si vous démontrez que vous êtes là en paix, vous considéreront-ils comme un allié ?', `VerifiedBuild`=29981 WHERE (`ID`=7135 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Soyez sur vos gardes ! Les Furbolgs noirbois sont nombreux dans cette zone...', `VerifiedBuild`=29981 WHERE (`ID`=6867 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Bandages, sérums anti-venin et autres, c\'est une nécessité quand on vit dans les plaines. Vira Jeune-Sabot peut vous enseigner ces connaissances. Vous la trouverez dans la grande maison à l\'ouest de Sabot-de-Sang.', `Text1_lang`='Bandages, sérums anti-venin et autres, c\'est une nécessité quand on vit dans les plaines. Vira Jeune-Sabot peut vous enseigner ces connaissances. Vous la trouverez dans la grande maison à l\'ouest de Sabot-de-Sang.', `VerifiedBuild`=29981 WHERE (`ID`=6687 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Tout le monde aux postes de combat ! Les Nagas arrivent !', `VerifiedBuild`=29981 WHERE (`ID`=6372 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous me demandez vraiment où est le Forgeron ? Vous n\’avez pas entendu parler de la Grande Forge !? Nos meilleurs forgerons s\’y rassemblent pour y fourbir leurs armes et armures ! \n\nC\’est juste au milieu de Forgefer, c\’est là que vous trouverez l\’un des plus grands d\’entre eux, Bengus Forge-Profonde.', `Text1_lang`='Vous me demandez vraiment où est le Forgeron ? Vous n\’avez pas entendu parler de la Grande Forge !? Nos meilleurs forgerons s\’y rassemblent pour y fourbir leurs armes et armures ! \n\nC\’est juste au milieu de Forgefer, c\’est là que vous trouverez l\’un des plus grands d\’entre eux, Bengus Forge-Profonde.', `VerifiedBuild`=29981 WHERE (`ID`=6335 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous ne sentez pas la fumée des forges naines ? Ma foi, c\’est Therum Forge-Profonde que vous devez trouver si vous voulez progresser comme forgeron. Il est dans le quartier des Nains, juste au nord de la place de la Cathédrale.', `Text1_lang`='Vous ne sentez pas la fumée des forges naines ? Ma foi, c\’est Therum Forge-Profonde que vous devez trouver si vous voulez progresser comme forgeron. Il est dans le quartier des Nains, juste au nord de la place de la Cathédrale.', `VerifiedBuild`=29981 WHERE (`ID`=6300 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Ah... Des Ogres. J\'avais oublié ces bouffons. Il n\'y a pas de moyen facile de les contourner, alors attendez-vous à bien des combats. Ouvrez l\'œil !', `VerifiedBuild`=29981 WHERE (`ID`=5687 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mais qu\’est-ce que... Personne n\’a le droit de purifier un Furbolg dans MON camp ! Affrontez la colère de Xabraxxis !', `VerifiedBuild`=29981 WHERE (`ID`=5616 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Vous allez devoir patienter un moment, $c, les Nagas sont en train de nous attaquer. Je vous parlerai dès que l\’affaire sera réglée !', `VerifiedBuild`=29981 WHERE (`ID`=5412 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous êtes au bon endroit ! Les gens viennent ici de partout pour apprendre le métier de Forgeron. Vous trouverez Bengus Forge-Profonde jouant du marteau près d\’une enclume au milieu de notre belle ville, près de la Grande Forge elle-même.', `Text1_lang`='Vous êtes au bon endroit ! Les gens viennent ici de partout pour apprendre le métier de Forgeron. Vous trouverez Bengus Forge-Profonde jouant du marteau près d\’une enclume au milieu de notre belle ville, près de la Grande Forge elle-même.', `VerifiedBuild`=29981 WHERE (`ID`=5118 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Enfin ! Mettez-vous les doigts dans les oreilles, votre cerveau a l\’air d\’avoir grossi et j\’ai peur qu\’il se mette à couler.$B$BAlors, les Sombrefer ont épargné sa vie et l\’ont fait prisonnier. Leur chef, un type arrogant et sans pitié nommé Thauris-quelque chose, a gardé Hostefer pour lui. C\’est la dernière fois que j\’ai vu Windsor... *hic* Pardon.', `VerifiedBuild`=29981 WHERE (`ID`=5035 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='$GMonseigneur:Mademoiselle;, pour un peu je croirais que vous êtes une de ces créatures « spéciales ». C\'est comme ça qu\'on appelle les Troggs.$B$BWindsor n\'avait pas de querelle avec les Sombrefer, après tout, le meilleur ami de son arrière-grand-père en était un. C\'est probablement pour ça que les Sombrefer ne l\'ont pas tué à vue.', `VerifiedBuild`=29981 WHERE (`ID`=5031 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Trois cents ? Alors les Sombrefer l\’ont tué avant de le transporter dans les Profondeurs ?', `Text1_lang`='Trois cents ? Alors les Sombrefer l\’ont tué avant de le transporter dans les Profondeurs ?', `VerifiedBuild`=29981 WHERE (`ID`=5030 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Doucement ! J\’y arrive !$B$BAlors il était là, tout droit, avec les tripes et le sang qui dégoulinaient sur lui, et qui apparaît soudain ?$B$BLes Sombrefer ! Vous avez entendu ce que j\’ai dit ??$B$BEt les Sombrefers sont un peu plus solides que ces Orcs rochenoires. Ils étaient préparés. Je veux dire qu\’ils étaient au moins trois cents... *hic* Pardon.', `VerifiedBuild`=29981 WHERE (`ID`=5028 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mais pourquoi voulez-vous qu\’il soit mort ? Qui vous a dit ça ? Pas moi en tout cas.$B$BNul ne sait où il est, c\’est tout.$B$BVous voyez, nous sommes visiblement tombés au milieu d\’une grosse bataille entre les Orcs et les Sombrefer. Les Orcs, en lamentables brutes qu\’ils sont, avaient commencé à poser des pièges et des trucs diaboliques que vous ne comprendriez probablement pas.', `VerifiedBuild`=29981 WHERE (`ID`=5022 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Eh eh... Vous êtes du genre inquisiteur, hein, $n ? Eh bien voilà ce que vous devez faire.$B$BAu nord d\’ici, dans les vieilles ruines, vit un Gnoll déplaisant du nom de Miblon Grondequenotte. Il conserve la seule Evoracine que je connaisse, mais il la surveille jour et nuit. Il paraît qu\’il ne dort jamais !$B$BVous pouvez essayer de le corrompre. Je peux vous vendre de l\’appât qu\’il trouvera appétissant. Placez-le près de lui et ça le distraira assez longtemps pour que vous puissiez prendre l\’Evoracine. Bonne chance !', `VerifiedBuild`=29981 WHERE (`ID`=4828 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Allez voir le marcheur des ombres Zuru dans la vallée des Esprits. Cherchez le lac à l\’ouest, au-dessus de la vallée de la Force.', `Text1_lang`='Allez voir le marcheur des ombres Zuru dans la vallée des Esprits. Cherchez le lac à l\’ouest, au-dessus de la vallée de la Force.', `VerifiedBuild`=29981 WHERE (`ID`=4809 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Oui, cela n\’aurait pu arriver sans cela. Quelqu\’un a dû renseigner les Sombrefer.$B$B<Kharan lève le poing.>$B$BAlors aidez-moi ! Si je sors d\’ici, je dédierai ma vie à retrouver le traître !', `VerifiedBuild`=29981 WHERE (`ID`=4745 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Alors que nous avancions dans les steppes Ardentes, nous sommes tombés dans une embuscade. Ils devaient être une centaine... Des nains sombrefer ! Ils sortaient des murs, de derrière les rochers des steppes, de chaque fissure, de chaque ouverture... Ils nous ont submergés, et les gardes et les héros qui s\'étaient engagés à nos côtés ont ployé sous le nombre.$B$BUne chose était claire : c\'était une embuscade parfaitement organisée. C\'est comme s\'ils savaient à l\'avance tout ce que nous allions faire...', `VerifiedBuild`=29981 WHERE (`ID`=4743 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Préparez-vous ! Les Nagas ne tarderont pas à pousser leur avantage quand ils sauront que nous sommes en vie.', `VerifiedBuild`=29981 WHERE (`ID`=4658 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Salutations, $r. Je suis Franclorn Le Forgebusier. Vous êtes ici pour en savoir plus sur le pic et les Sombrefer ?', `VerifiedBuild`=29981 WHERE (`ID`=4646 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je ne comprends pas les officiels de Hurlevent. Envoyer comme ça notre armée à l\’autre bout du monde… Alors que l\’ennemi est à nos portes !$B$BAvec les voleurs qui viennent de la marche de l\’Ouest et les Gnolls qui dévalent de l\’est et de l\’ouest, c\’est un miracle que Hurlevent ne soit pas encore assiégé.', `VerifiedBuild`=29981 WHERE (`ID`=4637 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Aidez-nous ! <La relique tombe en poussière. La vision de huit nains sombrefer en plein rituel étrange emplit votre cerveau.>', `VerifiedBuild`=29981 WHERE (`ID`=4597 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Capitaine, ils arrivent ! Les Nagas arrivent !', `Text1_lang`='Capitaine, ils arrivent ! Les Nagas arrivent !', `VerifiedBuild`=29981 WHERE (`ID`=4580 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Beau travail ! Je vais faire exploser les explosifs de façon à ce que les Troggs ne puissent plus remonter à la surface.', `VerifiedBuild`=29981 WHERE (`ID`=4329 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Encore des Troggs ! Repoussez-les, le temps que je prépare les explosifs !', `VerifiedBuild`=29981 WHERE (`ID`=4209 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Bravo ! Sans vous, je n\'aurais pas pu contrecarrer cette vague de Troggs.', `VerifiedBuild`=29981 WHERE (`ID`=4206 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Louée soit la lumière, vous êtes là ! J\’accepterais même l\’aide d\’un Ogre à deux têtes au point où j\’en suis.\n\nLa cité a été envahie par des Troggs ! Les tentatives pour les éradiquer ont provoqué une contamination de masse. Mais il y a de l\’espoir.\n\nNos scientifiques, qui ont été évacués à Forgefer, travaillent sur un remède. Pendant ce temps, si vous pouviez m\’aider à stopper l\’invasion des Troggs, peut-être que la cité pourrait être reprise.', `VerifiedBuild`=29981 WHERE (`ID`=4083 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Allons voir si nous pouvons trouver d\'où viennent ces Troggs... et mettre un terme à cette invasion !', `VerifiedBuild`=29981 WHERE (`ID`=4051 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Les Gordunni sont une grande tribu d\’Ogres qui contrôle une grande partie de la forêt en Féralas. Leur magie noire s\’insinue dans les éléments tout autour d\’elle, nuisant à l\’environnement et aux créatures qui le peuplent.$B$BSi vous décidez de vous rendre en Féralas, faites attention à ces Ogres ; ils sont méchants et possèdent une magie noire puissante.', `VerifiedBuild`=29981 WHERE (`ID`=3924 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Hé, vous là-bas ! J\’ai une proposition pour une personne comme vous, qui cherche l\’aventure, si vous le voulez !$B$BAvec mon invention, le Super Œuf-O-Matic, je travaille dur en aidant les druides dans leur campagne pour sauver les hippogriffes. Les oiseaux sont affectés par la mauvaise influence des Ogres gordunni qui habitent les ruines de Féralas, et leur nombre est en chute libre.$B$BJe collecte différents types d\’œufs. Voulez-vous bien en ramasser pour moi ?', `VerifiedBuild`=29981 WHERE (`ID`=3813 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Vous êtes médecin, vous aussi ? Je me ferais un plaisir de vous enseigner quelques techniques utiles.', `Text1_lang`='Vous êtes médecin, vous aussi ? Je me ferais un plaisir de vous enseigner quelques techniques utiles.', `VerifiedBuild`=29981 WHERE (`ID`=3356 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Salutations. Cherchez-vous à en apprendre davantage sur l\’art de la guerre ?', `VerifiedBuild`=29981 WHERE (`ID`=3353 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Troggs ?! Est-ce que les Troggs dont vous avez parlé sont les mêmes que ceux qui peuplent le monde aujourd\’hui ?', `Text1_lang`='Les Troggs ?! Est-ce que les Troggs dont vous avez parlé sont les mêmes que ceux qui peuplent le monde aujourd\’hui ?', `VerifiedBuild`=29981 WHERE (`ID`=3197 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Mes excuses, je suis dans l\’incapacité de traiter votre référence chronologique par rapport à l\’enregistrement de cette donnée.$B$BLe Trogg conserve la composition de diverses pierres d\’Azeroth, mais la perte des facultés cognitives rend cette variante inacceptable pour les Créateurs.$B$BLe Trogg procrée selon une biomasse standard. Par défaut, il consomme de la roche ou n\’importe quoi d\’autre, Troggs inclus. Le cannibalisme est jugé inacceptable par les Créateurs.', `VerifiedBuild`=29981 WHERE (`ID`=3182 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les Troggs... ils ne cessent de nous envahir. Qu\’ils meurent ! Qu\’ils meurent !', `Text1_lang`='Les Troggs... ils ne cessent de nous envahir. Qu\’ils meurent ! Qu\’ils meurent !', `VerifiedBuild`=29981 WHERE (`ID`=2423 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Sentez le pouvoir des nains sombrefer !', `Text1_lang`='Sentez le pouvoir des nains sombrefer !', `VerifiedBuild`=29981 WHERE (`ID`=1936 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Paval Reethe ! Je vous trouve enfin. Et vous fréquentez des Ogres maintenant ? N\’ayez crainte, même les déserteurs et les traîtres bénéficient d\’une certaine pitié.', `VerifiedBuild`=29981 WHERE (`ID`=1714 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Pas un pas de plus, Ogre !', `VerifiedBuild`=29981 WHERE (`ID`=1710 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je... Bon, j\’ai peut-être pris une chose ou deux dans l\’auberge... mais qu\’est-ce que ça peut faire à un Ogre ?', `VerifiedBuild`=29981 WHERE (`ID`=1708 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Moi toujours chef des Ogres. Ho !', `VerifiedBuild`=29981 WHERE (`ID`=1514 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Quand fera-t-on quelque chose contre les Morts-vivants ?', `VerifiedBuild`=29981 WHERE (`ID`=961 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Prends ça ! Les Sèches-Moustaches vaincront !', `VerifiedBuild`=29981 WHERE (`ID`=814 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Si je recevais une petite pièce pour chacune de vos bonnes actions, je serais un riche Kobold !', `VerifiedBuild`=29981 WHERE (`ID`=801 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Je ne veux pas servir de repas à un Ogre ! Je vous en supplie, sauvez-moi !', `VerifiedBuild`=29981 WHERE (`ID`=787 AND `locale`='frFR');
