UPDATE `broadcast_text_locale` SET `Text_lang`='Cette terre appartient aux Nains sombrefer. Prépare-toi à voir l\’au-delà, $c !', `VerifiedBuild`=29981 WHERE (`ID`=455 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text_lang`='Les nains sombrefer reprendront possession des terres qui leur reviennent de droit !', `VerifiedBuild`=29981 WHERE (`ID`=450 AND `locale`='frFR');
UPDATE `broadcast_text_locale` SET `Text1_lang`='Tout-doux ! Tout-Doux, arrête de courir !', `VerifiedBuild`=29981 WHERE (`ID`=162 AND `locale`='frFR');
